package alphametics

import (
	"errors"
	"strings"
	"unicode"
)

// Helper to extract unique letters and words from the puzzle
func parsePuzzle(puzzle string) (words []string, result string, letters []rune, leadingLetters map[rune]bool, err error) {
	// Remove spaces
	puzzle = strings.ReplaceAll(puzzle, " ", "")
	parts := strings.Split(puzzle, "==")
	if len(parts) != 2 {
		return nil, "", nil, nil, errors.New("invalid puzzle: must contain '=='")
	}
	left := parts[0]
	right := parts[1]

	words = strings.Split(left, "+")
	result = right

	// Collect all unique letters and leading letters
	letterSet := make(map[rune]bool)
	leadingLetters = make(map[rune]bool)
	for _, w := range append(words, result) {
		for i, r := range w {
			if !unicode.IsUpper(r) {
				return nil, "", nil, nil, errors.New("invalid puzzle: only uppercase letters allowed")
			}
			letterSet[r] = true
			if i == 0 && len(w) > 1 {
				leadingLetters[r] = true
			}
		}
	}
	letters = make([]rune, 0, len(letterSet))
	for r := range letterSet {
		letters = append(letters, r)
	}
	if len(letters) > 10 {
		return nil, "", nil, nil, errors.New("too many unique letters (max 10)")
	}
	return words, result, letters, leadingLetters, nil
}

// Helper to convert a word to a number using a mapping
func wordToNumber(word string, mapping map[rune]int) (int, error) {
	n := 0
	for _, r := range word {
		d, ok := mapping[r]
		if !ok {
			return 0, errors.New("incomplete mapping")
		}
		n = n*10 + d
	}
	return n, nil
}

// Backtracking search for a valid mapping
func solveRecursive(words []string, result string, letters []rune, leadingLetters map[rune]bool, mapping map[rune]int, usedDigits map[int]bool, idx int) (map[rune]int, bool) {
	if idx == len(letters) {
		// All letters assigned, check if solution is valid
		for _, w := range append(words, result) {
			if len(w) > 1 && mapping[rune(w[0])] == 0 {
				return nil, false // leading zero
			}
		}
		sum := 0
		for _, w := range words {
			n, _ := wordToNumber(w, mapping)
			sum += n
		}
		res, _ := wordToNumber(result, mapping)
		if sum == res {
			// Copy mapping to avoid mutation
			final := make(map[rune]int)
			for k, v := range mapping {
				final[k] = v
			}
			return final, true
		}
		return nil, false
	}

	letter := letters[idx]
	for d := 0; d <= 9; d++ {
		if usedDigits[d] {
			continue
		}
		if d == 0 && leadingLetters[letter] {
			continue // no leading zero
		}
		mapping[letter] = d
		usedDigits[d] = true
		if m, ok := solveRecursive(words, result, letters, leadingLetters, mapping, usedDigits, idx+1); ok {
			return m, true
		}
		delete(mapping, letter)
		usedDigits[d] = false
	}
	return nil, false
}

func Solve(puzzle string) (map[string]int, error) {
	words, result, letters, leadingLetters, err := parsePuzzle(puzzle)
	if err != nil {
		return nil, err
	}
	mapping, ok := solveRecursive(words, result, letters, leadingLetters, make(map[rune]int), make(map[int]bool), 0)
	if !ok {
		return nil, errors.New("no solution")
	}
	// Convert rune map to string map
	out := make(map[string]int)
	for k, v := range mapping {
		out[string(k)] = v
	}
	return out, nil
}
