#[derive(Debug, PartialEq, Eq)]
pub enum Error {
    IncompleteNumber,
}

/// Convert a list of numbers to a stream of bytes encoded with variable length encoding.
pub fn to_bytes(values: &[u32]) -> Vec<u8> {
    let mut result = Vec::new();
    for &value in values {
        let mut bytes = Vec::new();
        let mut n = value;
        // Always push at least one byte
        loop {
            let byte = (n & 0x7F) as u8;
            bytes.push(byte);
            n >>= 7;
            if n == 0 {
                break;
            }
        }
        // Set the continuation bit for all but the last byte
        for i in (1..bytes.len()).rev() {
            bytes[i] |= 0x80;
        }
        // Reverse to get most significant group first
        result.extend(bytes.iter().rev());
    }
    result
}

/// Given a stream of bytes, extract all numbers which are encoded in there.
pub fn from_bytes(bytes: &[u8]) -> Result<Vec<u32>, Error> {
    let mut result = Vec::new();
    let mut value: u32 = 0;
    let mut bytes_read = 0;

    for &byte in bytes {
        value = (value << 7) | (byte & 0x7F) as u32;
        bytes_read += 1;
        if (byte & 0x80) == 0 {
            result.push(value);
            value = 0;
            bytes_read = 0;
        } else if bytes_read > 5 {
            // More than 5 bytes for a u32 is invalid (since 5*7=35 > 32 bits)
            // But the problem doesn't specify error for overflow, so we just keep going
            // (could add an error if desired)
        }
    }
    if bytes_read != 0 {
        // If we finished with a partial number, it's incomplete
        return Err(Error::IncompleteNumber);
    }
    Ok(result)
}
