        self.rolls = []

    def roll(self, pins):
        if not isinstance(pins, int):
            raise ValueError("pins must be an integer")
        if pins < 0 or pins > 10:
            raise ValueError("pins must be between 0 and 10")
        # Check for invalid pin count in a frame (except 10th frame and fill balls)
        if len(self.rolls) < 18:
            # Not in 10th frame yet
            if len(self.rolls) % 2 == 1 and self.rolls[-1] != 10:
                if self.rolls[-1] + pins > 10:
                    raise ValueError("pin count exceeds pins on the lane")
        elif len(self.rolls) < 21:
            # 10th frame or fill balls
            frame_start = 18
            tenth = self.rolls[frame_start:]
            if len(tenth) == 1:
                if tenth[0] != 10 and tenth[0] + pins > 10:
                    raise ValueError("pin count exceeds pins on the lane in 10th frame")
            if len(tenth) == 2:
                # If first was strike, second can be up to 10, but if not, sum must be <= 10 unless first was strike
                if tenth[0] == 10:
                    # second and third can be any, but if second is not strike, sum with third must be <= 10
                    if tenth[1] != 10 and tenth[1] + pins > 10:
                        raise ValueError("invalid fill balls")
                elif tenth[0] + tenth[1] == 10:
                    # spare, third can be up to 10
                    pass
                elif tenth[0] + tenth[1] < 10:
                    raise IndexError("cannot throw bonus with an open tenth frame")
        else:
            raise IndexError("cannot roll after game is over")
        self.rolls.append(pins)

    def score(self):
        score = 0
        roll_index = 0
        for frame in range(10):
            if roll_index >= len(self.rolls):
                raise ValueError("not enough rolls to score the game")
            if self.rolls[roll_index] == 10:
                # Strike
                if roll_index + 2 >= len(self.rolls):
                    raise ValueError("not enough rolls to score a strike")
                score += 10 + self.rolls[roll_index + 1] + self.rolls[roll_index + 2]
                roll_index += 1
            elif roll_index + 1 < len(self.rolls):
                frame_sum = self.rolls[roll_index] + self.rolls[roll_index + 1]
                if frame_sum > 10:
                    raise ValueError("pin count exceeds pins on the lane")
                if frame_sum == 10:
                    # Spare
                    if roll_index + 2 >= len(self.rolls):
                        raise ValueError("not enough rolls to score a spare")
                    score += 10 + self.rolls[roll_index + 2]
                else:
                    # Open frame
                    score += frame_sum
                roll_index += 2
            else:
                raise ValueError("not enough rolls to score the game")
        # Check for extra rolls after 10th frame
        if roll_index < len(self.rolls):
            # Only valid if they are fill balls for 10th frame
            tenth_start = 18
            tenth = self.rolls[tenth_start:]
            if len(tenth) == 2:
                if tenth[0] == 10 or sum(tenth[:2]) == 10:
                    if len(self.rolls) != 21:
                        raise ValueError("invalid number of fill balls")
                elif sum(tenth[:2]) < 10:
                    if len(self.rolls) != 20:
                        raise IndexError("cannot throw bonus with an open tenth frame")
            elif len(tenth) == 3:
                if tenth[0] == 10 or sum(tenth[:2]) == 10:
                    if len(self.rolls) != 21:
                        raise ValueError("invalid number of fill balls")
                else:
                    raise IndexError("cannot throw bonus with an open tenth frame")
            elif len(tenth) > 3:
                raise ValueError("too many rolls in the game")
        return score
