package alphametics

import (
	"errors"
	"strings"
	"unicode"
)

// Helper to extract unique letters and leading letters from the puzzle
func extractLetters(words []string) ([]rune, map[rune]bool) {
	lettersMap := make(map[rune]bool)
	leading := make(map[rune]bool)
	for _, word := range words {
		for i, r := range word {
			lettersMap[r] = true
			if i == 0 {
				leading[r] = true
			}
		}
	}
	letters := make([]rune, 0, len(lettersMap))
	for r := range lettersMap {
		letters = append(letters, r)
	}
	return letters, leading
}

// Helper to convert a word to a number using a mapping
func wordToNumber(word string, mapping map[rune]int) int {
	num := 0
	for _, r := range word {
		num = num*10 + mapping[r]
	}
	return num
}

// Backtracking solver
func solveRecursive(words []string, result string, letters []rune, leading map[rune]bool, mapping map[rune]int, used map[int]bool, idx int) (map[rune]int, bool) {
	if idx == len(letters) {
		// All letters assigned, check if solution is valid
		for _, word := range words {
			if mapping[rune(word[0])] == 0 && len(word) > 1 {
				return nil, false
			}
		}
		if mapping[rune(result[0])] == 0 && len(result) > 1 {
			return nil, false
		}
		sum := 0
		for _, word := range words {
			sum += wordToNumber(word, mapping)
		}
		if sum == wordToNumber(result, mapping) {
			// Copy mapping to return
			solution := make(map[rune]int)
			for k, v := range mapping {
				solution[k] = v
			}
			return solution, true
		}
		return nil, false
	}

	letter := letters[idx]
	for d := 0; d <= 9; d++ {
		if used[d] {
			continue
		}
		if d == 0 && leading[letter] {
			continue
		}
		mapping[letter] = d
		used[d] = true
		if sol, ok := solveRecursive(words, result, letters, leading, mapping, used, idx+1); ok {
			return sol, true
		}
		delete(mapping, letter)
		used[d] = false
	}
	return nil, false
}

func Solve(puzzle string) (map[string]int, error) {
	// Remove spaces
	puzzle = strings.ReplaceAll(puzzle, " ", "")
	// Split into left and right of ==
	parts := strings.Split(puzzle, "==")
	if len(parts) != 2 {
		return nil, errors.New("invalid puzzle format")
	}
	left := parts[0]
	right := parts[1]

	// Split left by +
	leftWords := strings.Split(left, "+")
	words := make([]string, 0, len(leftWords))
	for _, w := range leftWords {
		if w != "" {
			words = append(words, w)
		}
	}
	result := right

	// Collect all unique letters and leading letters
	allWords := append(words, result)
	letters, leading := extractLetters(allWords)
	if len(letters) > 10 {
		return nil, errors.New("too many unique letters")
	}

	// Only allow uppercase letters
	for _, l := range letters {
		if !unicode.IsUpper(l) {
			return nil, errors.New("only uppercase letters allowed")
		}
	}

	// Backtracking search
	mapping := make(map[rune]int)
	used := make(map[int]bool)
	solution, ok := solveRecursive(words, result, letters, leading, mapping, used, 0)
	if !ok {
		return nil, errors.New("no solution")
	}

	// Convert rune->int map to string->int map
	resultMap := make(map[string]int)
	for k, v := range solution {
		resultMap[string(k)] = v
	}
	return resultMap, nil
}
