import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Map;

class BuildTree {

    TreeNode buildTree(ArrayList<Record> records) throws InvalidRecordsException {
        // Sort records by recordId
        records.sort(Comparator.comparing(Record::getRecordId));

        int n = records.size();
        if (n == 0) {
            return null;
        }

        // Validate records
        for (int i = 0; i < n; i++) {
            Record record = records.get(i);
            int id = record.getRecordId();
            int parentId = record.getParentId();

            if (id != i) {
                throw new InvalidRecordsException("Invalid Records");
            }
            if (id == 0) {
                if (parentId != 0) {
                    throw new InvalidRecordsException("Invalid Records");
                }
            } else {
                if (parentId >= id) {
                    throw new InvalidRecordsException("Invalid Records");
                }
            }
        }

        // Build nodes and map them by id
        Map<Integer, TreeNode> nodeMap = new HashMap<>();
        for (Record record : records) {
            nodeMap.put(record.getRecordId(), new TreeNode(record.getRecordId()));
        }

        TreeNode root = null;

        // Build tree structure
        for (Record record : records) {
            int id = record.getRecordId();
            int parentId = record.getParentId();
            TreeNode node = nodeMap.get(id);

            if (id == 0) {
                root = node;
            } else {
                TreeNode parent = nodeMap.get(parentId);
                parent.getChildren().add(node);
            }
        }

        return root;
    }

}
