import java.util.*;

class ZebraPuzzle {
    private static final int HOUSE_COUNT = 5;

    private enum Color { RED, GREEN, IVORY, YELLOW, BLUE }
    private enum Nationality { ENGLISHMAN, SPANIARD, UKRAINIAN, NORWEGIAN, JAPANESE }
    private enum Pet { DOG, SNAILS, FOX, HORSE, ZEBRA }
    private enum Drink { COFFEE, TEA, MILK, ORANGE_JUICE, WATER }
    private enum Hobby { DANCING, PAINTING, READING, FOOTBALL, CHESS }

    private static class House {
        Color color;
        Nationality nationality;
        Pet pet;
        Drink drink;
        Hobby hobby;

        House() {}

        House(House other) {
            this.color = other.color;
            this.nationality = other.nationality;
            this.pet = other.pet;
            this.drink = other.drink;
            this.hobby = other.hobby;
        }
    }

    private List<House> solution = null;

    String getWaterDrinker() {
        solve();
        for (House h : solution) {
            if (h.drink == Drink.WATER) {
                return toString(h.nationality);
            }
        }
        return null;
    }

    String getZebraOwner() {
        solve();
        for (House h : solution) {
            if (h.pet == Pet.ZEBRA) {
                return toString(h.nationality);
            }
        }
        return null;
    }

    private void solve() {
        if (solution != null) return;

        List<List<Color>> colorPerms = permutations(Color.values());
        List<List<Nationality>> natPerms = permutations(Nationality.values());
        List<List<Pet>> petPerms = permutations(Pet.values());
        List<List<Drink>> drinkPerms = permutations(Drink.values());
        List<List<Hobby>> hobbyPerms = permutations(Hobby.values());

        // Try all possible assignments, but prune as early as possible
        for (List<Color> colors : colorPerms) {
            if (!constraint6(colors)) continue; // green right of ivory
            for (List<Nationality> nats : natPerms) {
                if (!constraint2(colors, nats)) continue; // Englishman in red
                if (!constraint10(nats)) continue; // Norwegian in first
                if (!constraint15(colors, nats)) continue; // Norwegian next to blue
                for (List<Pet> pets : petPerms) {
                    if (!constraint3(nats, pets)) continue; // Spaniard owns dog
                    for (List<Drink> drinks : drinkPerms) {
                        if (!constraint4(colors, drinks)) continue; // green drinks coffee
                        if (!constraint5(nats, drinks)) continue; // Ukrainian drinks tea
                        if (!constraint9(drinks)) continue; // milk in middle
                        for (List<Hobby> hobbies : hobbyPerms) {
                            if (!constraint7(pets, hobbies)) continue; // snails owner dances
                            if (!constraint8(colors, hobbies)) continue; // yellow is painter
                            if (!constraint11(pets, hobbies)) continue; // reading next to fox
                            if (!constraint12(hobbies, pets)) continue; // painter next to horse
                            if (!constraint13(hobbies, drinks)) continue; // football drinks OJ
                            if (!constraint14(nats, hobbies)) continue; // Japanese plays chess

                            // All constraints satisfied
                            List<House> houses = new ArrayList<>();
                            for (int i = 0; i < HOUSE_COUNT; i++) {
                                House h = new House();
                                h.color = colors.get(i);
                                h.nationality = nats.get(i);
                                h.pet = pets.get(i);
                                h.drink = drinks.get(i);
                                h.hobby = hobbies.get(i);
                                houses.add(h);
                            }
                            solution = houses;
                            return;
                        }
                    }
                }
            }
        }
    }

    // Constraint helpers

    // 2. The Englishman lives in the red house.
    private boolean constraint2(List<Color> colors, List<Nationality> nats) {
        for (int i = 0; i < HOUSE_COUNT; i++) {
            if (nats.get(i) == Nationality.ENGLISHMAN && colors.get(i) != Color.RED) return false;
        }
        return true;
    }

    // 3. The Spaniard owns the dog.
