    private <T> void permute(T[] arr, int k, List<List<T>> result) {
        if (k == arr.length) {
            result.add(new ArrayList<>(Arrays.asList(arr.clone())));
        } else {
            for (int i = k; i < arr.length; i++) {
                swap(arr, i, k);
                permute(arr, k + 1, result);
                swap(arr, i, k);
            }
        }
    }

    private <T> void swap(T[] arr, int i, int j) {
        T tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

