import java.util.List;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

class BookStore {

    private static final double BOOK_PRICE = 8.0;
    private static final double[] DISCOUNTS = {0.0, 0.0, 0.05, 0.10, 0.20, 0.25};

    double calculateBasketCost(List<Integer> books) {
        if (books == null || books.isEmpty()) {
            return 0.0;
        }

        // Count the number of each book
        int[] counts = new int[5];
        for (int book : books) {
            if (book < 1 || book > 5) {
                throw new IllegalArgumentException("Book numbers must be between 1 and 5.");
            }
            counts[book - 1]++;
        }

        // Use memoization to avoid recalculating the same state
        Map<String, Double> memo = new HashMap<>();
        return minCost(counts, memo);
    }

    private double minCost(int[] counts, Map<String, Double> memo) {
        // Create a key for memoization
        String key = countsToString(counts);
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        // If all counts are zero, cost is zero
        boolean allZero = true;
        for (int c : counts) {
            if (c != 0) {
                allZero = false;
                break;
            }
        }
        if (allZero) {
            return 0.0;
        }

        double min = Double.MAX_VALUE;

        // Try all possible group sizes (from 5 down to 1)
        for (int groupSize = 5; groupSize >= 1; groupSize--) {
            // Can we form a group of this size?
            List<Integer> idxs = new ArrayList<>();
            for (int i = 0; i < counts.length; i++) {
                if (counts[i] > 0) {
                    idxs.add(i);
                }
            }
            if (idxs.size() < groupSize) {
                continue;
            }

            // Generate all combinations of groupSize books
            List<List<Integer>> combinations = combinations(idxs, groupSize);
            for (List<Integer> combo : combinations) {
                int[] newCounts = counts.clone();
                for (int idx : combo) {
                    newCounts[idx]--;
                }
                double groupCost = groupSize * BOOK_PRICE * (1.0 - DISCOUNTS[groupSize]);
                double totalCost = groupCost + minCost(newCounts, memo);
                if (totalCost < min) {
                    min = totalCost;
                }
            }
        }

        memo.put(key, min);
        return min;
    }

    // Helper to convert counts array to a string key for memoization
    private String countsToString(int[] counts) {
        StringBuilder sb = new StringBuilder();
        for (int c : counts) {
            sb.append(c).append(',');
        }
        return sb.toString();
    }

    // Helper to generate all combinations of k elements from a list
    private List<List<Integer>> combinations(List<Integer> list, int k) {
        List<List<Integer>> result = new ArrayList<>();
        combineHelper(list, k, 0, new ArrayList<>(), result);
        return result;
    }

    private void combineHelper(List<Integer> list, int k, int start, List<Integer> current, List<List<Integer>> result) {
        if (current.size() == k) {
            result.add(new ArrayList<>(current));
            return;
        }
        for (int i = start; i < list.size(); i++) {
            current.add(list.get(i));
            combineHelper(list, k, i + 1, current, result);
            current.remove(current.size() - 1);
        }
    }
}
