class FoodChain {

    private static final String[] ANIMALS = {
        "fly",
        "spider",
        "bird",
        "cat",
        "dog",
        "goat",
        "cow",
        "horse"
    };

    private static final String[] COMMENTS = {
        "",
        "It wriggled and jiggled and tickled inside her.",
        "How absurd to swallow a bird!",
        "Imagine that, to swallow a cat!",
        "What a hog, to swallow a dog!",
        "Just opened her throat and swallowed a goat!",
        "I don't know how she swallowed a cow!",
        "She's dead, of course!"
    };

    private static final String[] CATCH_PHRASES = {
        "",
        "She swallowed the spider to catch the fly.",
        "She swallowed the bird to catch the spider that wriggled and jiggled and tickled inside her.",
        "She swallowed the cat to catch the bird.",
        "She swallowed the dog to catch the cat.",
        "She swallowed the goat to catch the dog.",
        "She swallowed the cow to catch the goat."
    };

    private static final String FLY_REFRAIN = "I don't know why she swallowed the fly. Perhaps she'll die.";

    String verse(int verse) {
        StringBuilder sb = new StringBuilder();
        int idx = verse - 1;

        sb.append("I know an old lady who swallowed a ").append(ANIMALS[idx]).append(".\n");

        // Special case: horse
        if (idx == 7) {
            sb.append(COMMENTS[7]);
            return sb.toString();
        }

        // Add comment if present
        if (!COMMENTS[idx].isEmpty()) {
            sb.append(COMMENTS[idx]).append("\n");
        }

        // Add cumulative catch lines
        for (int i = idx; i > 0; i--) {
            if (i == 2) {
                sb.append(CATCH_PHRASES[i]).append("\n");
            } else if (i > 2) {
                sb.append(CATCH_PHRASES[i]).append("\n");
            } else {
                sb.append(CATCH_PHRASES[i]).append("\n");
            }
        }

        sb.append(FLY_REFRAIN);

        return sb.toString();
    }

    String verses(int startVerse, int endVerse) {
        StringBuilder sb = new StringBuilder();
        for (int i = startVerse; i <= endVerse; i++) {
            sb.append(verse(i));
            if (i != endVerse) {
                sb.append("\n\n");
            }
        }
        return sb.toString();
    }

}
