#[derive(PartialEq, Eq, Debug, Clone, Copy)]
pub enum Bucket {
    One,
    Two,
}

/// A struct to hold your results in.
#[derive(PartialEq, Eq, Debug)]
pub struct BucketStats {
    /// The total number of "moves" it should take to reach the desired number of liters, including
    /// the first fill.
    pub moves: u8,
    /// Which bucket should end up with the desired number of liters? (Either "one" or "two")
    pub goal_bucket: Bucket,
    /// How many liters are left in the other bucket?
    pub other_bucket: u8,
}

/// State of the buckets at any point
#[derive(PartialEq, Eq, Debug, Clone, Copy, Hash)]
struct State {
    b1: u8,
    b2: u8,
}

use std::collections::{HashSet, VecDeque};

/// Solve the bucket problem
pub fn solve(
    capacity_1: u8,
    capacity_2: u8,
    goal: u8,
    start_bucket: &Bucket,
) -> Option<BucketStats> {
    // Early exit if goal is impossible
    if goal > capacity_1 && goal > capacity_2 {
        return None;
    }
    if goal == 0 {
        return None;
    }

    // BFS setup
    let mut visited = HashSet::new();
    let mut queue = VecDeque::new();

    // Initial state: fill the starting bucket, other is empty
    let (init_state, moves) = match start_bucket {
        Bucket::One => (State { b1: capacity_1, b2: 0 }, 1),
        Bucket::Two => (State { b1: 0, b2: capacity_2 }, 1),
    };
    queue.push_back((init_state, moves, *start_bucket));

    while let Some((state, moves, first_bucket)) = queue.pop_front() {
        // Check for goal
        if state.b1 == goal {
            return Some(BucketStats {
                moves,
                goal_bucket: Bucket::One,
                other_bucket: state.b2,
            });
        }
        if state.b2 == goal {
            return Some(BucketStats {
                moves,
                goal_bucket: Bucket::Two,
                other_bucket: state.b1,
            });
        }

        // Don't revisit states
        if !visited.insert(state) {
            continue;
        }

        // Rule: may not arrive at a state where the initial starting bucket is empty and the other is full
        let forbidden = match first_bucket {
            Bucket::One => state.b1 == 0 && state.b2 == capacity_2,
            Bucket::Two => state.b2 == 0 && state.b1 == capacity_1,
        };
        if forbidden {
            continue;
        }

        // Generate all possible next states (actions)
        let mut next_states = Vec::new();

        // 1. Fill bucket 1
        if state.b1 < capacity_1 {
            next_states.push(State { b1: capacity_1, b2: state.b2 });
        }
        // 2. Fill bucket 2
        if state.b2 < capacity_2 {
            next_states.push(State { b1: state.b1, b2: capacity_2 });
        }
        // 3. Empty bucket 1
        if state.b1 > 0 {
            next_states.push(State { b1: 0, b2: state.b2 });
        }
        // 4. Empty bucket 2
        if state.b2 > 0 {
            next_states.push(State { b1: state.b1, b2: 0 });
        }
        // 5. Pour bucket 1 -> bucket 2
        if state.b1 > 0 && state.b2 < capacity_2 {
            let pour = std::cmp::min(state.b1, capacity_2 - state.b2);
            next_states.push(State { b1: state.b1 - pour, b2: state.b2 + pour });
        }
        // 6. Pour bucket 2 -> bucket 1
        if state.b2 > 0 && state.b1 < capacity_1 {
            let pour = std::cmp::min(state.b2, capacity_1 - state.b1);
            next_states.push(State { b1: state.b1 + pour, b2: state.b2 - pour });
        }

        for ns in next_states {
            queue.push_back((ns, moves + 1, first_bucket));
        }
    }

    None
}
