/// Type implementing arbitrary-precision decimal arithmetic
#[derive(Clone, Debug)]
pub struct Decimal {
    sign: i8,           // 1 for positive, -1 for negative, 0 for zero
    int: Vec<u8>,       // integer part, most significant digit first
    frac: Vec<u8>,      // fractional part, least significant digit last
}

impl Decimal {
    pub fn try_from(input: &str) -> Option<Decimal> {
        // Remove whitespace
        let input = input.trim();
        if input.is_empty() {
            return None;
        }

        let mut chars = input.chars().peekable();
        let mut sign = 1i8;
        if let Some(&c) = chars.peek() {
            if c == '-' {
                sign = -1;
                chars.next();
            } else if c == '+' {
                chars.next();
            }
        }

        let mut int_part = Vec::new();
        let mut frac_part = Vec::new();
        let mut seen_dot = false;

        for c in chars {
            if c == '.' {
                if seen_dot {
                    // Multiple dots
                    return None;
                }
                seen_dot = true;
                continue;
            }
            if !c.is_ascii_digit() {
                return None;
            }
            let digit = c as u8 - b'0';
            if !seen_dot {
                int_part.push(digit);
            } else {
                frac_part.push(digit);
            }
        }

        // Remove leading zeros from int_part
        while int_part.len() > 1 && int_part[0] == 0 {
            int_part.remove(0);
        }
        // Remove trailing zeros from frac_part
        while frac_part.last() == Some(&0) {
            frac_part.pop();
        }

        // If both int_part and frac_part are zero, set sign to 0
        if int_part.iter().all(|&d| d == 0) && frac_part.iter().all(|&d| d == 0) {
            sign = 0;
        }

        Some(Decimal {
            sign,
            int: if int_part.is_empty() { vec![0] } else { int_part },
            frac: frac_part,
        })
    }

    fn cmp_abs(&self, other: &Decimal) -> Ordering {
        // Compare integer part
        if self.int.len() != other.int.len() {
            return self.int.len().cmp(&other.int.len());
        }
        for (a, b) in self.int.iter().zip(other.int.iter()) {
            if a != b {
                return a.cmp(b);
            }
        }
        // Compare fractional part
        let max_frac = self.frac.len().max(other.frac.len());
        for i in 0..max_frac {
            let a = *self.frac.get(i).unwrap_or(&0);
            let b = *other.frac.get(i).unwrap_or(&0);
            if a != b {
                return a.cmp(&b);
            }
        }
        Ordering::Equal
    }

    fn add_abs(a: &Decimal, b: &Decimal) -> Decimal {
        // Add fractional part
        let max_frac = a.frac.len().max(b.frac.len());
        let mut frac = Vec::with_capacity(max_frac);
        let mut carry = 0u8;
        for i in (0..max_frac).rev() {
            let da = *a.frac.get(i).unwrap_or(&0);
            let db = *b.frac.get(i).unwrap_or(&0);
            let sum = da + db + carry;
            frac.push(sum % 10);
            carry = sum / 10;
        }
        frac.reverse();

