            0
        };
        let int = if int_len > 0 {
            result[..int_len].to_vec()
        } else {
            vec![0]
        };
        let mut frac = if int_len < result.len() {
            result[int_len..].to_vec()
        } else {
            vec![]
        };
        // Remove trailing zeros from frac
        while frac.last() == Some(&0) {
            frac.pop();
        }

        Decimal {
            sign: 1,
            int,
            frac,
        }
    }
}

// Display for debugging
impl fmt::Display for Decimal {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.sign == -1 {
            write!(f, "-")?;
        }
        for d in &self.int {
            write!(f, "{}", d)?;
        }
        if !self.frac.is_empty() {
            write!(f, ".")?;
            for d in &self.frac {
                write!(f, "{}", d)?;
            }
        }
        Ok(())
    }
}

// PartialEq
impl PartialEq for Decimal {
    fn eq(&self, other: &Self) -> bool {
        self.sign == other.sign
            && self.int == other.int
            && {
                // trailing zeros in frac are not significant
                let mut a = self.frac.clone();
                let mut b = other.frac.clone();
                while a.last() == Some(&0) {
                    a.pop();
                }
                while b.last() == Some(&0) {
                    b.pop();
                }
                a == b
            }
    }
}

// PartialOrd
impl PartialOrd for Decimal {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        if self.sign != other.sign {
            return Some(self.sign.cmp(&other.sign));
        }
        if self.sign == 0 {
            return Some(Ordering::Equal);
        }
        let ord = self.cmp_abs(other);
        if self.sign == 1 {
            Some(ord)
        } else {
            Some(ord.reverse())
        }
    }
}

// Add
impl Add for Decimal {
    type Output = Decimal;
    fn add(self, rhs: Decimal) -> Decimal {
        if self.sign == 0 {
            return rhs;
        }
        if rhs.sign == 0 {
            return self;
        }
        if self.sign == rhs.sign {
            let mut res = Decimal::add_abs(&self, &rhs);
            res.sign = self.sign;
            res
        } else {
            match self.cmp_abs(&rhs) {
                Ordering::Greater => {
                    let mut res = Decimal::sub_abs(&self, &rhs);
                    res.sign = self.sign;
                    res
                }
                Ordering::Less => {
                    let mut res = Decimal::sub_abs(&rhs, &self);
                    res.sign = rhs.sign;
                    res
                }
                Ordering::Equal => Decimal {
                    sign: 0,
                    int: vec![0],
                    frac: vec![],
                },
            }
        }
    }
}

// Sub
impl Sub for Decimal {
    type Output = Decimal;
    fn sub(self, rhs: Decimal) -> Decimal {
        if rhs.sign == 0 {
            return self;
        }
        if self.sign == 0 {
            let mut res = rhs;
            res.sign *= -1;
            return res;
        }
        if self.sign != rhs.sign {
            let mut res = Decimal::add_abs(&self, &rhs);
            res.sign = self.sign;
            res
        } else {
            match self.cmp_abs(&rhs) {
                Ordering::Greater => {
                    let mut res = Decimal::sub_abs(&self, &rhs);
                    res.sign = self.sign;
                    res
                }
                Ordering::Less => {
                    let mut res = Decimal::sub_abs(&rhs, &self);
                    res.sign = -self.sign;
                    res
                }
                Ordering::Equal => Decimal {
                    sign: 0,
                    int: vec![0],
                    frac: vec![],
                },
            }
        }
    }
}

// Mul
impl Mul for Decimal {
    type Output = Decimal;
    fn mul(self, rhs: Decimal) -> Decimal {
        if self.sign == 0 || rhs.sign == 0 {
            return Decimal {
                sign: 0,
                int: vec![0],
                frac: vec![],
            };
        }
        let mut res = Decimal::mul_abs(&self, &rhs);
        res.sign = self.sign * rhs.sign;
        res
    }
}
