    public String format(String currency, String locale, LedgerEntry[] entries) {
        LedgerFormatConfig config = LedgerFormatConfig.forCurrencyAndLocale(currency, locale);

        StringBuilder sb = new StringBuilder();
        sb.append(config.header);

        if (entries.length > 0) {
            // Sort entries: negative first, then positive, each group by date
            List<LedgerEntry> negatives = new ArrayList<>();
            List<LedgerEntry> positives = new ArrayList<>();
            for (LedgerEntry entry : entries) {
                if (entry.getChange() < 0) {
                    negatives.add(entry);
                } else {
                    positives.add(entry);
                }
            }
            negatives.sort(Comparator.comparing(LedgerEntry::getLocalDate));
            positives.sort(Comparator.comparing(LedgerEntry::getLocalDate));

            List<LedgerEntry> all = new ArrayList<>();
            all.addAll(negatives);
            all.addAll(positives);

            for (LedgerEntry entry : all) {
                String date = entry.getLocalDate().format(config.dateFormatter);

                String desc = entry.getDescription();
                if (desc.length() > 25) {
                    desc = desc.substring(0, 22) + "...";
                }

                String amount = formatAmount(entry.getChange(), config);

                sb.append("\n");
                sb.append(String.format("%s | %-25s | %13s", date, desc, amount));
            }
        }

        return sb.toString();
    }

    private String formatAmount(double change, LedgerFormatConfig config) {
        boolean isNegative = change < 0;
        double absValue = Math.abs(change) / 100.0;

        // Format number with grouping and decimal separator
        String[] parts = String.format(Locale.US, "%.2f", absValue).split("\\.");
        String integerPart = parts[0];
        String decimalPart = parts[1];

        // Add thousands separator
        StringBuilder grouped = new StringBuilder();
        int len = integerPart.length();
        for (int i = 0; i < len; i++) {
            if (i > 0 && (len - i) % 3 == 0) {
                grouped.append(config.thousandsSeparator);
            }
            grouped.append(integerPart.charAt(i));
        }

        String formatted = grouped.toString() + config.decimalSeparator + decimalPart;

        // Add currency symbol and handle negative formatting
        if (config.locale.equals("nl-NL")) {
            formatted = config.currencySymbol + " " + formatted;
            if (isNegative) {
                formatted = config.currencySymbol + " -" + formatted.substring(config.currencySymbol.length() + 1) + " ";
            } else {
                formatted = " " + formatted + " ";
            }
        } else {
            formatted = config.currencySymbol + formatted;
            if (isNegative) {
                formatted = "(" + formatted + ")";
            } else {
                formatted = formatted + " ";
            }
        }
        return formatted;
    }

    private static class LedgerFormatConfig {
        final String currencySymbol;
        final DateTimeFormatter dateFormatter;
        final String decimalSeparator;
        final String thousandsSeparator;
        final String header;
        final String locale;

        private LedgerFormatConfig(String currencySymbol, DateTimeFormatter dateFormatter, String decimalSeparator,
                                   String thousandsSeparator, String header, String locale) {
            this.currencySymbol = currencySymbol;
            this.dateFormatter = dateFormatter;
            this.decimalSeparator = decimalSeparator;
            this.thousandsSeparator = thousandsSeparator;
            this.header = header;
            this.locale = locale;
        }

        static LedgerFormatConfig forCurrencyAndLocale(String currency, String locale) {
            if (!Arrays.asList("USD", "EUR").contains(currency)) {
                throw new IllegalArgumentException("Invalid currency");
            }
            if (!Arrays.asList("en-US", "nl-NL").contains(locale)) {
                throw new IllegalArgumentException("Invalid locale");
            }

            String currencySymbol = currency.equals("USD") ? "$" : "€";
            DateTimeFormatter dateFormatter;
            String decimalSeparator;
            String thousandsSeparator;
            String header;

            if (locale.equals("en-US")) {
                dateFormatter = DateTimeFormatter.ofPattern("MM/dd/yyyy");
                decimalSeparator = ".";
                thousandsSeparator = ",";
                header = "Date       | Description               | Change       ";
            } else { // nl-NL
                dateFormatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
                decimalSeparator = ",";
                thousandsSeparator = ".";
                header = "Date       | Description               | Change       ";
            }

            return new LedgerFormatConfig(currencySymbol, dateFormatter, decimalSeparator, thousandsSeparator, header, locale);
        }
    }

    public static class LedgerEntry {
        LocalDate localDate;
        String description;
        double change;

        public LocalDate getLocalDate() {
            return localDate;
        }

        public void setLocalDate(LocalDate localDate) {
            this.localDate = localDate;
