use std::marker::PhantomData;
use std::ptr::NonNull;

/// A node in the doubly linked list.
struct Node<T> {
    elem: T,
    next: Option<NonNull<Node<T>>>,
    prev: Option<NonNull<Node<T>>>,
}

/// A doubly linked list.
pub struct LinkedList<T> {
    head: Option<NonNull<Node<T>>>,
    tail: Option<NonNull<Node<T>>>,
    len: usize,
    _marker: PhantomData<Box<Node<T>>>, // Ensures drop order and variance
}

pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    current: Option<NonNull<Node<T>>>,
    _marker: PhantomData<&'a mut T>,
}

pub struct Iter<'a, T> {
    current: Option<NonNull<Node<T>>>,
    remaining: usize,
    _marker: PhantomData<&'a T>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        Cursor {
            current: self.head,
            list: self,
            _marker: PhantomData,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        Cursor {
            current: self.tail,
            list: self,
            _marker: PhantomData,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            current: self.head,
            remaining: self.len,
            _marker: PhantomData,
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // Safety: we always remove nodes from the front, so we never double-free.
        let mut current = self.head;
        while let Some(node_ptr) = current {
            unsafe {
                let node = Box::from_raw(node_ptr.as_ptr());
                current = node.next;
                // node is dropped here
            }
        }
        self.head = None;
        self.tail = None;
        self.len = 0;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        if self.remaining == 0 {
            return None;
        }
        self.current.map(|node_ptr| unsafe {
            let node = &*node_ptr.as_ptr();
            self.current = node.next;
            self.remaining -= 1;
            &node.elem
        })
    }
}

// The cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<'a, T> Cursor<'a, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        self.current.map(|node_ptr| unsafe { &mut (*node_ptr.as_ptr()).elem })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        if let Some(node_ptr) = self.current {
            unsafe {
                let node = &mut *node_ptr.as_ptr();
                if let Some(next_ptr) = node.next {
                    self.current = Some(next_ptr);
                    Some(&mut (*next_ptr.as_ptr()).elem)
                } else {
                    self.current = None;
                    None
                }
            }
        } else {
            None
        }
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        if let Some(node_ptr) = self.current {
            unsafe {
                let node = &mut *node_ptr.as_ptr();
                if let Some(prev_ptr) = node.prev {
                    self.current = Some(prev_ptr);
                    Some(&mut (*prev_ptr.as_ptr()).elem)
                } else {
                    self.current = None;
                    None
                }
            }
        } else {
            None
        }
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node_ptr = self.current?;
        unsafe {
            let node = &mut *node_ptr.as_ptr();
            let prev = node.prev;
            let next = node.next;

            // Unlink node from the list
            if let Some(mut prev_ptr) = prev {
                (*prev_ptr.as_ptr()).next = next;
            } else {
                self.list.head = next;
            }
            if let Some(mut next_ptr) = next {
                (*next_ptr.as_ptr()).prev = prev;
            } else {
                self.list.tail = prev;
            }

            self.list.len -= 1;

            // Move cursor to next if possible, else prev
            self.current = next.or(prev);

            // Take ownership and drop node
            let boxed = Box::from_raw(node_ptr.as_ptr());
            Some(boxed.elem)
        }
    }

    pub fn insert_after(&mut self, element: T) {
        // If the list is empty, insert as the only element
        if self.list.len == 0 {
            let boxed = Box::new(Node {
                elem: element,
                next: None,
                prev: None,
            });
            let node_ptr = Some(unsafe { NonNull::new_unchecked(Box::into_raw(boxed)) });
            self.list.head = node_ptr;
            self.list.tail = node_ptr;
            self.current = node_ptr;
            self.list.len = 1;
            return;
        }

        let node_ptr = self.current.expect("Cursor must be on a node to insert after");
        unsafe {
            let node = &mut *node_ptr.as_ptr();
            let next = node.next;
            let mut new_node = Box::new(Node {
                elem: element,
                next,
                prev: Some(node_ptr),
            });
            let new_node_ptr = NonNull::new_unchecked(Box::into_raw(new_node));
            node.next = Some(new_node_ptr);
            if let Some(mut next_ptr) = next {
                (*next_ptr.as_ptr()).prev = Some(new_node_ptr);
            } else {
                self.list.tail = Some(new_node_ptr);
            }
            self.list.len += 1;
        }
    }

    pub fn insert_before(&mut self, element: T) {
        // If the list is empty, insert as the only element
        if self.list.len == 0 {
            let boxed = Box::new(Node {
                elem: element,
                next: None,
                prev: None,
            });
            let node_ptr = Some(unsafe { NonNull::new_unchecked(Box::into_raw(boxed)) });
            self.list.head = node_ptr;
            self.list.tail = node_ptr;
            self.current = node_ptr;
            self.list.len = 1;
            return;
        }

        let node_ptr = self.current.expect("Cursor must be on a node to insert before");
        unsafe {
            let node = &mut *node_ptr.as_ptr();
            let prev = node.prev;
            let mut new_node = Box::new(Node {
                elem: element,
                next: Some(node_ptr),
                prev,
            });
            let new_node_ptr = NonNull::new_unchecked(Box::into_raw(new_node));
            node.prev = Some(new_node_ptr);
            if let Some(mut prev_ptr) = prev {
                (*prev_ptr.as_ptr()).next = Some(new_node_ptr);
            } else {
                self.list.head = Some(new_node_ptr);
            }
            self.list.len += 1;
        }
    }
}

// SAFETY: LinkedList<T> is covariant over T because it only ever stores T in Box<Node<T>> and never mutates T through shared references.
unsafe impl<T: Send> Send for LinkedList<T> {}
unsafe impl<T: Sync> Sync for LinkedList<T> {}
