pub fn translate(input: &str) -> String {
    input
        .split_whitespace()
        .map(|word| translate_word(word))
        .collect::<Vec<_>>()
        .join(" ")
}

fn is_vowel(c: char) -> bool {
    matches!(c, 'a' | 'e' | 'i' | 'o' | 'u')
}

fn translate_word(word: &str) -> String {
    // Rule 1: starts with vowel or "xr"/"yt"
    if word.starts_with(|c: char| is_vowel(c))
        || word.starts_with("xr")
        || word.starts_with("yt")
    {
        return format!("{word}ay");
    }

    // Rule 3: starts with consonant(s) + "qu"
    if let Some(qu_pos) = find_qu(word) {
        let (start, end) = word.split_at(qu_pos + 2);
        return format!("{}{}ay", end, start);
    }

    // Rule 4: consonant(s) followed by 'y'
    if let Some(y_pos) = find_consonant_y(word) {
        let (start, end) = word.split_at(y_pos);
        return format!("{}{}ay", end, start);
    }

    // Rule 2: move leading consonant(s) to end, add "ay"
    let first_vowel = word
        .char_indices()
        .find(|&(_, c)| is_vowel(c))
        .map(|(i, _)| i)
        .unwrap_or(0);

    let (start, end) = word.split_at(first_vowel);
    format!("{}{}ay", end, start)
}

// Find the position of "qu" after leading consonants
fn find_qu(word: &str) -> Option<usize> {
    let mut chars = word.char_indices().peekable();
    while let Some((i, c)) = chars.next() {
        if is_vowel(c) {
            break;
        }
        if let Some(&(j, next_c)) = chars.peek() {
            if c == 'q' && next_c == 'u' {
                return Some(i);
            }
        }
    }
    // Also check for "qu" at the start
    if word.starts_with("qu") {
        return Some(0);
    }
    None
}

// Find the position of 'y' after leading consonants (not at start)
fn find_consonant_y(word: &str) -> Option<usize> {
    for (i, c) in word.char_indices().skip(1) {
        if c == 'y' {
            // Only if all before are consonants
            if word[..i].chars().all(|ch| !is_vowel(ch)) {
                return Some(i);
            }
        }
    }
    None
}
