use std::collections::HashMap;
use std::thread;

/// Count the frequency of letters in the given input using parallel computation.
/// Only alphabetic characters are counted, case-insensitively.
pub fn frequency(input: &[&str], worker_count: usize) -> HashMap<char, usize> {
    if input.is_empty() {
        return HashMap::new();
    }

    // Flatten all input strings into a single String for easier chunking
    let all_text: String = input.join(" ");
    let chars: Vec<char> = all_text.chars().collect();
    let len = chars.len();

    // Determine the number of workers to use (at most the number of chars)
    let workers = worker_count.min(len).max(1);

    // Split the chars into chunks for each worker
    let chunk_size = (len + workers - 1) / workers; // ceil division

    let mut handles = Vec::with_capacity(workers);

    for chunk in chars.chunks(chunk_size) {
        // Clone the chunk for the thread
        let chunk: Vec<char> = chunk.to_vec();
        let handle = thread::spawn(move || {
            let mut freq = HashMap::new();
            for c in chunk {
                if c.is_alphabetic() {
                    let c = c.to_ascii_lowercase();
                    *freq.entry(c).or_insert(0) += 1;
                }
            }
            freq
        });
        handles.push(handle);
    }

    // Merge all the results
    let mut result = HashMap::new();
    for handle in handles {
        if let Ok(freq) = handle.join() {
            for (c, count) in freq {
                *result.entry(c).or_insert(0) += count;
            }
        }
    }

    result
}
