pub fn answer(command: &str) -> Option<i32> {
    // Check that the command starts with "What is " and ends with "?"
    let trimmed = command.trim();
    if !trimmed.starts_with("What is ") || !trimmed.ends_with('?') {
        return None;
    }

    // Remove "What is " from the start and "?" from the end
    let mut expr = &trimmed[8..trimmed.len() - 1];
    expr = expr.trim();

    // If the expression is empty, return None
    if expr.is_empty() {
        return None;
    }

    // Supported operations
    #[derive(Debug, Clone, Copy)]
    enum Op {
        Add,
        Sub,
        Mul,
        Div,
    }

    // Map operation words to Op
    fn parse_op(word: &str) -> Option<Op> {
        match word {
            "plus" => Some(Op::Add),
            "minus" => Some(Op::Sub),
            "multiplied by" => Some(Op::Mul),
            "divided by" => Some(Op::Div),
            _ => None,
        }
    }

    // Tokenize the expression into numbers and operations
    let mut tokens = Vec::new();
    let mut i = 0;
    let words: Vec<&str> = expr.split_whitespace().collect();

    while i < words.len() {
        // Try to parse a number
        if let Ok(num) = words[i].parse::<i32>() {
            tokens.push(num.to_string());
            i += 1;
            continue;
        }

        // Try to parse a negative number (e.g., "-5")
        if words[i].starts_with('-') {
            if let Ok(num) = words[i].parse::<i32>() {
                tokens.push(num.to_string());
                i += 1;
                continue;
            }
        }

        // Try to parse two-word operations
        if i + 1 < words.len() {
            let op2 = format!("{} {}", words[i], words[i + 1]);
            if parse_op(&op2).is_some() {
                tokens.push(op2);
                i += 2;
                continue;
            }
        }

        // Try to parse one-word operations
        if parse_op(words[i]).is_some() {
            tokens.push(words[i].to_string());
            i += 1;
            continue;
        }

        // If we get here, it's an unsupported operation or invalid syntax
        return None;
    }

    // There must be at least one number
    if tokens.is_empty() {
        return None;
    }

    // The first token must be a number
    let mut idx = 0;
    let mut result = match tokens.get(idx) {
        Some(token) => match token.parse::<i32>() {
            Ok(num) => num,
            Err(_) => return None,
        },
        None => return None,
    };
    idx += 1;

    // Now, alternate between op and number
    while idx < tokens.len() {
        // Parse operation
        let op_token = &tokens[idx];
        let op = match parse_op(op_token) {
            Some(op) => op,
            None => return None,
        };
        idx += 1;

        // Parse next number
        if idx >= tokens.len() {
            return None;
        }
        let num_token = &tokens[idx];
        let num = match num_token.parse::<i32>() {
            Ok(n) => n,
            Err(_) => return None,
        };
        idx += 1;

        // Apply operation (left-to-right)
        result = match op {
            Op::Add => result + num,
            Op::Sub => result - num,
            Op::Mul => result * num,
            Op::Div => {
                if num == 0 {
                    return None;
                }
                result / num
            }
        };
    }

    Some(result)
}
