use std::collections::HashMap;

pub struct CodonsInfo<'a> {
    codon_to_protein: HashMap<&'a str, &'a str>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Error;

impl<'a> CodonsInfo<'a> {
    // Helper: IUPAC codes for DNA/RNA
    fn iupac_map() -> HashMap<char, Vec<char>> {
        let mut m = HashMap::new();
        m.insert('A', vec!['A']);
        m.insert('C', vec!['C']);
        m.insert('G', vec!['G']);
        m.insert('T', vec!['T']);
        m.insert('U', vec!['U']); // for RNA
        m.insert('R', vec!['A', 'G']);
        m.insert('Y', vec!['C', 'T']);
        m.insert('S', vec!['G', 'C']);
        m.insert('W', vec!['A', 'T']);
        m.insert('K', vec!['G', 'T']);
        m.insert('M', vec!['A', 'C']);
        m.insert('B', vec!['C', 'G', 'T']);
        m.insert('D', vec!['A', 'G', 'T']);
        m.insert('H', vec!['A', 'C', 'T']);
        m.insert('V', vec!['A', 'C', 'G']);
        m.insert('N', vec!['A', 'C', 'G', 'T']);
        m
    }

    // Expand a codon with possible IUPAC codes into all possible concrete codons
    fn expand_codon(codon: &str) -> Option<Vec<String>> {
        let iupac = Self::iupac_map();
        let chars: Vec<char> = codon.chars().collect();
        if chars.len() != 3 {
            return None;
        }
        let mut sets: Vec<Vec<char>> = Vec::new();
        for &c in &chars {
            if let Some(bases) = iupac.get(&c) {
                sets.push(bases.clone());
            } else {
                return None;
            }
        }
        let mut results = Vec::new();
        for a in &sets[0] {
            for b in &sets[1] {
                for c in &sets[2] {
                    results.push(format!("{}{}{}", a, b, c));
                }
            }
        }
        Some(results)
    }

    pub fn name_for(&self, codon: &str) -> Result<&'a str, Error> {
        if let Some(expanded) = Self::expand_codon(codon) {
            let mut protein: Option<&'a str> = None;
            for concrete in expanded {
                match self.codon_to_protein.get(concrete.as_str()) {
                    Some(&p) => {
                        if let Some(existing) = protein {
                            if existing != p {
                                // Ambiguous: codon maps to multiple proteins
                                return Err(Error);
                            }
                        } else {
                            protein = Some(p);
                        }
                    }
                    None => return Err(Error),
                }
            }
            protein.ok_or(Error)
        } else {
            Err(Error)
        }
    }

    pub fn of_rna(&self, rna: &str) -> Result<Vec<&'a str>, Error> {
        if rna.len() % 3 != 0 {
            return Err(Error);
        }
        let mut result = Vec::new();
        for i in (0..rna.len()).step_by(3) {
            let codon = &rna[i..i + 3];
            let protein = self.name_for(codon)?;
            result.push(protein);
        }
        Ok(result)
    }
}

pub fn parse<'a>(pairs: Vec<(&'a str, &'a str)>) -> CodonsInfo<'a> {
    let mut codon_to_protein = HashMap::new();
    for (codon, protein) in pairs {
        codon_to_protein.insert(codon, protein);
    }
    CodonsInfo { codon_to_protein }
}
