import java.util.*;

public class MazeGenerator {

    private static final char WALL_HORIZONTAL = '─';
    private static final char WALL_VERTICAL = '│';
    private static final char CORNER_TL = '┌';
    private static final char CORNER_TR = '┐';
    private static final char CORNER_BL = '└';
    private static final char CORNER_BR = '┘';
    private static final char T_UP = '┴';
    private static final char T_DOWN = '┬';
    private static final char T_LEFT = '┤';
    private static final char T_RIGHT = '├';
    private static final char CROSS = '┼';
    private static final char SPACE = ' ';
    private static final char ENTRANCE = '⇨';
    private static final char EXIT = '⇨';

    // Directions: up, right, down, left
    private static final int[] DX = {0, 1, 0, -1};
    private static final int[] DY = {-1, 0, 1, 0};

    public char[][] generatePerfectMaze(int rows, int columns) {
        return generatePerfectMaze(rows, columns, new Random().nextInt());
    }

    public char[][] generatePerfectMaze(int rows, int columns, int seed) {
        if (rows < 5 || columns < 5 || rows > 100 || columns > 100) {
            throw new IllegalArgumentException("Maze size must be between 5 and 100 cells in each dimension.");
        }
        int mazeRows = rows;
        int mazeCols = columns;
        int gridRows = 2 * mazeRows + 1;
        int gridCols = 2 * mazeCols + 1;

        // Maze cell visited state
        boolean[][] visited = new boolean[mazeRows][mazeCols];
        // Maze grid (walls and spaces)
        char[][] grid = new char[gridRows][gridCols];

        // Fill with walls
        for (int y = 0; y < gridRows; y++) {
            for (int x = 0; x < gridCols; x++) {
                grid[y][x] = SPACE;
            }
        }

        // Draw outer walls and corners
        for (int y = 0; y < gridRows; y++) {
            for (int x = 0; x < gridCols; x++) {
                boolean top = y == 0;
                boolean bottom = y == gridRows - 1;
                boolean left = x == 0;
                boolean right = x == gridCols - 1;

                if (top && left) grid[y][x] = CORNER_TL;
                else if (top && right) grid[y][x] = CORNER_TR;
                else if (bottom && left) grid[y][x] = CORNER_BL;
                else if (bottom && right) grid[y][x] = CORNER_BR;
                else if (top) grid[y][x] = WALL_HORIZONTAL;
                else if (bottom) grid[y][x] = WALL_HORIZONTAL;
                else if (left) grid[y][x] = WALL_VERTICAL;
                else if (right) grid[y][x] = WALL_VERTICAL;
            }
        }

        // Draw grid intersections and internal walls
        for (int y = 1; y < gridRows - 1; y++) {
            for (int x = 1; x < gridCols - 1; x++) {
                if (y % 2 == 0 && x % 2 == 0) {
                    grid[y][x] = CROSS;
                } else if (y % 2 == 0) {
                    grid[y][x] = WALL_HORIZONTAL;
                } else if (x % 2 == 0) {
                    grid[y][x] = WALL_VERTICAL;
                }
            }
        }

        // Maze generation using randomized DFS
        Random rand = new Random(seed);
        Deque<int[]> stack = new ArrayDeque<>();
        int startRow = rand.nextInt(mazeRows);
        int startCol = 0; // always start at leftmost column
        stack.push(new int[]{startRow, startCol});
        visited[startRow][startCol] = true;

        while (!stack.isEmpty()) {
            int[] cell = stack.peek();
            int r = cell[0];
            int c = cell[1];

            List<Integer> dirs = Arrays.asList(0, 1, 2, 3);
            Collections.shuffle(dirs, rand);

            boolean moved = false;
            for (int dir : dirs) {
                int nr = r + DY[dir];
                int nc = c + DX[dir];
                if (nr >= 0 && nr < mazeRows && nc >= 0 && nc < mazeCols && !visited[nr][nc]) {
                    // Remove wall between (r,c) and (nr,nc)
                    int wallY = r * 2 + 1 + DY[dir];
                    int wallX = c * 2 + 1 + DX[dir];
                    grid[wallY][wallX] = SPACE;
                    visited[nr][nc] = true;
                    stack.push(new int[]{nr, nc});
                    moved = true;
                    break;
                }
            }
            if (!moved) {
                stack.pop();
            }
        }

        // Open up the cells
        for (int r = 0; r < mazeRows; r++) {
            for (int c = 0; c < mazeCols; c++) {
                grid[r * 2 + 1][c * 2 + 1] = SPACE;
            }
        }

        // Place entrance and exit
        int entranceRow = 2 * startRow + 1;
        grid[entranceRow][0] = ENTRANCE;

        // Find a cell on the rightmost column to be the exit
        int exitRow = -1;
        for (int r = mazeRows - 1; r >= 0; r--) {
            if (grid[r * 2 + 1][gridCols - 2] == SPACE) {
                exitRow = r * 2 + 1;
                break;
            }
        }
        if (exitRow == -1) {
            // fallback: just use the bottom right cell
            exitRow = gridRows - 2;
        }
        grid[exitRow][gridCols - 1] = EXIT;

        // Fix T-junctions and corners for box-drawing
        fixBoxDrawing(grid);

        return grid;
    }

    private void fixBoxDrawing(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        for (int y = 1; y < rows - 1; y++) {
            for (int x = 1; x < cols - 1; x++) {
                if (grid[y][x] == WALL_HORIZONTAL || grid[y][x] == WALL_VERTICAL || grid[y][x] == CROSS) {
                    boolean up = isWall(grid[y - 1][x]);
                    boolean down = isWall(grid[y + 1][x]);
                    boolean left = isWall(grid[y][x - 1]);
                    boolean right = isWall(grid[y][x + 1]);
                    if (up && down && left && right) {
                        grid[y][x] = CROSS;
                    } else if (up && down && left) {
                        grid[y][x] = T_RIGHT;
                    } else if (up && down && right) {
                        grid[y][x] = T_LEFT;
                    } else if (left && right && up) {
                        grid[y][x] = T_UP;
                    } else if (left && right && down) {
                        grid[y][x] = T_DOWN;
                    } else if (up && down) {
                        grid[y][x] = WALL_VERTICAL;
                    } else if (left && right) {
                        grid[y][x] = WALL_HORIZONTAL;
                    } else if (up && right) {
                        grid[y][x] = CORNER_BL;
                    } else if (up && left) {
                        grid[y][x] = CORNER_BR;
                    } else if (down && right) {
                        grid[y][x] = CORNER_TL;
                    } else if (down && left) {
                        grid[y][x] = CORNER_TR;
                    }
                }
            }
        }
    }

    private boolean isWall(char c) {
        return c == WALL_HORIZONTAL || c == WALL_VERTICAL || c == CORNER_TL || c == CORNER_TR ||
               c == CORNER_BL || c == CORNER_BR || c == T_UP || c == T_DOWN || c == T_LEFT ||
               c == T_RIGHT || c == CROSS;
    }
}
