#include "linked_list.h"
#include <stdexcept>

namespace linked_list {

template <typename T>
List<T>::List() : head(nullptr), tail(nullptr), sz(0) {}

template <typename T>
List<T>::~List() {
    Node* current = head;
    while (current) {
        Node* next = current->next;
        delete current;
        current = next;
    }
}

template <typename T>
void List<T>::push(const T& value) {
    Node* node = new Node(value);
    if (!tail) {
        head = tail = node;
    } else {
        tail->next = node;
        node->prev = tail;
        tail = node;
    }
    ++sz;
}

template <typename T>
T List<T>::pop() {
    if (!tail) {
        throw std::out_of_range("pop from empty list");
    }
    Node* node = tail;
    T value = node->value;
    tail = tail->prev;
    if (tail) {
        tail->next = nullptr;
    } else {
        head = nullptr;
    }
    delete node;
    --sz;
    return value;
}

template <typename T>
void List<T>::unshift(const T& value) {
    Node* node = new Node(value);
    if (!head) {
        head = tail = node;
    } else {
        node->next = head;
        head->prev = node;
        head = node;
    }
    ++sz;
}

template <typename T>
T List<T>::shift() {
    if (!head) {
        throw std::out_of_range("shift from empty list");
    }
    Node* node = head;
    T value = node->value;
    head = head->next;
    if (head) {
        head->prev = nullptr;
    } else {
        tail = nullptr;
    }
    delete node;
    --sz;
    return value;
}

template <typename T>
std::size_t List<T>::count() const {
    return sz;
}

template <typename T>
bool List<T>::erase(const T& value) {
    Node* current = head;
    while (current) {
        if (current->value == value) {
            if (current->prev) {
                current->prev->next = current->next;
            } else {
                head = current->next;
            }
            if (current->next) {
                current->next->prev = current->prev;
            } else {
                tail = current->prev;
            }
            delete current;
            --sz;
            return true;
        }
        current = current->next;
    }
    return false;
}

// Move constructor
template <typename T>
List<T>::List(List&& other) noexcept : head(other.head), tail(other.tail), sz(other.sz) {
    other.head = nullptr;
    other.tail = nullptr;
    other.sz = 0;
}

// Move assignment
template <typename T>
List<T>& List<T>::operator=(List&& other) noexcept {
    if (this != &other) {
        // Clean up current list
        Node* current = head;
        while (current) {
            Node* next = current->next;
            delete current;
            current = next;
        }
        head = other.head;
        tail = other.tail;
        sz = other.sz;
        other.head = nullptr;
        other.tail = nullptr;
        other.sz = 0;
    }
    return *this;
}

// Explicit instantiations for int (add more types as needed)
template class List<int>;

}  // namespace linked_list
