import string
import math

ALPHABET = string.ascii_lowercase
M = len(ALPHABET)

def _is_coprime(a, m):
    return math.gcd(a, m) == 1

def _modinv(a, m):
    # Find modular multiplicative inverse of a mod m
    # Returns x such that (a * x) % m == 1
    # Raises ValueError if no inverse exists
    for x in range(1, m):
        if (a * x) % m == 1:
            return x
    raise ValueError("a and m must be coprime.")

def encode(plain_text, a, b):
    if not _is_coprime(a, M):
        raise ValueError("a and m must be coprime.")

    result = []
    count = 0
    for char in plain_text.lower():
        if char in ALPHABET:
            i = ALPHABET.index(char)
            enc = (a * i + b) % M
            result.append(ALPHABET[enc])
            count += 1
        elif char.isdigit():
            result.append(char)
            count += 1
        # ignore spaces and punctuation

        # Insert space every 5 characters in output (excluding spaces in input)
        if count == 5:
            result.append(' ')
            count = 0

    # Remove trailing space if present
    encoded = ''.join(result).rstrip()
    return encoded

def decode(ciphered_text, a, b):
    if not _is_coprime(a, M):
        raise ValueError("a and m must be coprime.")

    a_inv = _modinv(a, M)
    result = []
    for char in ciphered_text.lower():
        if char in ALPHABET:
            y = ALPHABET.index(char)
            dec = (a_inv * (y - b)) % M
            result.append(ALPHABET[dec])
        elif char.isdigit():
            result.append(char)
        # ignore spaces and punctuation

    return ''.join(result)
