    ranks = []
    suits = []
    for card in cards:
        if card[:-1] == '10':
            rank = '10'
            suit = card[2]
        else:
            rank = card[0]
            suit = card[1]
        ranks.append(RANKS[rank])
        suits.append(suit)
    ranks.sort(reverse=True)
    return ranks, suits

def is_straight(ranks):
    # Handle wheel straight (A-2-3-4-5)
    if ranks == [14, 5, 4, 3, 2]:
        return True, 5
    for i in range(4):
        if ranks[i] - 1 != ranks[i+1]:
            return False, None
    return True, ranks[0]

def hand_rank(hand):
    ranks, suits = parse_hand(hand)
    flush = len(set(suits)) == 1
    straight, high_card = is_straight(ranks)
    counts = {r: ranks.count(r) for r in set(ranks)}
    count_values = sorted(counts.values(), reverse=True)
    unique_ranks = sorted(counts.keys(), reverse=True, key=lambda r: (counts[r], r))

    if straight and flush:
        if ranks[0] == 14 and ranks[1] == 13:
            return (9, ranks)  # Royal Flush
        return (8, [high_card])  # Straight Flush
    if 4 in count_values:
        four = unique_ranks[0]
        kicker = [r for r in ranks if r != four]
        return (7, [four] + kicker)  # Four of a Kind
    if 3 in count_values and 2 in count_values:
        three = unique_ranks[0]
        pair = unique_ranks[1]
        return (6, [three, pair])  # Full House
    if flush:
        return (5, ranks)  # Flush
    if straight:
        return (4, [high_card])  # Straight
    if 3 in count_values:
        three = unique_ranks[0]
        kickers = [r for r in ranks if r != three]
        return (3, [three] + kickers)  # Three of a Kind
    if count_values.count(2) == 2:
        pair1 = unique_ranks[0]
        pair2 = unique_ranks[1]
        kicker = [r for r in ranks if r != pair1 and r != pair2]
        return (2, [pair1, pair2] + kicker)  # Two Pair
    if 2 in count_values:
        pair = unique_ranks[0]
        kickers = [r for r in ranks if r != pair]
        return (1, [pair] + kickers)  # One Pair
    return (0, ranks)  # High Card

def best_hands(hands):
    ranked = [(hand_rank(hand), hand) for hand in hands]
    max_rank = max(ranked, key=lambda x: x[0])[0]
    return [hand for rank, hand in ranked if rank == max_rank]
