def encode(numbers):
    if not all(isinstance(n, int) and n >= 0 and n <= 0xFFFFFFFF for n in numbers):
        raise ValueError("all numbers must be 32-bit unsigned integers")
    result = []
    for number in numbers:
        if number == 0:
            result.append(0)
            continue
        bytes_ = []
        while number > 0:
            bytes_.insert(0, number & 0x7F)
            number >>= 7
        for i in range(len(bytes_) - 1):
            bytes_[i] |= 0x80  # set continuation bit
        result.extend(bytes_)
    return result


def decode(bytes_):
    numbers = []
    value = 0
    for i, b in enumerate(bytes_):
        value = (value << 7) | (b & 0x7F)
        if not (b & 0x80):
            numbers.append(value)
            value = 0
    if value != 0 or (bytes_ and (bytes_[-1] & 0x80)):
        raise ValueError("incomplete sequence")
    return numbers
