def recite(start, take=1):
    def bottle_phrase(n, capitalize=False):
        if n == 0:
            phrase = "no more bottles of beer"
        elif n == 1:
            phrase = "1 bottle of beer"
        else:
            phrase = f"{n} bottles of beer"
        if capitalize:
            phrase = phrase[0].upper() + phrase[1:]
        return phrase

    def wall_phrase(n, capitalize=False):
        return bottle_phrase(n, capitalize) + " on the wall"

    def verse(n):
        lines = []
        # First line
        lines.append(f"{wall_phrase(n, True)}, {bottle_phrase(n)}.")
        # Second line
        if n > 1:
            lines.append(f"Take one down and pass it around, {wall_phrase(n-1)}.")
        elif n == 1:
            lines.append(f"Take it down and pass it around, {wall_phrase(0)}.")
        else:  # n == 0
            lines.append("Go to the store and buy some more, 99 bottles of beer on the wall.")
        return lines

    verses = []
    for n in range(start, start - take, -1):
        verses.extend(verse(n))
        if n != start - take + 1:
            verses.append("")  # blank line between verses

    return verses
