class Zipper:
    def __init__(self, value, left, right, breadcrumbs):
        self._value = value
        self._left = left
        self._right = right
        self._breadcrumbs = breadcrumbs

    @staticmethod
    def from_tree(tree):
        # tree is expected to be a dict: {'value': x, 'left': l, 'right': r}
        return Zipper(
            tree['value'],
            tree['left'],
            tree['right'],
            []
        )

    def value(self):
        return self._value

    def set_value(self, value):
        return Zipper(value, self._left, self._right, self._breadcrumbs)

    def left(self):
        if self._left is None:
            return None
        # Add a breadcrumb for moving left: (direction, value, right)
        new_breadcrumbs = self._breadcrumbs + [('left', self._value, self._right)]
        return Zipper(self._left['value'], self._left['left'], self._left['right'], new_breadcrumbs)

    def set_left(self, left):
        return Zipper(self._value, left, self._right, self._breadcrumbs)

    def right(self):
        if self._right is None:
            return None
