#pragma once

#include <cstddef> // for std::size_t
#include <stdexcept>

namespace linked_list {

template <typename T>
class List {
private:
    struct Node {
        T value;
        Node* prev;
        Node* next;
        Node(const T& val) : value(val), prev(nullptr), next(nullptr) {}
    };

    Node* head;
    Node* tail;
    std::size_t sz;

public:
    List() : head(nullptr), tail(nullptr), sz(0) {}

    ~List() {
        Node* current = head;
        while (current) {
            Node* next = current->next;
            delete current;
            current = next;
        }
    }

    void push(const T& value) {
        Node* node = new Node(value);
        if (!tail) {
            head = tail = node;
        } else {
            tail->next = node;
            node->prev = tail;
            tail = node;
        }
        ++sz;
    }

    T pop() {
        if (!tail) {
            throw std::out_of_range("pop from empty list");
        }
        Node* node = tail;
        T value = node->value;
        tail = tail->prev;
        if (tail) {
            tail->next = nullptr;
        } else {
            head = nullptr;
        }
        delete node;
        --sz;
        return value;
    }

    void unshift(const T& value) {
        Node* node = new Node(value);
        if (!head) {
            head = tail = node;
        } else {
            node->next = head;
            head->prev = node;
            head = node;
        }
        ++sz;
    }

    T shift() {
        if (!head) {
            throw std::out_of_range("shift from empty list");
        }
        Node* node = head;
        T value = node->value;
        head = head->next;
        if (head) {
            head->prev = nullptr;
        } else {
            tail = nullptr;
        }
        delete node;
        --sz;
        return value;
    }

    std::size_t count() const {
        return sz;
    }

    bool erase(const T& value) {
        Node* current = head;
        while (current) {
            if (current->value == value) {
                if (current->prev) {
                    current->prev->next = current->next;
                } else {
                    head = current->next;
                }
                if (current->next) {
                    current->next->prev = current->prev;
                } else {
                    tail = current->prev;
                }
                delete current;
                --sz;
                return true;
            }
            current = current->next;
        }
        return false;
    }

    // Disable copy semantics for simplicity
    List(const List&) = delete;
    List& operator=(const List&) = delete;

    // Allow move semantics
    List(List&& other) noexcept : head(other.head), tail(other.tail), sz(other.sz) {
        other.head = nullptr;
        other.tail = nullptr;
        other.sz = 0;
    }

    List& operator=(List&& other) noexcept {
        if (this != &other) {
            // Clean up current list
            Node* current = head;
            while (current) {
                Node* next = current->next;
                delete current;
                current = next;
            }
            head = other.head;
            tail = other.tail;
            sz = other.sz;
            other.head = nullptr;
            other.tail = nullptr;
            other.sz = 0;
        }
        return *this;
    }
};

}  // namespace linked_list
