import re

class SgfTree:
    def __init__(self, properties=None, children=None):
        self.properties = properties or {}
        self.children = children or []

    def __eq__(self, other):
        if not isinstance(other, SgfTree):
            return False
        for key, value in self.properties.items():
            if key not in other.properties:
                return False
            if other.properties[key] != value:
                return False
        for key in other.properties.keys():
            if key not in self.properties:
                return False
        if len(self.children) != len(other.children):
            return False
        for child, other_child in zip(self.children, other.children):
            if child != other_child:
                return False
        return True

    def __ne__(self, other):
        return not self == other

def parse(input_string):
    if not input_string or not input_string.strip():
        raise ValueError("tree missing")
    input_string = input_string.strip()
    if not (input_string.startswith('(') and input_string.endswith(')')):
        raise ValueError("tree missing")
    # Remove outermost parentheses
    content = input_string[1:-1]
    if not content:
        raise ValueError("tree with no nodes")
    nodes, rest = _parse_nodes(content)
    if rest.strip():
        raise ValueError("properties without delimiter")
    if not nodes:
        raise ValueError("tree with no nodes")
    return nodes[0]

def _parse_nodes(s):
    nodes = []
    i = 0
    while i < len(s):
        if s[i] == ';':
            node, i = _parse_node(s, i + 1)
            nodes.append(node)
        elif s[i] == '(':
            # parse variation
            children, j = _parse_variation(s, i)
            if not nodes:
                # Variation without a parent node
                raise ValueError("tree with no nodes")
            nodes[-1].children.extend(children)
            i = j
        elif s[i].isspace():
            i += 1
        else:
            # Unexpected character
            raise ValueError("properties without delimiter")
    return nodes, ""

def _parse_variation(s, i):
    # s[i] == '('
    depth = 1
    j = i + 1
    start = j
    variations = []
    while j < len(s):
        if s[j] == '(':
            depth += 1
        elif s[j] == ')':
            depth -= 1
            if depth == 0:
                # parse the content between i+1 and j
                content = s[start:j]
                nodes, rest = _parse_nodes(content)
                if rest.strip():
                    raise ValueError("properties without delimiter")
                variations.append(nodes[0])
                return variations, j + 1
        elif s[j] == ';' and depth == 1:
            # start of a new variation at the top level
            if j > start:
                content = s[start:j]
                if content.strip():
                    nodes, rest = _parse_nodes(content)
                    if rest.strip():
                        raise ValueError("properties without delimiter")
                    variations.append(nodes[0])
            start = j
        j += 1
    raise ValueError("tree missing")

def _parse_node(s, i):
    # Parse properties until next ';' or '(' or ')'
    properties = {}
    while i < len(s):
        if s[i] in ';()':
            break
        if s[i].isspace():
            i += 1
            continue
        # Parse property key
        m = re.match(r'([A-Za-z]+)', s[i:])
        if not m:
            raise ValueError("properties without delimiter")
        key = m.group(1)
        if not key.isupper():
            raise ValueError("property must be in uppercase")
        i += len(key)
        # Parse property values
        values = []
        while i < len(s) and s[i] == '[':
            value, i = _parse_value(s, i + 1)
            values.append(value)
        if not values:
            raise ValueError("properties without delimiter")
        properties[key] = values if len(values) > 1 else [values[0]]
    node = SgfTree(properties)
    # Check for children (variations)
    if i < len(s) and s[i] == '(':
        children, j = _parse_variation(s, i)
        node.children.extend(children)
        i = j
    # Check for next node
    if i < len(s) and s[i] == ';':
        # There is another node at this level
        next_nodes, _ = _parse_nodes(s[i:])
        if next_nodes:
            node.children.extend(next_nodes)
        i = len(s)
    return node, i

def _parse_value(s, i):
    value = ''
    while i < len(s):
        if s[i] == ']':
            i += 1
            break
        if s[i] == '\\':
            i += 1
            if i >= len(s):
                break
            if s[i] == '\n':
                # Remove newline after backslash
                i += 1
                continue
            elif s[i] in ' \t\r':
                value += ' '
                i += 1
                continue
            else:
                value += s[i]
                i += 1
                continue
        elif s[i] == '\n':
            value += '\n'
            i += 1
        elif s[i] in ' \t\r':
            value += ' '
            i += 1
        else:
            value += s[i]
            i += 1
    return value, i
