const ALPHABET = 'abcdefghijklmnopqrstuvwxyz';
const M = 26; // length of the alphabet

function isCoprime(a, m) {
  // Euclidean algorithm
  while (m !== 0) {
    [a, m] = [m, a % m];
  }
  return a === 1;
}

function mod(n, m) {
  // JS % is remainder, not true mod for negatives
  return ((n % m) + m) % m;
}

function mmi(a, m) {
  // Extended Euclidean Algorithm to find modular multiplicative inverse
  let m0 = m, x0 = 0, x1 = 1;
  if (m === 1) return 0;
  while (a > 1) {
    let q = Math.floor(a / m);
    [a, m] = [m, a % m];
    [x0, x1] = [x1 - q * x0, x0];
  }
  if (x1 < 0) x1 += m0;
  return x1;
}

function cleanInput(phrase) {
  // Lowercase, remove punctuation, keep digits and letters
  return phrase
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

function groupOutput(text, groupSize = 5) {
  return text.replace(new RegExp(`(.{1,${groupSize}})`, 'g'), '$1 ').trim();
}

export const encode = (phrase, key) => {
  const { a, b } = key;
  if (!isCoprime(a, M)) {
    throw new Error('a and m must be coprime.');
  }
  const input = cleanInput(phrase);
  let result = '';
  for (let char of input) {
    if (/[a-z]/.test(char)) {
      const i = char.charCodeAt(0) - 97;
      const enc = mod(a * i + b, M);
      result += ALPHABET[enc];
    } else if (/[0-9]/.test(char)) {
      result += char;
    }
    // ignore all else
  }
  return groupOutput(result);
};

export const decode = (phrase, key) => {
  const { a, b } = key;
  if (!isCoprime(a, M)) {
    throw new Error('a and m must be coprime.');
  }
  const a_inv = mmi(a, M);
  // Remove spaces, keep digits and letters
  const input = phrase.replace(/[^a-z0-9]/gi, '').toLowerCase();
  let result = '';
  for (let char of input) {
    if (/[a-z]/.test(char)) {
      const y = char.charCodeAt(0) - 97;
      const dec = mod(a_inv * (y - b), M);
      result += ALPHABET[dec];
    } else if (/[0-9]/.test(char)) {
      result += char;
    }
    // ignore all else
  }
  return result;
};
