export const encode = (numbers) => {
  if (!Array.isArray(numbers)) {
    throw new Error('Input must be an array of numbers');
  }
  const result = [];
  for (const number of numbers) {
    if (!Number.isInteger(number) || number < 0 || number > 0xFFFFFFFF) {
      throw new Error('Input contains invalid number');
    }
    if (number === 0) {
      result.push(0x00);
      continue;
    }
    const bytes = [];
    let n = number;
    while (n > 0) {
      bytes.unshift(n & 0x7F);
      n >>>= 7;
    }
    for (let i = 0; i < bytes.length - 1; i++) {
      bytes[i] |= 0x80; // set continuation bit
    }
    result.push(...bytes);
  }
  return result;
};

export const decode = (bytes) => {
  if (!Array.isArray(bytes)) {
    throw new Error('Input must be an array of bytes');
  }
  const result = [];
  let value = 0;
  let seen = false;
  for (let i = 0; i < bytes.length; i++) {
    const byte = bytes[i];
    if (byte < 0 || byte > 0xFF) {
      throw new Error('Input contains invalid byte');
    }
    value = (value << 7) | (byte & 0x7F);
    seen = true;
    if ((byte & 0x80) === 0) {
      result.push(value >>> 0); // ensure unsigned
      value = 0;
      seen = false;
    }
  }
  if (seen) {
    throw new Error('Incomplete sequence');
  }
  return result;
};
