/**
 * Count the number of rectangles in an ASCII diagram.
 * @param {string[]} diagram - Array of strings representing the ASCII diagram.
 * @returns {number} - The number of rectangles found.
 */
export function count(diagram) {
  if (!diagram || diagram.length === 0) return 0;

  const rows = diagram.length;
  const cols = diagram[0].length;
  let rectangles = 0;

  // Helper to check if all chars between (row, col1) and (row, col2) are '-' or '+'
  function isHorizontalEdge(row, col1, col2) {
    for (let c = col1 + 1; c < col2; c++) {
      if (diagram[row][c] !== '-' && diagram[row][c] !== '+') {
        return false;
      }
    }
    return true;
  }

  // Helper to check if all chars between (row1, col) and (row2, col) are '|' or '+'
  function isVerticalEdge(col, row1, row2) {
    for (let r = row1 + 1; r < row2; r++) {
      if (diagram[r][col] !== '|' && diagram[r][col] !== '+') {
        return false;
      }
    }
    return true;
  }

  // Find all pairs of '+' in the same row (potential top edges)
  for (let r1 = 0; r1 < rows; r1++) {
    for (let c1 = 0; c1 < cols; c1++) {
      if (diagram[r1][c1] !== '+') continue;
      for (let c2 = c1 + 1; c2 < cols; c2++) {
        if (diagram[r1][c2] !== '+') continue;
        // Check top edge
        if (!isHorizontalEdge(r1, c1, c2)) continue;
        // Now look for matching bottom edges
        for (let r2 = r1 + 1; r2 < rows; r2++) {
          // Both corners must be '+'
          if (diagram[r2][c1] !== '+' || diagram[r2][c2] !== '+') continue;
          // Check bottom edge
          if (!isHorizontalEdge(r2, c1, c2)) continue;
          // Check left and right vertical edges
          if (!isVerticalEdge(c1, r1, r2)) continue;
          if (!isVerticalEdge(c2, r1, r2)) continue;
          // All checks passed, found a rectangle
          rectangles++;
        }
      }
    }
  }

  return rectangles;
}
