const SHARP_SCALE = [
  'A', 'A#', 'B', 'C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#'
];

const FLAT_SCALE = [
  'A', 'Bb', 'B', 'C', 'Db', 'D', 'Eb', 'E', 'F', 'Gb', 'G', 'Ab'
];

// Tonics that use the flat scale
const FLAT_TONICS = [
  'F', 'Bb', 'Eb', 'Ab', 'Db', 'Gb',
  'd', 'g', 'c', 'f', 'bb', 'eb'
];

// Tonics that use the sharp scale
const SHARP_TONICS = [
  'C', 'G', 'D', 'A', 'E', 'B', 'F#',
  'a', 'e', 'b', 'f#', 'c#', 'g#', 'd#'
];

// Helper to capitalize tonic properly
function formatTonic(tonic) {
  if (tonic.length === 1) {
    return tonic[0].toUpperCase();
  }
  if (tonic[1] === 'b' || tonic[1] === '#') {
    return tonic[0].toUpperCase() + tonic[1];
  }
  return tonic[0].toUpperCase() + tonic.slice(1);
}

function getScaleType(tonic) {
  // Use flats if tonic is in FLAT_TONICS, else sharps
  if (FLAT_TONICS.includes(tonic)) {
    return 'flat';
  }
  return 'sharp';
}

function getChromaticScale(tonic) {
  const scaleType = getScaleType(tonic);
  const scale = scaleType === 'flat' ? FLAT_SCALE : SHARP_SCALE;
  const formattedTonic = formatTonic(tonic);
  const idx = scale.findIndex(
    note => note.toUpperCase() === formattedTonic.toUpperCase()
  );
  // Rotate scale so it starts with tonic
  return [...scale.slice(idx), ...scale.slice(0, idx)];
}

export class Scale {
  constructor(tonic) {
    this.tonic = tonic;
    this.formattedTonic = formatTonic(tonic);
    this.scaleType = getScaleType(tonic);
    this.chromaticScale = getChromaticScale(tonic);
  }

  chromatic() {
    // Return all 12 notes, starting with tonic, in correct case
    return this.chromaticScale.map(note => {
      // Always uppercase except for 'b' in flats
      if (note.length === 2 && note[1] === 'b') {
        return note[0].toUpperCase() + 'b';
      }
      return note.toUpperCase();
    });
  }

  interval(intervals) {
    // intervals: string like 'MMmMMMm'
    const notes = [];
    let idx = 0;
    notes.push(
      this.chromaticScale[idx].length === 2 && this.chromaticScale[idx][1] === 'b'
        ? this.chromaticScale[idx][0].toUpperCase() + 'b'
        : this.chromaticScale[idx].toUpperCase()
    );
    for (let i = 0; i < intervals.length; i++) {
      const step = intervals[i];
      if (step === 'm') {
        idx += 1;
      } else if (step === 'M') {
        idx += 2;
      } else if (step === 'A') {
        idx += 3;
      } else {
        throw new Error(`Unknown interval: ${step}`);
      }
      idx = idx % this.chromaticScale.length;
      const note = this.chromaticScale[idx];
      notes.push(
        note.length === 2 && note[1] === 'b'
          ? note[0].toUpperCase() + 'b'
          : note.toUpperCase()
      );
    }
    return notes;
  }
}
