//
// This is only a SKELETON file for the 'Two Bucket' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

export class TwoBucket {
  constructor(bucketOneCap, bucketTwoCap, goal, startBucket) {
    this.bucketOneCap = bucketOneCap;
    this.bucketTwoCap = bucketTwoCap;
    this.goal = goal;
    this.startBucket = startBucket;
    this.result = this._solve();
  }

  solve() {
    return this.result;
  }

  _solve() {
    // Helper to simulate the process
    // Returns {moves, goalBucket, otherBucket}
    // We'll use BFS to avoid cycles and to find the shortest solution

    const cap1 = this.bucketOneCap;
    const cap2 = this.bucketTwoCap;
    const goal = this.goal;
    const start = this.startBucket;

    // State: [bucket1, bucket2]
    // Track visited states to avoid cycles
    const visited = new Set();

    // Each queue entry: [bucket1, bucket2, moves, lastAction]
    // lastAction is not strictly needed, but could be used for debugging
    let initial;
    if (start === 'one') {
      initial = [cap1, 0, 1]; // fill bucket one
    } else {
      initial = [0, cap2, 1]; // fill bucket two
    }

    const queue = [initial];
    visited.add(`${initial[0]},${initial[1]}`);

    while (queue.length > 0) {
      const [b1, b2, moves] = queue.shift();

      // Check for goal
      if (b1 === goal) {
        return {
          moves,
          goalBucket: 'one',
          otherBucket: b2
        };
      }
      if (b2 === goal) {
        return {
          moves,
          goalBucket: 'two',
          otherBucket: b1
        };
      }

      // Generate all possible next states (actions)
      const nextStates = [];

      // 1. Fill bucket one
      if (b1 < cap1) {
        nextStates.push([cap1, b2]);
      }
      // 2. Fill bucket two
      if (b2 < cap2) {
        nextStates.push([b1, cap2]);
      }
      // 3. Empty bucket one
      if (b1 > 0) {
        nextStates.push([0, b2]);
      }
      // 4. Empty bucket two
      if (b2 > 0) {
        nextStates.push([b1, 0]);
      }
      // 5. Pour bucket one -> bucket two
      if (b1 > 0 && b2 < cap2) {
        const pour = Math.min(b1, cap2 - b2);
        nextStates.push([b1 - pour, b2 + pour]);
      }
      // 6. Pour bucket two -> bucket one
      if (b2 > 0 && b1 < cap1) {
        const pour = Math.min(b2, cap1 - b1);
        nextStates.push([b1 + pour, b2 - pour]);
      }

      for (const [nb1, nb2] of nextStates) {
        // Rule: may not arrive at a state where the initial starting bucket is empty and the other bucket is full
        if (
          (start === 'one' && nb1 === 0 && nb2 === cap2) ||
          (start === 'two' && nb2 === 0 && nb1 === cap1)
        ) {
          continue;
        }
        const key = `${nb1},${nb2}`;
        if (!visited.has(key)) {
          visited.add(key);
          queue.push([nb1, nb2, moves + 1]);
        }
      }
    }

    // If we get here, no solution
    throw new Error('No solution');
  }
}
