//
// This is only a SKELETON file for the 'Zipper' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

// A binary tree node is expected to have the shape:
// { value: any, left: node|null, right: node|null }

export class Zipper {
  // The zipper keeps track of the current focus node and the path to it.
  // The path is a stack of { direction: 'left'|'right', value, sibling } objects.
  constructor(focus, path = []) {
    this._focus = focus;
    this._path = path;
  }

  // Create a zipper from a tree (focus on root)
  static fromTree(tree) {
    return new Zipper(cloneTree(tree), []);
  }

  // Get the full tree from the zipper
  toTree() {
    let node = this._focus;
    let path = this._path;
    while (path.length > 0) {
      const { direction, value, sibling } = path[path.length - 1];
      if (direction === 'left') {
        node = { value, left: node, right: sibling };
      } else {
        node = { value, left: sibling, right: node };
      }
      path = path.slice(0, -1);
    }
    return node;
  }

  // Get the value at the focus
  value() {
    return this._focus ? this._focus.value : undefined;
  }

  // Move focus to the left child
  left() {
    if (!this._focus || !this._focus.left) return null;
    const { value, left, right } = this._focus;
    return new Zipper(
      left,
      this._path.concat([{ direction: 'left', value, sibling: right }])
    );
  }

  // Move focus to the right child
  right() {
    if (!this._focus || !this._focus.right) return null;
    const { value, left, right } = this._focus;
    return new Zipper(
      right,
      this._path.concat([{ direction: 'right', value, sibling: left }])
    );
  }

  // Move focus to the parent
  up() {
    if (this._path.length === 0) return null;
    const { direction, value, sibling } = this._path[this._path.length - 1];
    let parent;
    if (direction === 'left') {
      parent = { value, left: this._focus, right: sibling };
    } else {
      parent = { value, left: sibling, right: this._focus };
    }
    return new Zipper(parent, this._path.slice(0, -1));
  }

  // Set the value at the focus, return new zipper
  setValue(value) {
    if (!this._focus) return null;
    const { left, right } = this._focus;
    return new Zipper({ value, left, right }, this._path);
  }

  // Set the left child, return new zipper
  setLeft(left) {
    if (!this._focus) return null;
    const { value, right } = this._focus;
    return new Zipper({ value, left, right }, this._path);
  }

  // Set the right child, return new zipper
  setRight(right) {
    if (!this._focus) return null;
    const { value, left } = this._focus;
    return new Zipper({ value, left, right }, this._path);
  }
}

// Helper to deep clone a tree (to avoid mutation)
function cloneTree(node) {
  if (!node) return null;
  return {
    value: node.value,
    left: cloneTree(node.left),
    right: cloneTree(node.right),
  };
}
