import java.lang.reflect.Array;

class SimpleLinkedList<T> {
    private Node<T> head;
    private int size;

    // Node class for singly linked list
    private static class Node<T> {
        T data;
        Node<T> next;

        Node(T data) {
            this.data = data;
        }
    }

    // Default constructor: creates an empty list
    SimpleLinkedList() {
        this.head = null;
        this.size = 0;
    }

    // Constructor from array (pushes in order so first element is head)
    SimpleLinkedList(T[] values) {
        this();
        if (values != null) {
            // Insert in reverse order so that first element is head
            for (int i = values.length - 1; i >= 0; i--) {
                push(values[i]);
            }
        }
    }

    // Push a value onto the head of the list
    void push(T value) {
        Node<T> newNode = new Node<>(value);
        newNode.next = head;
        head = newNode;
        size++;
    }

    // Pop a value from the head of the list
    T pop() {
        if (head == null) {
            throw new java.util.NoSuchElementException("List is empty");
        }
        T value = head.data;
        head = head.next;
        size--;
        return value;
    }

    // Reverse the linked list in place
    void reverse() {
        Node<T> prev = null;
        Node<T> current = head;
        while (current != null) {
            Node<T> nextNode = current.next;
            current.next = prev;
            prev = current;
            current = nextNode;
        }
        head = prev;
    }

    // Convert the linked list to an array
    T[] asArray(Class<T> clazz) {
        @SuppressWarnings("unchecked")
        T[] array = (T[]) Array.newInstance(clazz, size);
        Node<T> current = head;
        int i = 0;
        while (current != null) {
            array[i++] = current.data;
            current = current.next;
        }
        return array;
    }

    // Return the size of the list
    int size() {
        return size;
    }
}
