//
// This is only a SKELETON file for the 'Bottle Song' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

function bottleCountString(n) {
  if (n === 0) return 'no green bottles';
  if (n === 1) return 'one green bottle';
  return `${numberToWords(n)} green bottles`;
}

function numberToWords(n) {
  // Only need 0-10 for this song
  const words = [
    'zero', 'one', 'two', 'three', 'four',
    'five', 'six', 'seven', 'eight', 'nine', 'ten'
  ];
  return words[n];
}

function capitalize(str) {
  return str.charAt(0).toUpperCase() + str.slice(1);
}

export const recite = (initialBottlesCount, takeDownCount) => {
  const verses = [];
  for (let i = 0; i < takeDownCount; i++) {
    const current = initialBottlesCount - i;
    const next = current - 1;

    const currentBottles = capitalize(bottleCountString(current));
    const nextBottles = bottleCountString(next);

    verses.push(
      `${currentBottles} hanging on the wall,`,
      `${currentBottles} hanging on the wall,`,
      `And if one green bottle should accidentally fall,`,
      `There'll be ${nextBottles} hanging on the wall.`
    );

    // Add a blank line between verses, except after the last one
    if (i < takeDownCount - 1) {
      verses.push('');
    }
  }
  return verses;
};
