//
// This is only a SKELETON file for the 'Pig Latin' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

const VOWELS = ['a', 'e', 'i', 'o', 'u'];

function isVowel(char) {
  return VOWELS.includes(char);
}

function startsWithVowel(word) {
  return isVowel(word[0]);
}

function startsWithXrOrYt(word) {
  return word.startsWith('xr') || word.startsWith('yt');
}

function getConsonantCluster(word) {
  // Find the index of the first vowel or 'y' (for Rule 4)
  // But if 'y' is at the start, it's not a vowel
  for (let i = 0; i < word.length; i++) {
    if (isVowel(word[i]) || (word[i] === 'y' && i !== 0)) {
      return i;
    }
  }
  return 0;
}

function translateWord(word) {
  // Rule 1: starts with vowel or "xr"/"yt"
  if (startsWithVowel(word) || startsWithXrOrYt(word)) {
    return word + 'ay';
  }

  // Rule 3: starts with consonant(s) + "qu"
  const quMatch = word.match(/^([^aeiou]*qu)(.*)/);
  if (quMatch) {
    return quMatch[2] + quMatch[1] + 'ay';
  }

  // Rule 4: consonant(s) + "y"
  const yMatch = word.match(/^([^aeiou]+)(y.*)/);
  if (yMatch) {
    return yMatch[2] + yMatch[1] + 'ay';
  }

  // Rule 2: consonant(s) at the start
  const clusterLen = getConsonantCluster(word);
  if (clusterLen > 0) {
    return word.slice(clusterLen) + word.slice(0, clusterLen) + 'ay';
  }

  // Fallback (shouldn't be needed)
  return word + 'ay';
}

export const translate = (text) => {
  return text
    .split(' ')
    .map(translateWord)
    .join(' ');
};
