const VALID_OPTIONS = [
  'n', // add line numbers
  'l', // print file names where pattern is found
  'i', // ignore case
  'v', // reverse files results
  'x', // match entire line
];

const ARGS = process.argv;

// --- Begin implementation ---

// Parse arguments
function parseArgs(args) {
  // args[0] = node, args[1] = script, args[2...] = user args
  const userArgs = args.slice(2);
  let flags = [];
  let search = null;
  let files = [];

  // Collect flags
  let i = 0;
  while (i < userArgs.length && userArgs[i].startsWith('-')) {
    const flagStr = userArgs[i].slice(1);
    for (const c of flagStr) {
      if (VALID_OPTIONS.includes(c) && !flags.includes(c)) {
        flags.push(c);
      }
    }
    i++;
  }

  // Next arg is search string
  if (i < userArgs.length) {
    search = userArgs[i];
    i++;
  }

  // Remaining args are files
  files = userArgs.slice(i);

  return { flags, search, files };
}

function matchLine(line, search, flags) {
  let { i: ignoreCase, x: matchEntire } = Object.fromEntries(flags.map(f => [f, true]));
  let lineToCheck = line;
  let searchToCheck = search;

  if (ignoreCase) {
    lineToCheck = lineToCheck.toLowerCase();
    searchToCheck = searchToCheck.toLowerCase();
  }

  if (matchEntire) {
    return lineToCheck === searchToCheck;
  } else {
    return lineToCheck.includes(searchToCheck);
  }
}

function processFile(filename, search, flags) {
  const lines = readLines(filename);
  const results = [];
  let found = false;
  let { v: invert } = Object.fromEntries(flags.map(f => [f, true]));

  for (let idx = 0; idx < lines.length; idx++) {
    const line = lines[idx];
    const isMatch = matchLine(line, search, flags);
    const finalMatch = invert ? !isMatch : isMatch;
    if (finalMatch) {
      results.push({ line, idx });
      found = true;
    }
  }
  return { results, found };
}

function main() {
  const { flags, search, files } = parseArgs(ARGS);

  if (!search || files.length === 0) {
    // Not enough arguments
    process.exit(1);
  }

  const showLineNumbers = flags.includes('n');
  const showFileNamesOnly = flags.includes('l');
  const multipleFiles = files.length > 1;

  let output = [];

  if (showFileNamesOnly) {
    // Only print file names that have at least one match
    for (const file of files) {
      const { found } = processFile(file, search, flags);
      if (found) {
        output.push(file);
      }
    }
  } else {
    for (const file of files) {
      const { results } = processFile(file, search, flags);
      for (const { line, idx } of results) {
        let outLine = '';
        if (multipleFiles) {
          outLine += file + ':';
        }
        if (showLineNumbers) {
          outLine += (idx + 1) + ':';
        }
        outLine += line;
        output.push(outLine);
      }
    }
  }

  if (output.length > 0) {
    console.log(output.join('\n'));
  }
}

main();
