  };
}

export class RestAPI {
  constructor(database = null) {
    // database is an array of user objects
    if (database) {
      // Deep clone to avoid mutation
      this.users = deepClone(database.users);
    } else {
      this.users = [];
    }
  }

  getUserByName(name) {
    return this.users.find((u) => u.name === name);
  }

  get(url) {
    // Only /users endpoint is supported
    // url can be "/users" or "/users?users=Adam,Bob"
    const [path, query] = url.split("?");
    if (path !== "/users") {
      throw new Error("Unknown GET endpoint");
    }
    let usersToReturn;
    if (!query) {
      // Return all users
      usersToReturn = this.users
        .map((u) => userObject(u))
        .sort((a, b) => a.name.localeCompare(b.name));
    } else {
      // Parse query string
      const params = new URLSearchParams(query);
      const usersParam = params.get("users");
      if (!usersParam) {
        usersToReturn = [];
      } else {
        const names = usersParam.split(",");
        usersToReturn = names
          .map((name) => this.getUserByName(name))
          .filter((u) => u)
          .map((u) => userObject(u))
          .sort((a, b) => a.name.localeCompare(b.name));
      }
    }
    return { users: usersToReturn };
  }

  post(url, payload) {
    if (url === "/add") {
      // payload: { "user": <name> }
      const name = payload.user;
      if (this.getUserByName(name)) {
        throw new Error("User already exists");
      }
      const newUser = {
        name,
        owes: {},
        owed_by: {},
      };
      this.users.push(newUser);
      return userObject(newUser);
    } else if (url === "/iou") {
      // payload: { "lender": <name>, "borrower": <name>, "amount": <number> }
      const { lender, borrower, amount } = payload;
      if (lender === borrower) {
        throw new Error("Lender and borrower cannot be the same");
      }
      const lenderUser = this.getUserByName(lender);
      const borrowerUser = this.getUserByName(borrower);
      if (!lenderUser || !borrowerUser) {
        throw new Error("Lender or borrower does not exist");
      }

      // Set up default values
      if (!lenderUser.owed_by[borrower]) lenderUser.owed_by[borrower] = 0;
      if (!lenderUser.owes[borrower]) lenderUser.owes[borrower] = 0;
      if (!borrowerUser.owes[lender]) borrowerUser.owes[lender] = 0;
      if (!borrowerUser.owed_by[lender]) borrowerUser.owed_by[lender] = 0;

      // If lender owes borrower, net out
      if (lenderUser.owes[borrower] > 0) {
        if (lenderUser.owes[borrower] >= amount) {
          lenderUser.owes[borrower] -= amount;
          borrowerUser.owed_by[lender] -= amount;
        } else {
          const remainder = amount - lenderUser.owes[borrower];
          lenderUser.owes[borrower] = 0;
          borrowerUser.owed_by[lender] = 0;
          lenderUser.owed_by[borrower] += remainder;
          borrowerUser.owes[lender] += remainder;
        }
      } else {
        lenderUser.owed_by[borrower] += amount;
        borrowerUser.owes[lender] += amount;
      }

      // Remove zero entries for cleanliness
      if (lenderUser.owes[borrower] === 0) delete lenderUser.owes[borrower];
      if (lenderUser.owed_by[borrower] === 0) delete lenderUser.owed_by[borrower];
      if (borrowerUser.owes[lender] === 0) delete borrowerUser.owes[lender];
      if (borrowerUser.owed_by[lender] === 0) delete borrowerUser.owed_by[lender];

      // Return updated user objects for lender and borrower, sorted by name
      const resultUsers = [userObject(lenderUser), userObject(borrowerUser)].sort((a, b) =>
        a.name.localeCompare(b.name)
      );
      return { users: resultUsers };
    } else {
      throw new Error("Unknown POST endpoint");
    }
  }
