export class Triangle {
  constructor(...sides) {
    this.sides = sides;
  }

  // Helper to check if the triangle is valid
  get isValid() {
    const [a, b, c] = this.sides;
    // All sides must be > 0
    if (a <= 0 || b <= 0 || c <= 0) {
      return false;
    }
    // Triangle inequality: sum of any two sides >= third side
    if (a + b < c) return false;
    if (b + c < a) return false;
    if (a + c < b) return false;
    return true;
  }

  get isEquilateral() {
    if (!this.isValid) return false;
    const [a, b, c] = this.sides;
    return a === b && b === c;
  }

  get isIsosceles() {
    if (!this.isValid) return false;
    const [a, b, c] = this.sides;
    return a === b || b === c || a === c;
  }

  get isScalene() {
    if (!this.isValid) return false;
    const [a, b, c] = this.sides;
    return a !== b && b !== c && a !== c;
  }
}
