package pov

type Tree struct {
	value    string
	children []*Tree
}

// New creates and returns a new Tree with the given root value and children.
func New(value string, children ...*Tree) *Tree {
	return &Tree{
		value:    value,
		children: children,
	}
}

// Value returns the value at the root of a tree.
func (tr *Tree) Value() string {
	return tr.value
}

// Children returns a slice containing the children of a tree.
// There is no need to sort the elements in the result slice,
// they can be in any order.
func (tr *Tree) Children() []*Tree {
	return tr.children
}

// String describes a tree in a compact S-expression format.
// This helps to make test outputs more readable.
// Feel free to adapt this method as you see fit.
func (tr *Tree) String() string {
	if tr == nil {
		return "nil"
	}
	result := tr.Value()
	if len(tr.Children()) == 0 {
		return result
	}
	for _, ch := range tr.Children() {
		result += " " + ch.String()
	}
	return "(" + result + ")"
}

// findPath finds the path from the current node to the node with the given value.
// It returns the path as a slice of pointers to Tree nodes, or nil if not found.
func (tr *Tree) findPath(value string) []*Tree {
	if tr == nil {
		return nil
	}
	if tr.value == value {
		return []*Tree{tr}
	}
	for _, child := range tr.children {
		if path := child.findPath(value); path != nil {
			return append([]*Tree{tr}, path...)
		}
	}
	return nil
}

// cloneTree clones a tree, returning a new tree with the same structure and values.
func cloneTree(tr *Tree) *Tree {
	if tr == nil {
		return nil
	}
	newChildren := make([]*Tree, len(tr.children))
	for i, child := range tr.children {
		newChildren[i] = cloneTree(child)
	}
	return &Tree{
		value:    tr.value,
		children: newChildren,
	}
}

// FromPov returns the pov from the node specified in the argument.
func (tr *Tree) FromPov(from string) *Tree {
	path := tr.findPath(from)
	if path == nil {
		return nil
	}
	// Re-root the tree at the node with value "from"
	var reroot func(path []*Tree, idx int) *Tree
	reroot = func(path []*Tree, idx int) *Tree {
		node := path[idx]
		// Remove the parent from children to avoid cycles
		var newChildren []*Tree
		for _, child := range node.children {
			if idx+1 < len(path) && child == path[idx+1] {
				continue
			}
			newChildren = append(newChildren, cloneTree(child))
		}
		if idx > 0 {
			// Add the parent as a child, rerooted
			newChildren = append(newChildren, reroot(path, idx-1))
		}
		return &Tree{
			value:    node.value,
			children: newChildren,
		}
	}
	return reroot(path, len(path)-1)
}

// PathTo returns the shortest path between two nodes in the tree.
func (tr *Tree) PathTo(from, to string) []string {
	// First, re-root the tree at "from"
	newRoot := tr.FromPov(from)
	if newRoot == nil {
		return nil
	}
	// Now, find the path from newRoot to "to"
	path := newRoot.findPath(to)
	if path == nil {
		return nil
	}
	result := make([]string, len(path))
	for i, node := range path {
		result[i] = node.value
	}
	return result
}
