package tree

import (
	"errors"
	"sort"
)

type Record struct {
	ID     int
	Parent int
	// feel free to add fields as you see fit
}

type Node struct {
	ID       int
	Children []*Node
	// feel free to add fields as you see fit
}

func Build(records []Record) (*Node, error) {
	n := len(records)
	if n == 0 {
		return nil, nil
	}

	// Sort records by ID to make validation and tree building easier
	sort.Slice(records, func(i, j int) bool {
		return records[i].ID < records[j].ID
	})

	// Validation: IDs must be continuous from 0 to n-1
	for i, rec := range records {
		if rec.ID != i {
			return nil, errors.New("non-continuous IDs")
		}
	}

	nodes := make([]*Node, n)
	for i := 0; i < n; i++ {
		nodes[i] = &Node{ID: i}
	}

	var root *Node

	for _, rec := range records {
		if rec.ID == 0 {
			// Root node: parent must be itself
			if rec.Parent != 0 {
				return nil, errors.New("root node has invalid parent")
			}
			root = nodes[0]
		} else {
			if rec.Parent >= rec.ID {
				return nil, errors.New("node has invalid parent")
			}
			parent := nodes[rec.Parent]
			parent.Children = append(parent.Children, nodes[rec.ID])
		}
	}

	if root == nil {
		return nil, errors.New("no root node found")
	}

	return root, nil
}
