package alphametics

import (
	"errors"
	"strings"
	"unicode"
)

// Helper to extract unique letters and leading letters from the puzzle
func extractLetters(words []string) ([]string, map[string]bool) {
	lettersMap := make(map[string]bool)
	leading := make(map[string]bool)
	for _, word := range words {
		for i, r := range word {
			letter := string(r)
			lettersMap[letter] = true
			if i == 0 && len(word) > 1 {
				leading[letter] = true
			}
		}
	}
	letters := make([]string, 0, len(lettersMap))
	for k := range lettersMap {
		letters = append(letters, k)
	}
	return letters, leading
}

// Helper to convert a word to its numeric value given a mapping
func wordToNumber(word string, mapping map[string]int) int {
	n := 0
	for _, r := range word {
		n = n*10 + mapping[string(r)]
	}
	return n
}

// Backtracking solver
func solveRecursive(words []string, result string, letters []string, leading map[string]bool, mapping map[string]int, used map[int]bool, idx int) (map[string]int, bool) {
	if idx == len(letters) {
		// All letters assigned, check if solution is valid
		sum := 0
		for _, w := range words {
			// Leading zero check
			if len(w) > 1 && mapping[string(w[0])] == 0 {
				return nil, false
			}
			sum += wordToNumber(w, mapping)
		}
		// Leading zero check for result
		if len(result) > 1 && mapping[string(result[0])] == 0 {
			return nil, false
		}
		if sum == wordToNumber(result, mapping) {
			// Copy mapping to string->int map
			solution := make(map[string]int)
			for k, v := range mapping {
				solution[k] = v
			}
			return solution, true
		}
		return nil, false
	}

	letter := letters[idx]
	for d := 0; d <= 9; d++ {
		if used[d] {
			continue
		}
		// Don't assign 0 to a leading letter
		if d == 0 && leading[letter] {
			continue
		}
		mapping[letter] = d
		used[d] = true
		if sol, ok := solveRecursive(words, result, letters, leading, mapping, used, idx+1); ok {
			return sol, true
		}
		delete(mapping, letter)
		used[d] = false
	}
	return nil, false
}

func Solve(puzzle string) (map[string]int, error) {
	// Remove spaces
	puzzle = strings.ReplaceAll(puzzle, " ", "")
	// Split into left and right of ==
	parts := strings.Split(puzzle, "==")
	if len(parts) != 2 {
		return nil, errors.New("invalid puzzle format")
	}
	left := parts[0]
	right := parts[1]

	// Split left by +
	words := strings.Split(left, "+")
	// Validate words and result
	for _, w := range words {
		if w == "" {
			return nil, errors.New("invalid puzzle format")
		}
	}
	if right == "" {
		return nil, errors.New("invalid puzzle format")
	}

	// Validate all are uppercase letters
	for _, w := range append(words, right) {
		for _, r := range w {
			if !unicode.IsUpper(r) {
				return nil, errors.New("puzzle must use only uppercase letters")
			}
		}
	}

	// Extract unique letters and leading letters
	letters, leading := extractLetters(append(words, right))
	if len(letters) > 10 {
		return nil, errors.New("too many unique letters")
	}

	// Backtracking search
	mapping := make(map[string]int)
	used := make(map[int]bool)
	if sol, ok := solveRecursive(words, right, letters, leading, mapping, used, 0); ok {
		return sol, nil
	}
	return nil, errors.New("no solution")
}
