package cryptosquare

import (
	"strings"
	"unicode"
	"math"
)

func Encode(pt string) string {
	// Normalize the input: remove non-alphanumeric, downcase
	normalized := make([]rune, 0, len(pt))
	for _, r := range pt {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			normalized = append(normalized, unicode.ToLower(r))
		}
	}
	normStr := string(normalized)
	n := len(normStr)
	if n == 0 {
		return ""
	}

	// Determine rectangle size: c >= r, c - r <= 1, r*c >= n
	var r, c int
	c = int(math.Ceil(math.Sqrt(float64(n))))
	r = int(math.Floor(math.Sqrt(float64(n))))
	if r*c < n {
		r++
	}
	if c < r {
		c, r = r, c
	}

	// Pad the normalized string to fit the rectangle
	padLen := r*c - n
	if padLen > 0 {
		normStr += strings.Repeat(" ", padLen)
	}

	// Build the rows
	rows := make([]string, r)
	for i := 0; i < r; i++ {
		rows[i] = normStr[i*c : (i+1)*c]
	}

	// Read down the columns to build the encoded chunks
	chunks := make([]string, c)
	for col := 0; col < c; col++ {
		var sb strings.Builder
		for row := 0; row < r; row++ {
			sb.WriteByte(rows[row][col])
		}
		chunks[col] = sb.String()
	}

	return strings.Join(chunks, " ")
}
