package piglatin

import (
	"strings"
	"unicode"
)

func isVowel(r rune) bool {
	switch r {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}

func startsWithVowelOrSpecial(word string) bool {
	if len(word) < 1 {
		return false
	}
	if isVowel(rune(word[0])) {
		return true
	}
	if strings.HasPrefix(word, "xr") || strings.HasPrefix(word, "yt") {
		return true
	}
	return false
}

func firstVowelIndex(word string) int {
	for i, r := range word {
		if isVowel(r) {
			return i
		}
		// 'y' is only a vowel if not at the start
		if r == 'y' && i != 0 {
			return i
		}
	}
	return -1
}

func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	for i, word := range words {
		words[i] = pigLatinWord(word)
	}
	return strings.Join(words, " ")
}

func pigLatinWord(word string) string {
	// Rule 1: starts with vowel or "xr"/"yt"
	if startsWithVowelOrSpecial(word) {
		return word + "ay"
	}

	// Rule 3: starts with consonant(s) + "qu"
	if idx := strings.Index(word, "qu"); idx != -1 && idx != 0 {
		// "qu" must be after some consonant(s)
		if allConsonants(word[:idx]) {
			return word[idx+2:] + word[:idx+2] + "ay"
		}
	}
	if strings.HasPrefix(word, "qu") {
		return word[2:] + "quay"
	}

	// Rule 4: consonant(s) + "y"
	for i := 1; i < len(word); i++ {
		if word[i] == 'y' && allConsonants(word[:i]) {
			return word[i:] + word[:i] + "ay"
		}
	}

	// Rule 2: move leading consonant(s) to end, add "ay"
	for i, r := range word {
		if isVowel(r) {
			return word[i:] + word[:i] + "ay"
		}
		// 'y' is not a vowel at the start, but is after consonants (handled above)
	}
	return word + "ay"
}

func allConsonants(s string) bool {
	for _, r := range s {
		if isVowel(r) {
			return false
		}
		if !unicode.IsLetter(r) {
			return false
		}
		if r == 'y' {
			return false
		}
	}
	return len(s) > 0
}
