package wordy

import (
	"strconv"
	"strings"
	"unicode"
)

func Answer(question string) (int, bool) {
	// Trim and check prefix/suffix
	question = strings.TrimSpace(question)
	if !strings.HasPrefix(question, "What is ") || !strings.HasSuffix(question, "?") {
		return 0, false
	}
	// Remove prefix and suffix
	question = strings.TrimPrefix(question, "What is ")
	question = strings.TrimSuffix(question, "?")
	question = strings.TrimSpace(question)

	if question == "" {
		return 0, false
	}

	// Supported operations
	type opFunc func(int, int) int
	ops := map[string]opFunc{
		"plus":        func(a, b int) int { return a + b },
		"minus":       func(a, b int) int { return a - b },
		"multiplied by": func(a, b int) int { return a * b },
		"divided by":    func(a, b int) int { return a / b },
	}

	// Tokenize: split by spaces, but handle "multiplied by" and "divided by" as single tokens
	tokens := []string{}
	words := strings.FieldsFunc(question, func(r rune) bool {
		return unicode.IsSpace(r)
	})
	for i := 0; i < len(words); i++ {
		if i+1 < len(words) {
			two := words[i] + " " + words[i+1]
			if two == "multiplied by" || two == "divided by" {
				tokens = append(tokens, two)
				i++
				continue
			}
		}
		tokens = append(tokens, words[i])
	}

	// Parse: expect number, then (op, number) pairs
	if len(tokens) == 0 {
		return 0, false
	}

	// Parse first number
	num, err := strconv.Atoi(tokens[0])
	if err != nil {
		return 0, false
	}
	result := num
	i := 1
	for i < len(tokens) {
		// Next should be an operator
		op := tokens[i]
		opFunc, ok := ops[op]
		if !ok {
			return 0, false
		}
		i++
		if i >= len(tokens) {
			return 0, false // missing number after operator
		}
		// Next should be a number
		num, err := strconv.Atoi(tokens[i])
		if err != nil {
			return 0, false
		}
		result = opFunc(result, num)
		i++
	}
	return result, true
}
