package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML
func Render(markdown string) string {
	lines := strings.Split(markdown, "\n")
	var html strings.Builder
	inList := false

	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}

		// Handle headers
		if strings.HasPrefix(trimmed, "#") {
			headerLevel := 0
			for headerLevel < len(trimmed) && trimmed[headerLevel] == '#' {
				headerLevel++
			}
			// Only headers up to h6 are valid, otherwise treat as paragraph
			if headerLevel > 0 && headerLevel <= 6 && (len(trimmed) == headerLevel || trimmed[headerLevel] == ' ') {
				content := strings.TrimSpace(trimmed[headerLevel:])
				content = parseInline(content)
				html.WriteString(fmt.Sprintf("<h%d>%s</h%d>", headerLevel, content, headerLevel))
				continue
			}
		}

		// Handle unordered lists
		if strings.HasPrefix(trimmed, "* ") {
			if !inList {
				html.WriteString("<ul>")
				inList = true
			}
			content := strings.TrimSpace(trimmed[2:])
			content = parseInline(content)
			html.WriteString(fmt.Sprintf("<li>%s</li>", content))

			// If it's the last line or next line is not a list, close the list
			if i+1 == len(lines) || !strings.HasPrefix(strings.TrimSpace(lines[i+1]), "* ") {
				html.WriteString("</ul>")
				inList = false
			}
			continue
		}

		// Handle paragraphs
		content := parseInline(trimmed)
		html.WriteString(fmt.Sprintf("<p>%s</p>", content))
	}

	return html.String()
}

// parseInline handles inline markdown for strong and emphasis
func parseInline(text string) string {
	// Replace __text__ with <strong>text</strong>
	for strings.Contains(text, "__") {
		start := strings.Index(text, "__")
		end := strings.Index(text[start+2:], "__")
		if end == -1 {
			break
		}
		end += start + 2
		strongText := text[start+2 : end]
		text = text[:start] + "<strong>" + strongText + "</strong>" + text[end+2:]
	}

	// Replace _text_ with <em>text</em>
	for strings.Contains(text, "_") {
		start := strings.Index(text, "_")
		end := strings.Index(text[start+1:], "_")
		if end == -1 {
			break
		}
		end += start + 1
		emText := text[start+1 : end]
		text = text[:start] + "<em>" + emText + "</em>" + text[end+1:]
	}

	return text
}
