		catchLine: "",
	},
}

func Verse(v int) string {
	v = v - 1 // zero-based index
	var sb strings.Builder

	sb.WriteString("I know an old lady who swallowed a " + verses[v].animal + ".\n")
	if verses[v].comment != "" {
		sb.WriteString(verses[v].comment + "\n")
	}

	if verses[v].animal == "horse" {
		// Last verse, special case
		return strings.TrimRight(sb.String(), "\n")
	}

	// Cumulative part
	for i := v; i > 0; i-- {
		sb.WriteString("She swallowed the " + verses[i].animal + " to catch the " + verses[i-1].catchLineOrAnimal() + ".\n")
	}

	sb.WriteString("I don't know why she swallowed the fly. Perhaps she'll die.")

	return strings.TrimRight(sb.String(), "\n")
}

func (av animalVerse) catchLineOrAnimal() string {
	if av.animal == "spider" {
		return av.catchLine
	}
	return av.animal
}

func Verses(start, end int) string {
	var sb strings.Builder
	for i := start; i <= end; i++ {
		sb.WriteString(Verse(i))
		if i != end {
			sb.WriteString("\n\n")
		}
	}
	return sb.String()
}

func Song() string {
	return Verses(1, len(verses))
}
