function formatRow(entry, locale, currency) {
  const config = LOCALE_CONFIG[locale];
  const dateStr = config.dateFormatter(entry.date);
  const descStr = config.descriptionFormatter(entry.description);
  const changeStr = config.currencyFormatter(currency, entry.change).padStart(
    config.header[2].width,
    ' ',
  );
  return `${dateStr} | ${descStr} | ${changeStr}`;
}

export function formatEntries(currency, locale, entries) {
  if (!LOCALE_CONFIG[locale]) {
    throw new Error(`Unsupported locale: ${locale}`);
  }
  let table = '';
  table += formatHeader(locale) + '\n';

  sortEntries(entries);

  entries.forEach((entry) => {
    table += formatRow(entry, locale, currency) + '\n';
  });

  return table.replace(/\n$/, '');
}
