import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Solver for Alphametics puzzles such as `SEND + MORE == MONEY`.
 */
class Alphametics {

    private final List<String> addends = new ArrayList<>();
    private final String resultWord;
    private final List<Character> letters = new ArrayList<>();
    private final Set<Character> leadingLetters = new HashSet<>();
    private final String puzzle;

    Alphametics(String userInput) {
        this.puzzle = userInput;
        // Normalise the input: remove spaces so that parsing is easier
        String trimmed = userInput.replaceAll("\\s+", "");

        // Split into left-hand side and right-hand side
        String[] sides = trimmed.split("==|=");
        if (sides.length != 2) {
            throw new IllegalArgumentException("Invalid puzzle format: " + userInput);
        }
        String lhs = sides[0];
        this.resultWord = sides[1];

        // The LHS may contain one or more addends separated by '+'
        for (String word : lhs.split("\\+")) {
            if (word.isEmpty()) {
                throw new IllegalArgumentException("Invalid addend in puzzle: " + userInput);
            }
            addends.add(word);
        }

        // Collect all unique letters and note leading letters (cannot be zero)
        collectLetters();
    }

    /**
     * Solve the puzzle and return a mapping from character to digit.
     *
     * @throws UnsolvablePuzzleException if no solution exists
     */
    Map<Character, Integer> solve() throws UnsolvablePuzzleException {
        if (letters.size() > 10) {
            throw new UnsolvablePuzzleException();
        }

        int[] letterToDigit = new int[26];
        for (int i = 0; i < 26; i++) {
            letterToDigit[i] = -1;   // -1 indicates “unassigned”
        }
        boolean[] usedDigit = new boolean[10];

        if (search(0, letterToDigit, usedDigit)) {
            // Build and return the mapping
            Map<Character, Integer> solution = new LinkedHashMap<>();
            for (Character c : letters) {
                solution.put(c, letterToDigit[c - 'A']);
            }
            return solution;
        }
        throw new UnsolvablePuzzleException();
    }

    /* --------------------------------------------------------------------- */

    private void collectLetters() {
        // Process addends
        for (String word : addends) {
            addLeadingLetter(word);
            addLettersFromWord(word);
        }
        // Process result word
        addLeadingLetter(resultWord);
        addLettersFromWord(resultWord);
    }

    private void addLeadingLetter(String word) {
        if (word.length() > 1) {
            leadingLetters.add(word.charAt(0));
        }
    }

    private void addLettersFromWord(String word) {
        for (char c : word.toCharArray()) {
            if (!letters.contains(c)) {
                letters.add(c);
            }
        }
    }

    /**
     * Recursive back-tracking search for a valid assignment.
     *
     * @param index         Which letter (in {@code letters}) we are about to assign.
     * @param letterToDigit Mapping from letter to digit (partial).
     * @param usedDigit     Flag indicating which digits are already in use.
     * @return {@code true} if a complete valid assignment has been found.
     */
    private boolean search(int index, int[] letterToDigit, boolean[] usedDigit) {
        if (index == letters.size()) {
            return checkSolution(letterToDigit);
        }

        char current = letters.get(index);
        for (int digit = 0; digit <= 9; digit++) {
            if (usedDigit[digit]) {
                continue;
            }
            // Leading letters cannot be assigned the digit 0
            if (digit == 0 && leadingLetters.contains(current)) {
                continue;
            }

            // Assign and recurse
            letterToDigit[current - 'A'] = digit;
            usedDigit[digit] = true;

            if (search(index + 1, letterToDigit, usedDigit)) {
                return true;
            }

            // Backtrack
            letterToDigit[current - 'A'] = -1;
            usedDigit[digit] = false;
        }
        return false;
    }

    private boolean checkSolution(int[] letterToDigit) {
        long sum = 0;
        for (String word : addends) {
            long value = wordToNumber(word, letterToDigit);
            if (value < 0) {
                return false; // Some letter unassigned – should not happen.
            }
            sum += value;
        }
        long resultValue = wordToNumber(resultWord, letterToDigit);
        return sum == resultValue;
    }

    private long wordToNumber(String word, int[] letterToDigit) {
        long value = 0;
        for (char c : word.toCharArray()) {
            int digit = letterToDigit[c - 'A'];
            if (digit < 0) {
                return -1;
            }
            value = value * 10 + digit;
        }
        return value;
    }

    @Override
    public String toString() {
        return "Alphametics{" + puzzle + '}';
    }
}
