package scale

import "strings"

// sharp and flat chromatic scales expressed with ASCII accidentals.
// The order of notes is fixed and starts on A so that both slices are the
// same length and index-aligned. We will rotate the slice so that the tonic
// is at index 0 when building a scale.
var (
	sharpChromatic = []string{
		"A", "A#", "B", "C", "C#", "D",
		"D#", "E", "F", "F#", "G", "G#",
	}

	flatChromatic = []string{
		"A", "Bb", "B", "C", "Db", "D",
		"Eb", "E", "F", "Gb", "G", "Ab",
	}
)

// tonics that, by music theory convention, use the sharp chromatic spelling
var sharpsTonics = map[string]bool{
	"C": true, "G": true, "D": true, "A": true,
	"E": true, "B": true, "F#": true, "e": true,
	"b": true, "f#": true, "c#": true, "g#": true,
	"d#": true, "a": true,
}

// tonics that use the flat chromatic spelling
var flatsTonics = map[string]bool{
	"F": true, "Bb": true, "Eb": true, "Ab": true,
	"Db": true, "Gb": true, "d": true, "g": true,
	"c": true, "f": true, "bb": true, "eb": true,
}

// canonicalTonic converts the provided tonic to its canonical representation:
// first letter uppercase, accidentals (# or b) preserved.
func canonicalTonic(t string) string {
	if len(t) == 0 {
		return t
	}
	builder := strings.Builder{}
	builder.WriteString(strings.ToUpper(string(t[0])))
	if len(t) > 1 {
		builder.WriteString(t[1:])
	}
	return builder.String()
}

// chooseChromatic returns the chromatic scale (sharp or flat) appropriate
// for the given tonic.
func chooseChromatic(tonic string) []string {
	if sharpsTonics[tonic] {
		return sharpChromatic
	}
	if flatsTonics[tonic] {
		return flatChromatic
	}
	// Default to sharps if tonic not found in either set
	return sharpChromatic
}

// rotate takes a slice and an index and returns a new slice that starts
// from the given index, continuing circularly.
func rotate(scale []string, startIdx int) []string {
	l := len(scale)
	result := make([]string, l)
	for i := 0; i < l; i++ {
		result[i] = scale[(startIdx+i)%l]
	}
	return result
}

// stepWidth maps interval runes to their corresponding widths in the
// chromatic scale.
var stepWidth = map[rune]int{
	'm': 1, // half step
	'M': 2, // whole step
	'A': 3, // augmented second
}

// Scale generates either a chromatic or a diatonic/derived scale.
//
// If `interval` is an empty string the full 12-note chromatic scale is
// returned starting on `tonic`.
// Otherwise the returned slice has len(interval)+1 notes where each interval
// character determines how many semitones to move to reach the next note.
func Scale(tonic, interval string) []string {
	// Canonicalise tonic for internal processing and for output.
	cTonic := canonicalTonic(tonic)

	// Decide whether we should work with the sharp or flat chromatic scale.
	base := chooseChromatic(tonic)

	// Locate the tonic within the chosen chromatic scale.
	startIdx := 0
	for i, n := range base {
		if n == cTonic {
			startIdx = i
			break
		}
	}

	// Rotate so that the tonic is the first element.
	fullScale := rotate(base, startIdx)

	// If no interval pattern provided, return the full chromatic scale.
	if len(interval) == 0 {
		return fullScale
	}

	// Build the scale according to the interval pattern.
	result := []string{cTonic}
	pos := 0
	for _, r := range interval {
		step, ok := stepWidth[r]
		if !ok {
			// Unsupported interval symbol; ignore (or could panic).
			continue
		}
		pos = (pos + step) % len(fullScale)
		result = append(result, fullScale[pos])
	}

	return result
}
