package twobucket

import "errors"

// Solve determines the minimum number of actions required to reach the
// goalAmount.  It returns the bucket that ends with the goal amount
// ("one" or "two"), the number of steps taken, the litres left in the
// other bucket, and a possible error.
//
// The algorithm performs a breadth-first search over all reachable
// states (amount of water in bucket one and bucket two).  Each edge in
// the search space represents exactly one valid action (fill, empty,
// pour).  The first time we encounter a state in which either bucket
// holds the goal amount we are guaranteed to have found the shortest
// sequence of actions, so we can immediately return.
func Solve(sizeBucketOne, sizeBucketTwo, goalAmount int, startBucket string) (goalBucket string, numSteps, otherBucketLevel int, e error) {
	// ------------------------- validation -----------------------------
	if sizeBucketOne <= 0 || sizeBucketTwo <= 0 {
		return "", 0, 0, errors.New("bucket sizes must be positive")
	}
	if goalAmount <= 0 || goalAmount > max(sizeBucketOne, sizeBucketTwo) {
		return "", 0, 0, errors.New("invalid goal amount")
	}
	if startBucket != "one" && startBucket != "two" {
		return "", 0, 0, errors.New(`startBucket must be "one" or "two"`)
	}

	// Starting state (first action = fill the starting bucket)
	type state struct {
		a, b int // current volumes in bucket one and bucket two
	}

	var initial state
	if startBucket == "one" {
		initial = state{sizeBucketOne, 0}
	} else {
		initial = state{0, sizeBucketTwo}
	}

	// Immediate success check
	if initial.a == goalAmount {
		return "one", 1, initial.b, nil
	}
	if initial.b == goalAmount {
		return "two", 1, initial.a, nil
	}

	// -------------------------- BFS setup -----------------------------
	queue := []state{initial}
	steps := []int{1}

	visited := make(map[state]bool)
	visited[initial] = true

	// Helper to check forbidden states
	isForbidden := func(s state) bool {
		if startBucket == "one" {
			return s.a == 0 && s.b == sizeBucketTwo
		}
		return s.b == 0 && s.a == sizeBucketOne
	}

	for len(queue) > 0 {
		// pop front
		curr := queue[0]
		currSteps := steps[0]
		queue = queue[1:]
		steps = steps[1:]

		// Generate next states (= every possible single action)
		nextStates := make([]state, 0, 6)

		// 1. Pour from one -> two
		pour := min(curr.a, sizeBucketTwo-curr.b)
		nextStates = append(nextStates, state{curr.a - pour, curr.b + pour})

		// 2. Pour from two -> one
		pour = min(curr.b, sizeBucketOne-curr.a)
		nextStates = append(nextStates, state{curr.a + pour, curr.b - pour})

		// 3. Empty bucket one
		nextStates = append(nextStates, state{0, curr.b})

		// 4. Empty bucket two
		nextStates = append(nextStates, state{curr.a, 0})

		// 5. Fill bucket one
		nextStates = append(nextStates, state{sizeBucketOne, curr.b})

		// 6. Fill bucket two
		nextStates = append(nextStates, state{curr.a, sizeBucketTwo})

		for _, nxt := range nextStates {
			if visited[nxt] || isForbidden(nxt) {
				continue
			}
			visited[nxt] = true

			nxtSteps := currSteps + 1

			// Check for success
			if nxt.a == goalAmount {
				return "one", nxtSteps, nxt.b, nil
			}
			if nxt.b == goalAmount {
				return "two", nxtSteps, nxt.a, nil
			}

			queue = append(queue, nxt)
			steps = append(steps, nxtSteps)
		}
	}

	return "", 0, 0, errors.New("no solution possible")
}

// --------------------------------------------------------------------

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}
