/**
 * Return a Date object describing the meetup date.
 *
 * @param {number} year        – four–digit year (e.g. 2023)
 * @param {number} month       – 1-based month number (1 = January … 12 = December)
 * @param {string} descriptor  – 'first' | 'second' | 'third' | 'fourth' | 'last' | 'teenth'
 * @param {string} weekday     – 'Sunday' … 'Saturday'
 * @returns {Date}
 */
export const meetup = (year, month, descriptor, weekday) => {
  const weekdays = {
    Sunday: 0,
    Monday: 1,
    Tuesday: 2,
    Wednesday: 3,
    Thursday: 4,
    Friday: 5,
    Saturday: 6,
  };

  if (!(weekday in weekdays)) {
    throw new Error('Invalid weekday supplied');
  }

  const targetWeekday = weekdays[weekday];
  const monthIndex = month - 1; // JavaScript Date months are zero-based.
  let date = null;

  /**
   * Helper that finds the first date in [start, end] matching the weekday.
   */
  const findInRange = (start, end) => {
    for (let day = start; day <= end; day += 1) {
      const current = new Date(year, monthIndex, day);
      if (current.getDay() === targetWeekday) {
        return current;
      }
    }
    return null;
  };

  switch (descriptor) {
    case 'teenth':
      // Days 13 – 19 are the "teenth" days.
      date = findInRange(13, 19);
      break;

    case 'first':
      date = findInRange(1, 7);
      break;
    case 'second':
      date = findInRange(8, 14);
      break;
    case 'third':
      date = findInRange(15, 21);
      break;
    case 'fourth':
      date = findInRange(22, 28);
      break;

    case 'last': {
      // Day 0 of the following month gives the last day of the current month.
      const lastDay = new Date(year, month, 0).getDate();
      // Search backwards through the last 7 possible days.
      for (let day = lastDay; day >= lastDay - 6; day -= 1) {
        const current = new Date(year, monthIndex, day);
        if (current.getDay() === targetWeekday) {
          date = current;
          break;
        }
      }
      break;
    }

    default:
      throw new Error('Invalid descriptor supplied');
  }

  // All valid inputs should resolve a date; guard just in case.
  if (!date) {
    throw new Error('Unable to determine meetup date');
  }

  return date;
};
