// 1 different book  -> no discount
// 2 different books -> 5%  discount
// 3 different books -> 10% discount
// 4 different books -> 20% discount
// 5 different books -> 25% discount
//
// The function works for any combination of books from the 5-book series.
func Cost(books []int) int {
	// Count how many copies we have of each of the 5 titles.
	var counts [5]int
	for _, b := range books {
		if b >= 1 && b <= 5 { // Ignore any invalid book numbers.
			counts[b-1]++
		}
	}

	// Memoisation map to cache already-calculated states.
	memo := make(map[[5]int]int)
	return minCost(counts, memo)
}

// minCost returns the minimal cost (in cents) for the remaining basket
// represented by `counts`.  It uses memoisation to avoid recomputation.
func minCost(counts [5]int, memo map[[5]int]int) int {
	if v, ok := memo[counts]; ok {
		return v
	}

	// Check if the basket is empty.
	sum := 0
	for _, c := range counts {
		sum += c
	}
	if sum == 0 {
		return 0
	}

	// Pre-computed prices for each possible group size (index == size).
	// Index 0 is unused.
	groupCost := [...]int{
		0,    // 0 books – not used
		800,  // 1 book : 800 cents
		1520, // 2 books: 1600 * 0.95
		2160, // 3 books: 2400 * 0.90
		2560, // 4 books: 3200 * 0.80
		3000, // 5 books: 4000 * 0.75
	}

	// Worst-case cost: all books bought individually with no discount.
	best := sum * 800

	// Try every possible non-empty subset (bitmask) of titles.
	for mask := 1; mask < 1<<5; mask++ {
		var (
			newCounts [5]int
			size      int
			valid     = true
		)

		// Build the newCounts after removing one copy of each chosen title.
		for i := 0; i < 5; i++ {
			newCounts[i] = counts[i]
			if mask&(1<<i) != 0 {
				if counts[i] == 0 {
					valid = false
					break
				}
				newCounts[i]--
				size++
			}
		}
		if !valid {
			continue
		}

		// Cost of this grouping plus the optimal cost of the remainder.
		cost := groupCost[size] + minCost(newCounts, memo)
		if cost < best {
			best = cost
		}
	}

	memo[counts] = best
	return best
}
