package alphametics

import (
	"fmt"
	"strings"
)

// Solve tries to find a substitution of digits for the letters contained in the
// provided puzzle so that the arithmetic equation is valid.
//
// The puzzle must contain one "==" that separates the left-hand side from the
// right-hand side and zero or more "+" on the left-hand side.
//
// Each letter represents a single decimal digit; identical letters share the
// same digit and different letters must map to different digits.  A leading
// letter of a multi-digit word must never be mapped to 0.
//
// On success it returns a map that associates every letter that occurs in the
// puzzle with its digit (0-9).  When the puzzle is unsolvable an error is
// returned.
func Solve(puzzle string) (map[string]int, error) {
	// 1. Remove all spaces to simplify further parsing.
	puzzle = strings.ReplaceAll(puzzle, " ", "")

	parts := strings.Split(puzzle, "==")
	if len(parts) != 2 {
		return nil, fmt.Errorf("input must contain exactly one '=='")
	}
	leftPart, rightWord := parts[0], parts[1]
	if leftPart == "" || rightWord == "" {
		return nil, fmt.Errorf("malformed puzzle")
	}

	leftWords := strings.Split(leftPart, "+")
	words := append(leftWords, rightWord)

	// 2. Collect all unique letters and the set of letters that cannot be zero.
	lettersSet := make(map[byte]struct{})
	nonZeroSet := make(map[byte]struct{})
	for _, w := range words {
		if len(w) > 1 {
			nonZeroSet[w[0]] = struct{}{}
		}
		for i := 0; i < len(w); i++ {
			lettersSet[w[i]] = struct{}{}
		}
	}

	if len(lettersSet) > 10 {
		return nil, fmt.Errorf("more than 10 unique letters – impossible to map to digits 0-9")
	}

	// Convert set to deterministic slice to get reproducible results.
	letters := make([]byte, 0, len(lettersSet))
	for ch := range lettersSet {
		letters = append(letters, ch)
	}

	// 3. Prepare fast word-value computation: cache powers of 10 for each
	//    position so we can compute the numeric value with a single loop.
	type wordInfo struct {
		chars []byte   // letters of the word as bytes, left→right
		pow10 []int64  // pre-computed 10^n for each char position
	}
	prepare := func(w string) wordInfo {
		chars := []byte(w)
		pow10 := make([]int64, len(chars))
		p := int64(1)
		for i := len(chars) - 1; i >= 0; i-- {
			pow10[i] = p
			p *= 10
		}
		return wordInfo{chars: chars, pow10: pow10}
	}

	leftInfos := make([]wordInfo, len(leftWords))
	for i, w := range leftWords {
		leftInfos[i] = prepare(w)
	}
	rightInfo := prepare(rightWord)

	// 4. Start backtracking.
	assign := make(map[byte]int) // current letter→digit assignment
	used := [10]bool{}           // which digits are already used

	var dfs func(idx int) bool
	dfs = func(idx int) bool {
		if idx == len(letters) {
			// All letters assigned – check whether the equation holds.
			leftSum := int64(0)
			for _, info := range leftInfos {
				val := int64(0)
				for i, ch := range info.chars {
					val += int64(assign[ch]) * info.pow10[i]
				}
				leftSum += val
			}
			rightVal := int64(0)
			for i, ch := range rightInfo.chars {
				rightVal += int64(assign[ch]) * rightInfo.pow10[i]
			}
			return leftSum == rightVal
		}

		ch := letters[idx]
		for digit := 0; digit <= 9; digit++ {
			if used[digit] {
				continue
			}
			if digit == 0 {
				if _, forbidden := nonZeroSet[ch]; forbidden {
					continue // leading letter can't be zero
				}
			}
			assign[ch] = digit
			used[digit] = true

			if dfs(idx + 1) {
				return true
			}

			// backtrack
			delete(assign, ch)
			used[digit] = false
		}
		return false
	}

	if !dfs(0) {
		return nil, fmt.Errorf("no solution")
	}

	// Build the result map with string keys as required.
	res := make(map[string]int, len(assign))
	for ch, digit := range assign {
		res[string(ch)] = digit
	}
	return res, nil
}
