package bottlesong

import (
	"fmt"
	"strings"
)

// Recite returns the lyrics of "Ten Green Bottles" starting from
// `startBottles` and reciting `takeDown` verses.
func Recite(startBottles, takeDown int) []string {
	var result []string

	for i := 0; i < takeDown; i++ {
		bottles := startBottles - i
		result = append(result, buildVerse(bottles)...)

		// add a blank line between verses except after the last
		if i != takeDown-1 {
			result = append(result, "")
		}
	}

	return result
}

// buildVerse constructs a single verse for the given bottle count.
func buildVerse(n int) []string {
	next := n - 1
	if next < 0 {
		next = 0
	}

	line1 := fmt.Sprintf("%s green %s hanging on the wall,", capitalize(word(n)), bottleWord(n))
	line2 := line1
	line3 := "And if one green bottle should accidentally fall,"
	line4 := fmt.Sprintf("There'll be %s green %s hanging on the wall.", word(next), bottleWord(next))

	return []string{line1, line2, line3, line4}
}

// bottleWord returns "bottle" for 1, otherwise "bottles".
func bottleWord(count int) string {
	if count == 1 {
		return "bottle"
	}
	return "bottles"
}

// word returns the English word for the numbers 0-10.
// Outside that range it returns the numeric string.
func word(n int) string {
	words := []string{
		"no",
		"one",
		"two",
		"three",
		"four",
		"five",
		"six",
		"seven",
		"eight",
		"nine",
		"ten",
	}

	if n >= 0 && n < len(words) {
		return words[n]
	}
	return fmt.Sprintf("%d", n)
}

// capitalize makes the first letter of s uppercase.
func capitalize(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}
