package protein

import "errors"

// ErrStop should be returned by FromCodon when a STOP codon is encountered.
var ErrStop = errors.New("STOP")

// ErrInvalidBase should be returned by FromCodon when the codon contains invalid bases.
var ErrInvalidBase = errors.New("invalid codon")

// codonToProtein maps RNA codons to their corresponding proteins (or "STOP").
var codonToProtein = map[string]string{
	"AUG": "Methionine",

	"UUU": "Phenylalanine",
	"UUC": "Phenylalanine",

	"UUA": "Leucine",
	"UUG": "Leucine",

	"UCU": "Serine",
	"UCC": "Serine",
	"UCA": "Serine",
	"UCG": "Serine",

	"UAU": "Tyrosine",
	"UAC": "Tyrosine",

	"UGU": "Cysteine",
	"UGC": "Cysteine",

	"UGG": "Tryptophan",

	"UAA": "STOP",
	"UAG": "STOP",
	"UGA": "STOP",
}

// FromRNA translates a full RNA strand into a slice of proteins.
// Translation stops (without error) when a stop codon is encountered.
// If the RNA contains an invalid codon an error is returned.
func FromRNA(rna string) ([]string, error) {
	var proteins []string

	// The RNA strand must be processed three nucleotides (one codon) at a time.
	for i := 0; i+3 <= len(rna); i += 3 {
		codon := rna[i : i+3]

		protein, err := FromCodon(codon)
		switch err {
		case nil:
			proteins = append(proteins, protein)
		case ErrStop:
			return proteins, nil
		default:
			return nil, err
		}
	}

	// If there are leftover nucleotides they form an invalid (incomplete) codon.
	if len(rna)%3 != 0 {
		return nil, ErrInvalidBase
	}

	return proteins, nil
}

// FromCodon translates a single codon into its corresponding protein.
// If the codon is a stop codon, ErrStop is returned.
// If the codon is unknown, ErrInvalidBase is returned.
func FromCodon(codon string) (string, error) {
	protein, ok := codonToProtein[codon]
	if !ok {
		return "", ErrInvalidBase
	}
	if protein == "STOP" {
		return "", ErrStop
	}
	return protein, nil
}
