namespace {

// Random-name generator helpers.
std::string generate_random_name() {
    static std::random_device rd;
    static std::mt19937 engine(rd());
    static std::uniform_int_distribution<int> letter_dist('A', 'Z');
    static std::uniform_int_distribution<int> digit_dist(0, 9);

    std::string name(5, '\0');
    name[0] = static_cast<char>(letter_dist(engine));
    name[1] = static_cast<char>(letter_dist(engine));
    name[2] = static_cast<char>('0' + digit_dist(engine));
    name[3] = static_cast<char>('0' + digit_dist(engine));
    name[4] = static_cast<char>('0' + digit_dist(engine));
    return name;
}

// Global registry of names currently in use.
std::unordered_set<std::string> used_names;

// Produce a name that is not currently in the registry.
std::string generate_unique_name() {
    std::string candidate;
    do {
        candidate = generate_random_name();
    } while (used_names.find(candidate) != used_names.end());

    used_names.insert(candidate);
    return candidate;
}

} // namespace

namespace robot_name {

robot::robot() : name_(generate_unique_name()) {}

const std::string& robot::name() const {
    return name_;
}

void robot::reset() {
    // Reserve new unique name; keep the old one in the registry to
    // guarantee uniqueness among *existing* robots.
    name_ = generate_unique_name();
}

}  // namespace robot_name
