// Produce a name that is not currently in the registry.
std::string generate_unique_name() {
    std::string candidate;
    do {
        candidate = generate_random_name();
    } while (used_names.find(candidate) != used_names.end());

    used_names.insert(candidate);
    return candidate;
}

} // namespace

namespace robot_name {

robot::robot() : name_(::generate_unique_name()) {}

const std::string& robot::name() const {
    return name_;
}

void robot::reset() {
    // Reserve new unique name; keep the old one in the registry to
    // guarantee uniqueness among *existing* robots.
    name_ = ::generate_unique_name();
}

}  // namespace robot_name
