import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Objects;
import java.util.Queue;
import java.util.Set;
import java.util.function.Consumer;
import java.util.function.Function;

public class React {

    /**
     * Base class for every cell in the system.
     * Holds the current value and the list of dependent compute cells.
     */
    public static class Cell<T> {
        protected T value;
        protected final List<ComputeCell<?>> dependents = new ArrayList<>();

        public T getValue() {
            return value;
        }

        protected void addDependent(ComputeCell<?> cell) {
            dependents.add(cell);
        }
    }

    /**
     * A cell whose value can be set directly by the user.
     */
    public static class InputCell<T> extends Cell<T> {

        public InputCell(T initialValue) {
            this.value = initialValue;
        }

        /**
         * Update the value and propagate the change through the dependency graph.
         * If the new value is equal to the current value nothing happens.
         */
        public void setValue(T newValue) {
            if (Objects.equals(this.value, newValue)) {
                return; // No actual change, nothing to do.
            }
            this.value = newValue;
            propagateChanges(this.dependents);
        }
    }

    /**
     * A cell whose value is computed from other cells.
     */
    public static class ComputeCell<T> extends Cell<T> {
        private final Function<List<T>, T> computeFunction;
        private final List<Cell<T>> sources;
        private final List<Consumer<T>> callbacks = new ArrayList<>();

        public ComputeCell(Function<List<T>, T> function, List<Cell<T>> cells) {
            this.computeFunction = function;
            this.sources = new ArrayList<>(cells);

            // Register as dependent on every source cell.
            for (Cell<T> source : cells) {
                source.addDependent(this);
            }

            // Compute the initial value.
            this.value = computeValue();
        }

        public void addCallback(Consumer<T> callback) {
            if (callback != null) {
                callbacks.add(callback);
            }
        }

        public void removeCallback(Consumer<T> callback) {
            callbacks.remove(callback);
        }

        /**
         * Compute the value based on current source values.
         */
        private T computeValue() {
            List<T> values = new ArrayList<>(sources.size());
            for (Cell<T> cell : sources) {
                values.add(cell.getValue());
            }
            return computeFunction.apply(values);
        }

        /**
         * Recompute the value. Returns true if the value actually changed.
         */
        private boolean recompute() {
            T newValue = computeValue();
            if (Objects.equals(newValue, this.value)) {
                return false;
            }
            this.value = newValue;
            return true;
        }

        /**
         * Invoke every registered callback with the current value.
         */
        private void runCallbacks() {
            for (Consumer<T> cb : callbacks) {
                cb.accept(this.value);
            }
        }
    }

    /**
     * Factory for an input cell.
     */
    public static <T> InputCell<T> inputCell(T initialValue) {
        return new InputCell<>(initialValue);
    }

    /**
     * Factory for a compute cell.
     */
    public static <T> ComputeCell<T> computeCell(Function<List<T>, T> function, List<Cell<T>> cells) {
        return new ComputeCell<>(function, cells);
    }

    /**
     * Propagate value changes through the dependency graph until the system is stable,
     * then execute callbacks for every compute cell whose value has changed.
     */
    private static void propagateChanges(List<ComputeCell<?>> initialDependents) {
        Queue<ComputeCell<?>> queue = new ArrayDeque<>(initialDependents);
        Set<ComputeCell<?>> changedCells = new LinkedHashSet<>();

        while (!queue.isEmpty()) {
            ComputeCell<?> cell = queue.remove();
            if (cell.recompute()) {
                changedCells.add(cell);
                queue.addAll(cell.dependents);
            }
        }

        // Now the system is in a stable state. Fire callbacks for all changed cells.
        for (ComputeCell<?> cell : changedCells) {
            cell.runCallbacks();
        }
    }
}
