use std::collections::HashMap;

/// Count occurrences of words.
pub fn word_count(words: &str) -> HashMap<String, u32> {
    let mut counts: HashMap<String, u32> = HashMap::new();
    let mut current = String::new();

    // Build tokens made of ASCII letters, digits, or apostrophes.
    for ch in words.chars() {
        if ch.is_ascii_alphanumeric() || ch == '\'' {
            // Store characters in lowercase to make counting case-insensitive.
            current.push(ch.to_ascii_lowercase());
        } else if !current.is_empty() {
            // A delimiter finished the current token.
            let trimmed = current.trim_matches('\'');
            if !trimmed.is_empty() {
                *counts.entry(trimmed.to_string()).or_insert(0) += 1;
            }
            current.clear();
        }
    }

    // Handle the final token, if the subtitle doesn't end with a delimiter.
    if !current.is_empty() {
        let trimmed = current.trim_matches('\'');
        if !trimmed.is_empty() {
            *counts.entry(trimmed.to_string()).or_insert(0) += 1;
        }
    }

    counts
}
