import java.util.*;

/**
 * Solve the classic “two bucket” (or “water jug”) puzzle.
 *
 * Given two buckets of different capacities and the bucket that must be filled
 * first, find the minimum sequence of actions that leaves exactly
 * {@code desiredLiters} in one of the buckets while respecting the rules
 * described in the exercise.
 *
 * The constructor performs the search and stores the results so the three
 * accessor methods can simply return the cached values.
 */
class TwoBucket {

    private final int totalMoves;
    private final String finalBucket;
    private final int otherBucket;

    /**
     * Create a new puzzle instance and immediately solve it.
     *
     * @param bucketOneCap  capacity of bucket one
     * @param bucketTwoCap  capacity of bucket two
     * @param desiredLiters target volume to measure
     * @param startBucket   which bucket must be filled first ("one" or "two")
     * @throws IllegalArgumentException if the puzzle has no solution that
     *                                  satisfies the given rules
     */
    TwoBucket(int bucketOneCap, int bucketTwoCap, int desiredLiters, String startBucket) {
        if (!"one".equals(startBucket) && !"two".equals(startBucket)) {
            throw new IllegalArgumentException("startBucket must be \"one\" or \"two\"");
        }
        if (desiredLiters < 0
                || desiredLiters > Math.max(bucketOneCap, bucketTwoCap)) {
            throw new IllegalArgumentException("Desired liters out of range.");
        }

        Result result = solve(bucketOneCap, bucketTwoCap, desiredLiters, startBucket);

        // If no result is found throw an exception – the tests expect an exception
        // for impossible exercises.
        if (result == null) {
            throw new IllegalArgumentException("No solution can be found.");
        }

        this.totalMoves = result.moves;
        this.finalBucket = result.finalBucket;
        this.otherBucket = result.otherBucket;
    }

    int getTotalMoves() {
        return totalMoves;
    }

    String getFinalBucket() {
        return finalBucket;
    }

    int getOtherBucket() {
        return otherBucket;
    }

    /* ---------------------------------------------------------------------- */
    /* ---------------------------  private logic  -------------------------- */
    /* ---------------------------------------------------------------------- */

    /**
     * Represents a particular state in the search space.
     */
    private static final class State {
        final int v1;       // current volume in bucket one
        final int v2;       // current volume in bucket two
        final int moves;    // number of actions taken so far

        State(int v1, int v2, int moves) {
            this.v1 = v1;
            this.v2 = v2;
            this.moves = moves;
        }

        String key() {
            // Unique key for visited-set; capacities are small so a simple string is fine.
            return v1 + "/" + v2;
        }
    }

    /**
     * Holds the outcome once the desired number of liters has been reached.
     */
    private static final class Result {
        final int moves;
        final String finalBucket;
        final int otherBucket;

        Result(int moves, String finalBucket, int otherBucket) {
            this.moves = moves;
            this.finalBucket = finalBucket;
            this.otherBucket = otherBucket;
        }
    }

    /**
     * Breadth-first search through the state space to find the minimal
     * sequence of moves that reaches the goal.
     */
    private Result solve(int cap1, int cap2, int goal, String startBucket) {
        Queue<State> queue = new ArrayDeque<>();
        Set<String> visited = new HashSet<>();

        // Initial state: first action is to fill the starting bucket.
        State initial;
        if ("one".equals(startBucket)) {
            initial = new State(cap1, 0, 1);   // filled bucket one
        } else {
            initial = new State(0, cap2, 1);   // filled bucket two
        }

        queue.add(initial);
        visited.add(initial.key());

        while (!queue.isEmpty()) {
            State current = queue.poll();

            // Check for success
            if (current.v1 == goal || current.v2 == goal) {
                String finalBucket = current.v1 == goal ? "one" : "two";
                int other = current.v1 == goal ? current.v2 : current.v1;
                return new Result(current.moves, finalBucket, other);
            }

            // Generate all possible next states.

            // 1. Fill bucket one
            enqueueIfValid(queue, visited,
                    new State(cap1, current.v2, current.moves + 1),
                    cap1, cap2, startBucket);

            // 2. Fill bucket two
            enqueueIfValid(queue, visited,
                    new State(current.v1, cap2, current.moves + 1),
                    cap1, cap2, startBucket);

            // 3. Empty bucket one
            enqueueIfValid(queue, visited,
                    new State(0, current.v2, current.moves + 1),
                    cap1, cap2, startBucket);

            // 4. Empty bucket two
            enqueueIfValid(queue, visited,
                    new State(current.v1, 0, current.moves + 1),
                    cap1, cap2, startBucket);

            // 5. Pour bucket one -> bucket two
            int spaceInTwo = cap2 - current.v2;
            if (current.v1 > 0 && spaceInTwo > 0) {
                int transfer = Math.min(current.v1, spaceInTwo);
                enqueueIfValid(queue, visited,
                        new State(current.v1 - transfer, current.v2 + transfer, current.moves + 1),
                        cap1, cap2, startBucket);
            }

            // 6. Pour bucket two -> bucket one
            int spaceInOne = cap1 - current.v1;
            if (current.v2 > 0 && spaceInOne > 0) {
                int transfer = Math.min(current.v2, spaceInOne);
                enqueueIfValid(queue, visited,
                        new State(current.v1 + transfer, current.v2 - transfer, current.moves + 1),
                        cap1, cap2, startBucket);
            }
        }

        // Exhausted the search space without success
        return null;
    }

    /**
     * Validate the candidate state against the rule that forbids reaching a
     * configuration where the starting bucket is empty and the other bucket is
     * full, then add it to the queue/visited sets if unseen.
     */
    private void enqueueIfValid(Queue<State> queue,
                                Set<String> visited,
                                State candidate,
                                int cap1,
                                int cap2,
                                String startBucket) {

        // Rule: may not reach a state where the starting bucket is empty
        // and the other bucket is full.
        boolean forbidden =
                ("one".equals(startBucket) && candidate.v1 == 0 && candidate.v2 == cap2) ||
                ("two".equals(startBucket) && candidate.v2 == 0 && candidate.v1 == cap1);

        if (forbidden) {
            return;
        }

        if (visited.add(candidate.key())) {
            queue.add(candidate);
        }
    }
}
