/**
 * Robot Name
 *
 * When a robot is created it does not yet have a name.  The first time the
 * `name` property is accessed a random name is generated and remembered for
 * that robot instance.  Names are two uppercase ASCII letters followed by
 * three digits (e.g. "RX837").
 *
 * A robot can be reset to factory settings by calling the `reset()` method.
 * After resetting, the next access to `name` will lazily generate a new,
 * unique, random name.
 *
 * All names currently in use are tracked in a set to guarantee that no two
 * existing robots share the same name.  The static `releaseNames()` helper
 * clears that set so that names can be reused between independent runs (for
 * example, separate test cases).
 */

export class Robot {
  constructor() {
    this._name = null;               // Lazily generated on first access.
  }

  /**
   * Lazily generate (or return) this robot's name.
   */
  get name() {
    if (!this._name) {
      this._name = Robot._generateUniqueName();
    }
    return this._name;
  }

  /**
   * Reset the robot to factory settings.
   * Its current name is discarded and a new unique name will be generated
   * the next time `name` is accessed.
   */
  reset() {
    this._name = Robot._generateUniqueName();
  }

  /**
   * Clear the global name registry.
   * Intended for use by test suites to ensure isolation between tests.
   */
  static releaseNames() {
    Robot._usedNames.clear();
  }

  /**
   * Generate a name guaranteed to be unique amongst *currently existing*
   * robots.
   * @returns {string} A unique robot name, e.g. "AB123"
   * @private
   */
  static _generateUniqueName() {
    let candidate;
    do {
      candidate = Robot._randomName();
    } while (Robot._usedNames.has(candidate));

    Robot._usedNames.add(candidate);
    return candidate;
  }

  /**
   * Produce a random candidate name (without regard to uniqueness).
   * @returns {string}
   * @private
   */
  static _randomName() {
    const letters = Robot._LETTERS;
    const letter1 = letters[Math.floor(Math.random() * letters.length)];
    const letter2 = letters[Math.floor(Math.random() * letters.length)];
    const number = Math.floor(Math.random() * 1000)
      .toString()
      .padStart(3, '0');

    return `${letter1}${letter2}${number}`;
  }
}

/* Static/private data ---------------------------------------------------- */

Robot._LETTERS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
Robot._usedNames = new Set();
