export const sum = (factors, limit) => {
  // If the provided limit is not positive, there can be no valid multiples.
  if (limit <= 0) {
    return 0;
  }

  const uniqueMultiples = new Set();

  factors.forEach((factor) => {
    // Skip 0 to avoid an infinite loop / division-by-zero–style issues.
    if (factor === 0) return;

    // Work with the absolute value in case negative factors are supplied.
    const step = Math.abs(factor);

    for (let multiple = step; multiple < limit; multiple += step) {
      uniqueMultiples.add(multiple);
    }
  });

  // Sum the unique multiples.
  let total = 0;
  uniqueMultiples.forEach((value) => (total += value));

  return total;
};
