use std::collections::HashSet;
use std::sync::{atomic::{AtomicU64, Ordering}, Mutex, OnceLock};
use std::time::{SystemTime, UNIX_EPOCH};

/// Global set with the names in use.
static USED_NAMES: OnceLock<Mutex<HashSet<String>>> = OnceLock::new();

/// Seed for the pseudo-random generator.
static SEED: AtomicU64 = AtomicU64::new(0);

/// Convenient access to the global `HashSet`.
fn used_names() -> &'static Mutex<HashSet<String>> {
    USED_NAMES.get_or_init(|| Mutex::new(HashSet::new()))
}

/// Simple linear congruential generator (LCG).
fn next_random() -> u64 {
    // Lazy seed with the current time, if it hasn't been initialized.
    let _ = SEED.compare_exchange(
        0,
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("Time went backwards")
            .as_nanos() as u64,
        Ordering::SeqCst,
        Ordering::SeqCst,
    );

    // new = old * 1664525 + 1013904223   (mod 2⁶⁴)
    let mut old = SEED.load(Ordering::Relaxed);
    loop {
        let new = old
            .wrapping_mul(1_664_525)
            .wrapping_add(1_013_904_223);
        match SEED.compare_exchange(old, new, Ordering::SeqCst, Ordering::SeqCst) {
            Ok(_) => return new,
            Err(actual) => old = actual,
        }
    }
}

/// Builds a random name `AA000` and ensures its uniqueness.
fn generate_unique_name() -> String {
    loop {
        let r = next_random();

        let ch1 = ((r & 0xFF) % 26) as u8 + b'A';
        let ch2 = (((r >> 8) & 0xFF) % 26) as u8 + b'A';
        let d1  = (((r >> 16) & 0xFF) % 10) as u8 + b'0';
        let d2  = (((r >> 24) & 0xFF) % 10) as u8 + b'0';
        let d3  = (((r >> 32) & 0xFF) % 10) as u8 + b'0';

        let candidate = String::from_utf8(vec![ch1, ch2, d1, d2, d3]).unwrap();

        let mut set = used_names().lock().unwrap();
        if !set.contains(&candidate) {
            set.insert(candidate.clone());
            return candidate;
        }
        // If there is a collision, try again.
    }
}

pub struct Robot {
    name: String,
}

impl Robot {
    /// The robot leaves the factory without a public name, but internally
    /// it is assigned a unique one the first time.
    pub fn new() -> Self {
        Robot {
            name: generate_unique_name(),
        }
    }

    /// Returns the robot's current name.
    pub fn name(&self) -> &str {
        &self.name
    }

    /// Resets the robot to factory settings: releases its previous name
    /// and assigns a new, unique one.
    pub fn reset_name(&mut self) {
        {
            let mut set = used_names().lock().unwrap();
            set.remove(&self.name);
        }
        self.name = generate_unique_name();
    }
}
