use std::collections::HashMap;

/// Returns the minimum price (in cents) of the basket `books`.
/// Each element of `books` is a number between 1 and 5 that identifies the title.
pub fn lowest_price(books: &[u32]) -> u32 {
    // Count how many copies there are of each of the 5 titles
    let mut counts = [0u8; 5];
    for &book in books {
        if (1..=5).contains(&book) {
            counts[(book - 1) as usize] += 1;
        }
    }

    let mut memo = HashMap::new();
    price_from_counts(counts, &mut memo)
}

/// Recursively calculates the minimum price for a vector of quantities.
fn price_from_counts(counts: [u8; 5], memo: &mut HashMap<[u8; 5], u32>) -> u32 {
    if let Some(&cached) = memo.get(&counts) {
        return cached;
    }

    // If there are no books left, the price is 0
    if counts.iter().all(|&c| c == 0) {
        return 0;
    }

    let mut min_price = u32::MAX;

    // We go through all possible non-empty subsets (31 masks of 5 bits)
    for mask in 1u8..32 {
        let mut new_counts = counts;
        let mut subset_size = 0u32;

        for i in 0..5 {
            if (mask & (1 << i)) != 0 {
                if new_counts[i] == 0 {
                    subset_size = 0; // invalid subset
                    break;
                }
                new_counts[i] -= 1;
                subset_size += 1;
            }
        }

        if subset_size == 0 {
            continue; // could not form this group
        }

        let subset_price = price_for_group(subset_size);
        let remaining_price = price_from_counts(new_counts, memo);
        let total = subset_price + remaining_price;

        if total < min_price {
            min_price = total;
        }
    }

    memo.insert(counts, min_price);
    min_price
