/// Returns the price (in cents) of a group of `size` different books.
fn price_for_group(size: u32) -> u32 {
    let base = size * 800; // 8 $ per book → 800 ¢
    let discount = match size {
        1 => 0,
        2 => 5,
        3 => 10,
        4 => 20,
        5 => 25,
        _ => unreachable!("There are only up to 5 different titles"),
    };
    base - base * discount / 100
}

