package transpose

// Transpose returns the transposed representation of the given slice of
// strings. Each string is treated as a row of runes. When rows are of
// different lengths, missing positions are considered to be spaces that are
// added to the *left* side of the corresponding transposed row (i.e. they
// appear earlier in that row).  Only those added spaces that appear at the
// *right-most* end of an output row (and therefore do not correspond to any
// actual character in the input) are removed; all original characters —
// including spaces that were already present in the input — are preserved.
func Transpose(input []string) []string {
	rows := len(input)
	if rows == 0 {
		return []string{}
	}

	// Convert each input row to a slice of runes and determine the maximum width.
	runeRows := make([][]rune, rows)
	maxCols := 0
	for i, s := range input {
		runes := []rune(s)
		runeRows[i] = runes
		if len(runes) > maxCols {
			maxCols = len(runes)
		}
	}

	// For each column of the (conceptual) matrix build an output row.
	out := make([]string, maxCols)
	for col := 0; col < maxCols; col++ {
		// Build the current output row along with a flag indicating whether
		// each rune originates from the input (inserted=false) or was added as
		// padding (inserted=true).
		runesInRow := make([]rune, rows)
		inserted := make([]bool, rows)

		for row := 0; row < rows; row++ {
			if col < len(runeRows[row]) {
				runesInRow[row] = runeRows[row][col]
				inserted[row] = false
			} else {
				runesInRow[row] = ' '
				inserted[row] = true
			}
		}

		// Remove trailing runes that are spaces *and* were only inserted as
		// padding; preserve everything else.
		end := len(runesInRow)
		for end > 0 && runesInRow[end-1] == ' ' && inserted[end-1] {
			end--
		}

		out[col] = string(runesInRow[:end])
	}

	return out
}
