            // Third line
            sb.append("And if one green bottle should accidentally fall,\n");
            // Fourth line
            sb.append("There'll be ").append(bottleCount(next, false)).append(" hanging on the wall.");

            // Only add a blank line if not the last verse
            if (i < takeDown - 1) {
                sb.append("\n\n");
            } else {
                // Always add a trailing newline at the end of the last verse
                sb.append("\n");
            }
        }
        return sb.toString();
    }

    private String bottleLine(int count, boolean onTheWall) {
        return bottleCount(count, true) + (onTheWall ? " hanging on the wall," : "");
    }

    private String bottleCount(int count, boolean capitalize) {
        String text;
        if (count > 1) {
            text = numberWord(count) + " green bottles";
        } else if (count == 1) {
            text = "one green bottle";
        } else {
            text = "no green bottles";
        }
        if (capitalize) {
            text = Character.toUpperCase(text.charAt(0)) + text.substring(1);
        }
        return text;
    }

    private String numberWord(int n) {
        switch (n) {
            case 10: return "ten";
            case 9: return "nine";
            case 8: return "eight";
            case 7: return "seven";
            case 6: return "six";
            case 5: return "five";
            case 4: return "four";
            case 3: return "three";
            case 2: return "two";
            default: return Integer.toString(n);
        }
    }
}
