        boolean[] used = new boolean[inputDominoes.size()];

        for (int i = 0; i < inputDominoes.size(); i++) {
            Domino start = inputDominoes.get(i);
            // Try both orientations for the starting domino
            if (backtrack(chain, inputDominoes, used, start, 1, i)) {
                return new ArrayList<>(chain);
            }
            Domino flipped = new Domino(start.getRight(), start.getLeft());
            if (backtrack(chain, inputDominoes, used, flipped, 1, i)) {
                return new ArrayList<>(chain);
            }
        }

        throw new ChainNotFoundException("No domino chain found.");
    }

    private boolean backtrack(List<Domino> chain, List<Domino> dominoes, boolean[] used, Domino current, int depth, int currentIdx) {
        if (chain.size() < depth) {
            chain.add(current);
        } else {
            chain.set(depth - 1, current);
        }

        used[currentIdx] = true;

        if (depth == dominoes.size()) {
            // Check if the chain is closed (first left == last right)
            if (chain.get(0).getLeft() == chain.get(chain.size() - 1).getRight()) {
                return true;
            }
        } else {
            int right = current.getRight();
            for (int i = 0; i < dominoes.size(); i++) {
                if (!used[i]) {
                    Domino next = dominoes.get(i);
                    // Try both orientations
                    if (next.getLeft() == right) {
                        if (backtrack(chain, dominoes, used, next, depth + 1, i)) {
                            return true;
                        }
                    }
                    if (next.getRight() == right) {
