import java.util.*;

class Tree {
    private final String label;
    private final List<Tree> children;

    public Tree(String label) {
        this(label, new ArrayList<>());
    }

    public Tree(String label, List<Tree> children) {
        this.label = label;
        this.children = children;
    }

    public static Tree of(String label) {
        return new Tree(label);
    }

    public static Tree of(String label, List<Tree> children) {
        return new Tree(label, children);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Tree tree = (Tree) o;
        return label.equals(tree.label)
                && children.size() == tree.children.size()
                && children.containsAll(tree.children)
                && tree.children.containsAll(children);
    }

    @Override
    public int hashCode() {
        return Objects.hash(label, children);
    }

    @Override
    public String toString() {
        return "Tree{" + label +
                ", " + children +
                "}";
    }

    public String getLabel() {
        return label;
    }

    public List<Tree> getChildren() {
        return children;
    }

    // Helper: Find path from root to target node, as list of nodes
    private boolean findNodePath(String target, List<Tree> path) {
        path.add(this);
        if (this.label.equals(target)) {
            return true;
        }
        for (Tree child : children) {
            if (child.findNodePath(target, path)) {
                return true;
            }
        }
        path.remove(path.size() - 1);
        return false;
    }

    // Helper: Find node by label
    private Tree findNode(String target) {
        if (this.label.equals(target)) {
            return this;
        }
        for (Tree child : children) {
            Tree found = child.findNode(target);
            if (found != null) {
                return found;
            }
        }
        return null;
    }

    // Helper: Rebuild tree from a path, reversing parent-child relationships along the path
    private static Tree buildReparentedTree(List<Tree> path, int idx) {
        Tree current = path.get(idx);
        List<Tree> newChildren = new ArrayList<>();

        // Add all children except the one on the path (parent)
        for (Tree child : current.children) {
            if (idx + 1 < path.size() && child.label.equals(path.get(idx + 1).label)) {
                continue;
            }
            // Recursively copy the subtree
            newChildren.add(copyTree(child));
        }

        // If not at the end of the path, add the parent as a child (recurse)
        if (idx > 0) {
            newChildren.add(buildReparentedTree(path, idx - 1));
        }

        return new Tree(current.label, newChildren);
    }

    // Helper: Deep copy a tree
    private static Tree copyTree(Tree node) {
        List<Tree> newChildren = new ArrayList<>();
        for (Tree child : node.children) {
            newChildren.add(copyTree(child));
        }
        return new Tree(node.label, newChildren);
    }

    public Tree fromPov(String fromNode) {
        // Find path from root to fromNode
        List<Tree> path = new ArrayList<>();
        if (!findNodePath(fromNode, path)) {
            throw new UnsupportedOperationException("Tree could not be reoriented");
        }
        // Rebuild tree from the path, reversing parent-child relationships
        return buildReparentedTree(path, path.size() - 1);
    }

    public List<String> pathTo(String fromNode, String toNode) {
        // Find path from root to fromNode
        List<Tree> pathFrom = new ArrayList<>();
        if (!findNodePath(fromNode, pathFrom)) {
            throw new UnsupportedOperationException("No path found");
        }
        // Find path from root to toNode
        List<Tree> pathTo = new ArrayList<>();
        if (!findNodePath(toNode, pathTo)) {
            throw new UnsupportedOperationException("No path found");
        }
        // Find lowest common ancestor
        int i = 0;
        while (i < pathFrom.size() && i < pathTo.size() && pathFrom.get(i).label.equals(pathTo.get(i).label)) {
            i++;
        }
        // Path from fromNode up to LCA (excluding LCA)
        List<String> up = new ArrayList<>();
        for (int j = pathFrom.size() - 1; j >= i; j--) {
            up.add(pathFrom.get(j).label);
        }
        // Path from LCA to toNode (including LCA)
        List<String> down = new ArrayList<>();
        for (int j = i - 1; j < pathTo.size(); j++) {
            down.add(pathTo.get(j).label);
        }
        // Combine
        List<String> result = new ArrayList<>();
        result.addAll(up);
        result.addAll(down);
        if (result.isEmpty()) {
            throw new UnsupportedOperationException("No path found");
        }
        return result;
    }
}
