export class List {
  constructor(values = []) {
    this._head = null;
    this._length = 0;

    // If values are provided, add them to the list in order
    // The last element in the array should be the head of the list
    for (let i = 0; i < values.length; i++) {
      this.add(values[i]);
    }
  }

  add(value) {
    // If value is already an Element, use it directly
    let newElement;
    if (value instanceof Element) {
      newElement = value;
      newElement._next = this._head;
    } else {
      newElement = new Element(value, this._head);
    }
    this._head = newElement;
    this._length++;
    return this;
  }

  get length() {
    return this._length;
  }

  get head() {
    return this._head;
  }

  toArray() {
    const arr = [];
    let current = this._head;
    while (current) {
      arr.push(current.value);
      current = current.next;
    }
    return arr;
  }

  reverse() {
    let current = this._head;
    let prev = null;
    while (current) {
      const next = current.next;
      const reversedElement = new Element(current.value, prev);
      prev = reversedElement;
      current = next;
    }
    const reversedList = new List();
    reversedList._head = prev;
