#include "all_your_base.h"

namespace all_your_base {

std::vector<unsigned int> convert(
    unsigned int from_base,
    const std::vector<unsigned int>& digits,
    unsigned int to_base
) {
    if (from_base < 2) {
        throw std::invalid_argument("from_base must be >= 2");
    }
    if (to_base < 2) {
        throw std::invalid_argument("to_base must be >= 2");
    }
    // Check for invalid digits
    for (auto d : digits) {
        if (d >= from_base) {
            throw std::invalid_argument("All digits must be less than from_base");
        }
    }
    // Remove leading zeros
    size_t first_nonzero = 0;
    while (first_nonzero < digits.size() && digits[first_nonzero] == 0) {
        ++first_nonzero;
    }
    if (first_nonzero == digits.size()) {
        // All digits are zero, or the input is empty, so the number is zero
        // The correct output for empty input or all zeros is an empty vector
        return {};
    }
    std::vector<unsigned int> trimmed_digits(digits.begin() + first_nonzero, digits.end());

    // Convert input digits to an integer value
    unsigned long long value = 0;
    for (auto d : trimmed_digits) {
        value = value * from_base + d;
    }

    // Special case: value is zero
    if (value == 0) {
        // Only return {0} if the input was non-empty and not all zeros
        return {};
    }

    // Convert integer value to the target base
    std::vector<unsigned int> result;
    while (value > 0) {
        result.insert(result.begin(), value % to_base);
        value /= to_base;
    }
    return result;
}

}  // namespace all_your_base
