#include "zebra_puzzle.h"
#include <array>
#include <algorithm>
#include <vector>
#include <string>
#include <numeric>

namespace zebra_puzzle {

namespace {

constexpr int N = 5;

using Perm = std::array<int, N>;

// Helper: returns true if a and b are adjacent
bool is_next_to(int a, int b) {
    return std::abs(a - b) == 1;
}

// Helper: returns true if a is immediately to the right of b
bool is_right_of(int a, int b) {
    return a - b == 1;
}

// Attribute indices
enum Color { RED, GREEN, IVORY, YELLOW, BLUE };
enum Nationality { ENGLISHMAN, SPANIARD, UKRAINIAN, NORWEGIAN, JAPANESE };
enum Pet { DOG, SNAILS, FOX, HORSE, ZEBRA };
enum Drink { COFFEE, TEA, MILK, ORANGE_JUICE, WATER };
enum Hobby { DANCING, PAINTER, READING, FOOTBALL, CHESS };

const std::array<std::string, N> kColors = {"red", "green", "ivory", "yellow", "blue"};
const std::array<std::string, N> kNationalities = {"Englishman", "Spaniard", "Ukrainian", "Norwegian", "Japanese"};
const std::array<std::string, N> kPets = {"dog", "snails", "fox", "horse", "zebra"};
const std::array<std::string, N> kDrinks = {"coffee", "tea", "milk", "orange juice", "water"};
const std::array<std::string, N> kHobbies = {"dancing", "painter", "reading", "football", "chess"};

} // namespace

Solution solve() {
    // Each attribute is a permutation of {0,1,2,3,4} (house indices)
    Perm colors, nationalities, pets, drinks, hobbies;
    std::iota(colors.begin(), colors.end(), 0);
    std::iota(nationalities.begin(), nationalities.end(), 0);
    std::iota(pets.begin(), pets.end(), 0);
    std::iota(drinks.begin(), drinks.end(), 0);
    std::iota(hobbies.begin(), hobbies.end(), 0);

    // We'll permute in order of most-constrained to least-constrained
    // 1. Norwegian lives in the first house (house 0)
    // 2. Milk is drunk in the middle house (house 2)
    // We'll enforce these by only considering permutations that satisfy them

    do { // colors
        // 6. The green house is immediately to the right of the ivory house.
        int green = std::find(colors.begin(), colors.end(), GREEN) - colors.begin();
