          throw new Error('Pin count exceeds pins on the lane');
        }
      }
    } else if (this.currentFrame === 9) {
      // 10th frame
      if (frame.length === 1) {
        // If first roll is not strike, sum of first two rolls cannot exceed 10
        if (frame[0] !== 10 && frame[0] + pins > 10) {
          throw new Error('Pin count exceeds pins on the lane');
        }
      }
