          throw new Error('Cannot roll after game is over');
        }
      }
    }

    // Add roll to rolls and frameRolls
    this.rolls.push(pins);
    frame.push(pins);

    // Advance frame if needed
    if (this.currentFrame < 9) {
      if (frame[0] === 10 || frame.length === 2) {
        this.currentFrame++;
      }
    } else if (this.currentFrame === 9) {
      // 10th frame logic
      if (frame.length === 2) {
