package bowling

import (
	"errors"
)

// Define the Game type here.
type Game struct {
	rolls []int
}

// NewGame creates a new bowling game.
func NewGame() *Game {
	return &Game{
		rolls: make([]int, 0, 21), // max 21 rolls in a game
	}
}

// Roll records a roll in the game.
func (g *Game) Roll(pins int) error {
	if pins < 0 || pins > 10 {
		return errors.New("invalid number of pins")
	}

	rolls := g.rolls
	rollIndex := 0
	frame := 0

	// Find current frame and position in frame
	for frame < 10 && rollIndex < len(rolls) {
		if isStrike(rolls, rollIndex) {
			rollIndex++
		} else {
			rollIndex += 2
		}
		frame++
	}

	// If game is over, cannot roll anymore
	if frame == 10 {
		// 10th frame logic
		// Find the start of the 10th frame
		tenthStart := 0
		f := 0
		i := 0
		for f < 9 && i < len(rolls) {
			if isStrike(rolls, i) {
				i++
			} else {
				i += 2
			}
			f++
		}
		tenthFrameRolls := rolls[tenthStart+i:]
		// 10th frame can have up to 3 rolls
		if len(tenthFrameRolls) == 3 {
			return errors.New("Cannot roll after game is over")
		}
		// If 10th frame is open (no strike or spare), only 2 rolls allowed
		if len(tenthFrameRolls) == 2 && tenthFrameRolls[0]+tenthFrameRolls[1] < 10 {
			return errors.New("Cannot roll after game is over")
		}
		// Now, check fill ball rules
		if len(tenthFrameRolls) == 1 {
			// Second roll in 10th frame
			if tenthFrameRolls[0] != 10 && tenthFrameRolls[0]+pins > 10 {
				return errors.New("Pin count exceeds pins on the lane")
			}
		}
		if len(tenthFrameRolls) == 2 {
			// Third roll in 10th frame (fill ball)
			// If first roll is strike
			if tenthFrameRolls[0] == 10 {
				// If second roll is not strike, third roll + second roll cannot exceed 10
				if tenthFrameRolls[1] != 10 && tenthFrameRolls[1]+pins > 10 {
					return errors.New("Pin count exceeds pins on the lane")
				}
			} else if tenthFrameRolls[0]+tenthFrameRolls[1] == 10 {
				// Spare, only one fill ball, no restriction
			} else {
				// Should not reach here, as open frame is handled above
				return errors.New("Cannot roll after game is over")
			}
		}
	} else if frame < 10 {
		// Not in 10th frame yet
		// Check for frame pin count
		// If this is the second roll of a frame, check sum
		if len(rolls)%2 == 1 && !isStrike(rolls, len(rolls)-1) {
			if rolls[len(rolls)-1]+pins > 10 {
				return errors.New("pin count in a frame cannot exceed 10")
			}
		}
	}

	g.rolls = append(g.rolls, pins)
	return nil
}

func isStrike(rolls []int, idx int) bool {
	return idx < len(rolls) && rolls[idx] == 10
}

// Score calculates the total score for the game.
func (g *Game) Score() (int, error) {
	score := 0
	rollIndex := 0
	for frame := 0; frame < 10; frame++ {
		if rollIndex >= len(g.rolls) {
			return 0, errors.New("not enough rolls to score the game")
		}
		// Strike
		if g.rolls[rollIndex] == 10 {
			if rollIndex+2 >= len(g.rolls) {
				return 0, errors.New("not enough rolls to score a strike")
			}
			score += 10 + g.rolls[rollIndex+1] + g.rolls[rollIndex+2]
			rollIndex++
		} else if rollIndex+1 < len(g.rolls) {
			// Spare
			frameScore := g.rolls[rollIndex] + g.rolls[rollIndex+1]
			if frameScore > 10 {
				return 0, errors.New("pin count in a frame cannot exceed 10")
			}
			if frameScore == 10 {
				if rollIndex+2 >= len(g.rolls) {
					return 0, errors.New("not enough rolls to score a spare")
				}
				score += 10 + g.rolls[rollIndex+2]
			} else {
				// Open frame
				score += frameScore
			}
			rollIndex += 2
		} else {
			return 0, errors.New("not enough rolls to complete a frame")
		}
	}
	return score, nil
}
