	"strconv"
	"strings"
	"unicode"
	"errors"
)

type wordDef []string

type forthEnv struct {
	stack []int
	words map[string]wordDef
}

func isNumber(token string) bool {
	if len(token) == 0 {
		return false
	}
	// Allow negative numbers
	if token[0] == '-' && len(token) > 1 {
		token = token[1:]
	}
	for _, r := range token {
		if !unicode.IsDigit(r) {
			return false
		}
	}
	return true
}

func toLowerSlice(tokens []string) []string {
	out := make([]string, len(tokens))
	for i, t := range tokens {
		out[i] = strings.ToLower(t)
	}
	return out
}

func (env *forthEnv) evalToken(token string) error {
	token = strings.ToLower(token)
	// Check user-defined words first, so they can override built-ins
	if def, ok := env.words[token]; ok {
		for _, t := range def {
			if err := env.evalToken(t); err != nil {
				return err
			}
		}
		return nil
	}
	switch token {
	case "+":
		if len(env.stack) < 2 {
			return errors.New("stack underflow")
		}
		a, b := env.stack[len(env.stack)-2], env.stack[len(env.stack)-1]
		env.stack = env.stack[:len(env.stack)-2]
		env.stack = append(env.stack, a+b)
	case "-":
		if len(env.stack) < 2 {
			return errors.New("stack underflow")
		}
		a, b := env.stack[len(env.stack)-2], env.stack[len(env.stack)-1]
		env.stack = env.stack[:len(env.stack)-2]
		env.stack = append(env.stack, a-b)
	case "*":
		if len(env.stack) < 2 {
			return errors.New("stack underflow")
		}
		a, b := env.stack[len(env.stack)-2], env.stack[len(env.stack)-1]
		env.stack = env.stack[:len(env.stack)-2]
		env.stack = append(env.stack, a*b)
	case "/":
		if len(env.stack) < 2 {
			return errors.New("stack underflow")
		}
		a, b := env.stack[len(env.stack)-2], env.stack[len(env.stack)-1]
		if b == 0 {
			return errors.New("divide by zero")
		}
		env.stack = env.stack[:len(env.stack)-2]
		env.stack = append(env.stack, a/b)
	case "dup":
		if len(env.stack) < 1 {
			return errors.New("stack underflow")
		}
		env.stack = append(env.stack, env.stack[len(env.stack)-1])
	case "drop":
		if len(env.stack) < 1 {
			return errors.New("stack underflow")
		}
		env.stack = env.stack[:len(env.stack)-1]
	case "swap":
		if len(env.stack) < 2 {
			return errors.New("stack underflow")
		}
		env.stack[len(env.stack)-1], env.stack[len(env.stack)-2] = env.stack[len(env.stack)-2], env.stack[len(env.stack)-1]
	case "over":
		if len(env.stack) < 2 {
			return errors.New("stack underflow")
		}
		env.stack = append(env.stack, env.stack[len(env.stack)-2])
	default:
		if isNumber(token) {
			val, _ := strconv.Atoi(token)
			env.stack = append(env.stack, val)
		} else {
			return fmt.Errorf("undefined word: %s", token)
		}
	}
	return nil
}

func parseDefinition(tokens []string, i int) (string, []string, int, error) {
	// tokens[i] == ":"
	if i+1 >= len(tokens) {
		return "", nil, i, errors.New("invalid definition: missing word name")
	}
	wordName := strings.ToLower(tokens[i+1])
	def := []string{}
	j := i + 2
	for ; j < len(tokens); j++ {
		if tokens[j] == ";" {
			break
		}
		def = append(def, tokens[j])
	}
	if j == len(tokens) {
		return "", nil, i, errors.New("invalid definition: missing ';'")
	}
	return wordName, def, j, nil
}

func Forth(input []string) ([]int, error) {
	env := &forthEnv{
		stack: []int{},
		words: make(map[string]wordDef),
	}
	// Tokenize all input lines
	tokens := []string{}
	for _, line := range input {
		parts := strings.Fields(line)
		tokens = append(tokens, parts...)
	}
	// Evaluate tokens
	for i := 0; i < len(tokens); i++ {
		token := tokens[i]
		if token == ":" {
			wordName, def, j, err := parseDefinition(tokens, i)
			if err != nil {
				return nil, err
			}
			if isNumber(wordName) {
				return nil, errors.New("cannot redefine numbers")
			}
			// Expand user-defined words in the definition (case-insensitive)
			expandedDef := []string{}
			for _, t := range def {
				tl := strings.ToLower(t)
				if d, ok := env.words[tl]; ok {
					expandedDef = append(expandedDef, d...)
				} else {
					expandedDef = append(expandedDef, t)
				}
			}
			env.words[wordName] = toLowerSlice(expandedDef)
			i = j // skip to after ';'
		} else {
			if err := env.evalToken(token); err != nil {
				return nil, err
			}
		}
	}
	return env.stack, nil
}
