func MakeChain(input []Domino) ([]Domino, bool) {
	n := len(input)
	if n == 0 {
		return []Domino{}, true
	}
	if n == 1 {
		if input[0][0] == input[0][1] {
			return []Domino{input[0]}, true
		}
		return nil, false
	}

	used := make([]bool, n)
	chain := make([]Domino, 0, n)

	// Try every domino as a starting point, in both orientations
	for i := 0; i < n; i++ {
		for flip := 0; flip < 2; flip++ {
			start := input[i]
			if flip == 1 {
				start = Domino{input[i][1], input[i][0]}
			}
			used[i] = true
			chain = append(chain, start)
			if out, ok := backtrack(input, used, chain, start[1], start[0]); ok {
				return out, true
			}
			chain = chain[:0]
			used[i] = false
		}
	}
	return nil, false
}

func backtrack(input []Domino, used []bool, chain []Domino, want int, first int) ([]Domino, bool) {
	if len(chain) == len(input) {
		// Check if the chain is closed
		if want == first {
			// Return a copy of the chain
			out := make([]Domino, len(chain))
			copy(out, chain)
			return out, true
		}
		return nil, false
	}
	for i := 0; i < len(input); i++ {
		if used[i] {
			continue
		}
		for flip := 0; flip < 2; flip++ {
			d := input[i]
			if flip == 1 {
				d = Domino{input[i][1], input[i][0]}
			}
			if d[0] == want {
				used[i] = true
				chain = append(chain, d)
				if out, ok := backtrack(input, used, chain, d[1], first); ok {
					return out, true
				}
				chain = chain[:len(chain)-1]
				used[i] = false
			}
		}
	}
	return nil, false
}
