func Use(opener ResourceOpener, input string) (err error) {
	var res Resource
	for {
		var openErr error
		res, openErr = opener()
		if openErr != nil {
			if _, ok := openErr.(TransientError); ok {
				// Try again if it's a TransientError
				continue
			}
			// Return any other error
			return openErr
		}
		break
	}

	defer res.Close()

	defer func() {
		if r := recover(); r != nil {
			if fe, ok := r.(FrobError); ok {
				res.Defrob(fe.defrobTag)
				err = fe
			} else if e, ok := r.(error); ok {
				err = e
			} else {
				panic(r)
			}
		}
	}()

	res.Frob(input)
	return nil
}
