def translate(text):
    def translate_word(word):
        vowels = "aeiou"
        # Rule 1: starts with vowel or "xr" or "yt"
        if word[0] in vowels or word.startswith("xr") or word.startswith("yt"):
            return word + "ay"

        # Rule 3: starts with consonant(s) + "qu"
        if "qu" in word:
            idx = word.find("qu")
            if idx == 0:
                # starts with "qu"
                return word[2:] + "quay"
            elif idx > 0:
                # consonant(s) before "qu"
                return word[idx+2:] + word[:idx+2] + "ay"

        # Rule 4: consonant(s) before "y" acting as a vowel (not at start)
        # Only if y is not the first letter and is after consonant(s)
        for i in range(1, len(word)):
            if word[i] == "y":
                # Make sure all before y are consonants
                if all(c not in vowels for c in word[:i]):
                    return word[i:] + word[:i] + "ay"

        # Rule 2: move leading consonant(s) to end, then "ay"
        for i, c in enumerate(word):
            if c in vowels:
                return word[i:] + word[:i] + "ay"
        # If no vowels found, just add "ay"
        return word + "ay"

    return " ".join(translate_word(word) for word in text.split())
