use std::collections::{BTreeMap, BTreeSet};

pub struct School {
    // Map grade -> set of student names (sorted)
    roster: BTreeMap<u32, BTreeSet<String>>,
}

impl School {
    pub fn new() -> School {
        School {
            roster: BTreeMap::new(),
        }
    }

    pub fn add(&mut self, grade: u32, student: &str) {
        // Check if student is already in any grade
        for (g, students) in self.roster.iter() {
            if students.contains(student) {
                // If already in the same grade, do nothing (don't add again)
                // If in a different grade, do nothing (don't move)
                return;
            }
        }
        self.roster
            .entry(grade)
            .or_insert_with(BTreeSet::new)
            .insert(student.to_string());
    }

    pub fn grades(&self) -> Vec<u32> {
        self.roster.keys().cloned().collect()
    }

    pub fn grade(&self, grade: u32) -> Vec<String> {
        match self.roster.get(&grade) {
            Some(students) => students.iter().cloned().collect(),
            None => Vec::new(),
        }
    }
}
