pub fn abbreviate(phrase: &str) -> String {
    let mut acronym = String::new();
    let mut prev_is_separator = true;

    for (i, c) in phrase.chars().enumerate() {
        // Treat hyphens and underscores as word separators
        let is_separator = c == '-' || c == '_' || c.is_whitespace();

        // If current char is alphabetic and previous was a separator, it's a new word
        if c.is_alphabetic() && prev_is_separator {
            acronym.push(c.to_ascii_uppercase());
        }

        // Handle camelCase: if current char is uppercase and previous is lowercase, it's a new word
        if i > 0 {
            let prev = phrase.chars().nth(i - 1).unwrap();
            if c.is_uppercase() && prev.is_lowercase() {
                acronym.push(c.to_ascii_uppercase());
            }
        }

        prev_is_separator = is_separator;
    }

    acronym
}
