pub fn abbreviate(phrase: &str) -> String {
    // Replace hyphens with spaces to treat them as word separators
    let phrase = phrase.replace('-', " ");
    // Remove all non-alphabetic and non-space characters
    let cleaned: String = phrase
        .chars()
        .filter(|c| c.is_alphabetic() || c.is_whitespace())
        .collect();
    // Split into words, take the first letter of each, uppercase it, and collect
    cleaned
        .split_whitespace()
        .filter_map(|word| word.chars().next())
        .map(|c| c.to_ascii_uppercase())
        .collect()
}
