package wordsearch

import (
	"errors"
	"strings"
)

type Point [2]int

// directions: (dx, dy)
var directions = []Point{
	{0, 1},   // right
	{1, 0},   // down
	{0, -1},  // left
	{-1, 0},  // up
	{1, 1},   // down-right
	{1, -1},  // down-left
	{-1, 1},  // up-right
	{-1, -1}, // up-left
}

func inBounds(x, y, nRows, nCols int) bool {
	return x >= 0 && x < nRows && y >= 0 && y < nCols
}

// findWord now returns start and end as [row, col] and searches in all directions
func findWord(word string, grid []string) (Point, Point, bool) {
	nRows := len(grid)
	if nRows == 0 {
		return Point{}, Point{}, false
	}
	nCols := len(grid[0])
	wordLen := len(word)

	for i := 0; i < nRows; i++ {
		for j := 0; j < nCols; j++ {
			for _, dir := range directions {
				x, y := i, j
				match := true
				for k := 0; k < wordLen; k++ {
					if !inBounds(x, y, nRows, nCols) || grid[x][y] != word[k] {
						match = false
						break
					}
					x += dir[0]
					y += dir[1]
				}
				if match {
					start := Point{i, j}
					end := Point{i + dir[0]*(wordLen-1), j + dir[1]*(wordLen-1)}
					return start, end, true
				}
			}
		}
	}
	return Point{}, Point{}, false
}

// findWordColMajor searches for the word in the grid, but returns coordinates as [col, row] (column-major)
func findWordColMajor(word string, grid []string) (Point, Point, bool) {
	nRows := len(grid)
	if nRows == 0 {
		return Point{}, Point{}, false
	}
	nCols := len(grid[0])
	wordLen := len(word)

	for j := 0; j < nCols; j++ {
		for i := 0; i < nRows; i++ {
			for _, dir := range directions {
				x, y := i, j
				match := true
				for k := 0; k < wordLen; k++ {
					if !inBounds(x, y, nRows, nCols) || grid[x][y] != word[k] {
						match = false
						break
					}
					x += dir[0]
					y += dir[1]
				}
				if match {
					start := Point{j, i}
					end := Point{j + dir[1]*(wordLen-1), i + dir[0]*(wordLen-1)}
					return start, end, true
				}
			}
		}
	}
	return Point{}, Point{}, false
}

// Solve returns coordinates as [col, row] (column, row) for start and end
func Solve(words []string, puzzle []string) (map[string][2][2]int, error) {
	nRows := len(puzzle)
	if nRows == 0 {
		return nil, errors.New("puzzle is empty")
	}
	nCols := len(puzzle[0])
	for _, row := range puzzle {
		if len(row) != nCols {
			return nil, errors.New("puzzle is not a rectangle")
		}
	}

	// Convert puzzle to uppercase for case-insensitive search
	grid := make([]string, nRows)
	for i, row := range puzzle {
		grid[i] = strings.ToUpper(row)
	}

	result := make(map[string][2][2]int)
	notFound := []string{}
	for _, word := range words {
		upperWord := strings.ToUpper(word)
		found := false
		// Search in all directions, but return coordinates as [col, row]
		for i := 0; i < nRows && !found; i++ {
			for j := 0; j < nCols && !found; j++ {
				for _, dir := range directions {
					x, y := i, j
					match := true
					for k := 0; k < len(upperWord); k++ {
						if !inBounds(x, y, nRows, nCols) || grid[x][y] != upperWord[k] {
							match = false
							break
						}
						x += dir[0]
						y += dir[1]
					}
					if match {
						start := [2]int{j, i}
						end := [2]int{j + dir[1]*(len(upperWord)-1), i + dir[0]*(len(upperWord)-1)}
						result[word] = [2][2]int{start, end}
						found = true
						break
					}
				}
			}
		}
		if !found {
			notFound = append(notFound, word)
		}
	}
	if len(notFound) > 0 {
		return result, errors.New("not all words found")
	}
	return result, nil
}
