package wordsearch

import (
	"errors"
	"strings"
)

type Point [2]int

// directions: (dx, dy)
var directions = []Point{
	{0, 1},   // right
	{1, 0},   // down
	{0, -1},  // left
	{-1, 0},  // up
	{1, 1},   // down-right
	{1, -1},  // down-left
	{-1, 1},  // up-right
	{-1, -1}, // up-left
}

func inBounds(x, y, nRows, nCols int) bool {
	return x >= 0 && x < nRows && y >= 0 && y < nCols
}

func findWord(word string, grid []string) (Point, Point, bool) {
	nRows := len(grid)
	if nRows == 0 {
		return Point{}, Point{}, false
	}
	nCols := len(grid[0])
	wordLen := len(word)

	for i := 0; i < nRows; i++ {
		for j := 0; j < nCols; j++ {
			for _, dir := range directions {
				x, y := i, j
				match := true
				for k := 0; k < wordLen; k++ {
					if !inBounds(x, y, nRows, nCols) || grid[x][y] != word[k] {
						match = false
						break
					}
					x += dir[0]
					y += dir[1]
				}
				if match {
					start := Point{i, j}
					end := Point{i + dir[0]*(wordLen-1), j + dir[1]*(wordLen-1)}
					return start, end, true
				}
			}
		}
	}
	return Point{}, Point{}, false
}

