public class AffineCipher {

    private static final int ALPHABET_SIZE = 26;
    private static final int GROUP_SIZE = 5;

    public String encode(String text, int coefficient1, int coefficient2) {
        if (!areCoprime(coefficient1, ALPHABET_SIZE)) {
            throw new IllegalArgumentException("Error: keyA and alphabet size must be coprime.");
        }

        StringBuilder encoded = new StringBuilder();
        int groupCount = 0;

        for (char c : text.toLowerCase().toCharArray()) {
            if (Character.isLetter(c)) {
                int x = c - 'a';
                int enc = mod(coefficient1 * x + coefficient2, ALPHABET_SIZE);
                char encChar = (char) ('a' + enc);
                encoded.append(encChar);
                groupCount++;
            } else if (Character.isDigit(c)) {
                encoded.append(c);
                groupCount++;
            }
            // skip spaces and punctuation
            if (groupCount == GROUP_SIZE) {
                encoded.append(' ');
                groupCount = 0;
            }
        }

        // Remove trailing space if present
        if (encoded.length() > 0 && encoded.charAt(encoded.length() - 1) == ' ') {
            encoded.deleteCharAt(encoded.length() - 1);
        }

        return encoded.toString();
    }

    public String decode(String text, int coefficient1, int coefficient2) {
        if (!areCoprime(coefficient1, ALPHABET_SIZE)) {
            throw new IllegalArgumentException("Error: keyA and alphabet size must be coprime.");
        }

        int a_inv = modInverse(coefficient1, ALPHABET_SIZE);
        StringBuilder decoded = new StringBuilder();

        for (char c : text.toLowerCase().toCharArray()) {
            if (Character.isLetter(c)) {
                int y = c - 'a';
                int dec = mod(a_inv * (y - coefficient2), ALPHABET_SIZE);
                char decChar = (char) ('a' + dec);
                decoded.append(decChar);
            } else if (Character.isDigit(c)) {
                decoded.append(c);
            }
            // skip spaces and punctuation
        }

        return decoded.toString();
    }

    // Helper to check if two numbers are coprime
    private boolean areCoprime(int a, int b) {
        return gcd(a, b) == 1;
    }

    // Euclidean algorithm for GCD
    private int gcd(int a, int b) {
        if (b == 0) return Math.abs(a);
        return gcd(b, a % b);
    }

    // Modular multiplicative inverse using extended Euclidean algorithm
    private int modInverse(int a, int m) {
        int m0 = m, t, q;
        int x0 = 0, x1 = 1;
        a = mod(a, m);

        if (m == 1)
            return 0;

        while (a > 1) {
            q = a / m;
            t = m;

            m = a % m;
            a = t;
            t = x0;

            x0 = x1 - q * x0;
            x1 = t;
        }

        if (x1 < 0)
            x1 += m0;

        return x1;
    }

    // True modulo operation (always positive)
    private int mod(int a, int m) {
        int result = a % m;
        if (result < 0) {
            result += m;
        }
        return result;
    }
}
