            "|_ " +
            "   ", "2");
        DIGIT_MAP.put(
            " _ " +
            " _|" +
            " _|" +
            "   ", "3");
        DIGIT_MAP.put(
            "   " +
            "|_|" +
            "  |" +
            "   ", "4");
        DIGIT_MAP.put(
            " _ " +
            "|_ " +
            " _|" +
            "   ", "5");
        DIGIT_MAP.put(
            " _ " +
            "|_ " +
            "|_|" +
            "   ", "6");
        DIGIT_MAP.put(
            " _ " +
            "  |" +
            "  |" +
            "   ", "7");
        DIGIT_MAP.put(
            " _ " +
            "|_|" +
            "|_|" +
            "   ", "8");
        DIGIT_MAP.put(
            " _ " +
            "|_|" +
            " _|" +
            "   ", "9");
    }

    String parse(List<String> input) {
        // Step 1: Validate input size
        if (input == null || input.size() == 0) {
            throw new IllegalArgumentException("Input cannot be null or empty.");
        }
        int rowCount = input.size();
        if (rowCount % 4 != 0) {
            throw new IllegalArgumentException("Number of input rows must be a positive multiple of 4");
        }
        int colCount = input.get(0).length();
        for (String row : input) {
            if (row.length() != colCount) {
                throw new IllegalArgumentException("All rows must have the same number of columns.");
            }
        }
        if (colCount % 3 != 0) {
            throw new IllegalArgumentException("Number of input columns must be a positive multiple of 3");
        }

        int numLines = rowCount / 4;
        int digitsPerLine = colCount / 3;
        List<String> results = new ArrayList<>();

        for (int line = 0; line < numLines; line++) {
            int baseRow = line * 4;
            StringBuilder sb = new StringBuilder();
            for (int digit = 0; digit < digitsPerLine; digit++) {
                int baseCol = digit * 3;
                StringBuilder pattern = new StringBuilder();
                for (int r = 0; r < 4; r++) {
                    pattern.append(input.get(baseRow + r), baseCol, baseCol + 3);
                }
                String digitStr = DIGIT_MAP.getOrDefault(pattern.toString(), "?");
                sb.append(digitStr);
            }
            results.add(sb.toString());
        }

        return String.join(",", results);
    }
}
