class PigLatinTranslator {
    public String translate(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        // Support phrases by splitting on spaces and joining back
        String[] words = input.split(" ");
        StringBuilder result = new StringBuilder();
        for (int w = 0; w < words.length; w++) {
            String word = words[w];

            // Rule 1: Starts with vowel or "xr" or "yt"
            if (startsWithVowel(word) || word.startsWith("xr") || word.startsWith("yt")) {
                result.append(word).append("ay");
            }
            // Rule 3: Starts with consonant(s) followed by "qu"
            else if (startsWithConsonantFollowedByQu(word)) {
                int quIndex = word.indexOf("qu");
                String start = word.substring(0, quIndex + 2);
                String rest = word.substring(quIndex + 2);
                result.append(rest).append(start).append("ay");
            }
            // Rule 4: Starts with consonant(s) followed by "y"
            else if (indexOfYAfterConsonant(word) != -1) {
                int yIndex = indexOfYAfterConsonant(word);
                String start = word.substring(0, yIndex);
                String rest = word.substring(yIndex);
                result.append(rest).append(start).append("ay");
            }
            // Rule 2: Starts with consonant(s)
            else {
                int firstVowel = firstVowelIndex(word);
                if (firstVowel > 0) {
                    String start = word.substring(0, firstVowel);
                    String rest = word.substring(firstVowel);
                    result.append(rest).append(start).append("ay");
                } else {
                    // If no vowels found, just add "ay"
                    result.append(word).append("ay");
                }
            }

            if (w < words.length - 1) {
                result.append(" ");
            }
        }
        return result.toString();
    }

    private boolean startsWithVowel(String word) {
        char c = word.charAt(0);
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    private int firstVowelIndex(String word) {
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            if (isVowel(c)) {
                // 'u' after 'q' is not a vowel for this purpose
                if (c == 'u' && i > 0 && word.charAt(i - 1) == 'q') {
                    continue;
                }
                return i;
            }
        }
        return -1;
    }

    private boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    // Returns true if the word starts with zero or more consonants followed by "qu"
    private boolean startsWithConsonantFollowedByQu(String word) {
        int quIndex = word.indexOf("qu");
        if (quIndex == -1) {
            return false;
        }
        // All before 'qu' must be consonants
        for (int i = 0; i < quIndex; i++) {
            if (isVowel(word.charAt(i))) {
                return false;
            }
        }
        return true;
    }

    // Returns the index of 'y' after one or more consonants, or -1 if not found
    private int indexOfYAfterConsonant(String word) {
        for (int i = 1; i < word.length(); i++) {
            if (word.charAt(i) == 'y') {
                // All before i must be consonants
                boolean allConsonants = true;
                for (int j = 0; j < i; j++) {
                    if (isVowel(word.charAt(j))) {
                        allConsonants = false;
                        break;
                    }
                }
                if (allConsonants) {
                    return i;
                }
            }
        }
        return -1;
    }
}
