import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class ChangeCalculator {

    private final List<Integer> coins;

    ChangeCalculator(List<Integer> currencyCoins) {
        if (currencyCoins == null || currencyCoins.isEmpty()) {
            throw new IllegalArgumentException("Coin list must not be null or empty.");
        }
        for (Integer coin : currencyCoins) {
            if (coin <= 0) {
                throw new IllegalArgumentException("Coin denominations must be positive integers.");
            }
        }
        // Sort coins in descending order for easier greedy fallback
        this.coins = new ArrayList<>(currencyCoins);
        Collections.sort(this.coins, Collections.reverseOrder());
    }

    List<Integer> computeMostEfficientChange(int grandTotal) {
        if (grandTotal < 0) {
            throw new IllegalArgumentException("Negative totals are not allowed.");
        }
        if (grandTotal == 0) {
            return new ArrayList<>();
        }
        int minCoin = Collections.min(coins);
        if (grandTotal < minCoin) {
            throw new IllegalArgumentException("The total " + grandTotal + " cannot be represented in the given currency.");
        }

        // Dynamic programming: minCoins[i] = min number of coins for amount i
        // coinUsed[i] = last coin used to make amount i
        int[] minCoins = new int[grandTotal + 1];
        int[] coinUsed = new int[grandTotal + 1];

        for (int i = 1; i <= grandTotal; i++) {
            minCoins[i] = Integer.MAX_VALUE;
            coinUsed[i] = -1;
            for (int coin : coins) {
                if (coin <= i && minCoins[i - coin] != Integer.MAX_VALUE) {
                    if (minCoins[i - coin] + 1 < minCoins[i]) {
                        minCoins[i] = minCoins[i - coin] + 1;
                        coinUsed[i] = coin;
                    }
                }
            }
        }

        if (minCoins[grandTotal] == Integer.MAX_VALUE) {
            throw new IllegalArgumentException("The total " + grandTotal + " cannot be represented in the given currency.");
        }

        // Reconstruct the coins used
        List<Integer> result = new ArrayList<>();
        int amount = grandTotal;
        while (amount > 0) {
            int coin = coinUsed[amount];
            if (coin == -1) {
                // Should not happen due to earlier check
                throw new IllegalArgumentException("The total " + grandTotal + " cannot be represented in the given currency.");
            }
            result.add(coin);
            amount -= coin;
        }
        // Return coins in ascending order as per example
        Collections.sort(result);
        return result;
    }

}
