class WordProblemSolver {
    int solve(final String wordProblem) {
        // Standard error message for all invalid questions
        final String ERROR_MSG = "I'm sorry, I don't understand the question!";

        if (wordProblem == null || !wordProblem.startsWith("What is ") || !wordProblem.endsWith("?")) {
            throw new IllegalArgumentException(ERROR_MSG);
        }

        // Remove "What is " at the start and "?" at the end
        String content = wordProblem.substring(8, wordProblem.length() - 1).trim();

        if (content.isEmpty()) {
            throw new IllegalArgumentException(ERROR_MSG);
        }

        // Supported operations
        String[] ops = {"plus", "minus", "multiplied by", "divided by"};
        // Replace multi-word operators with single tokens for easier splitting
        content = content.replaceAll("multiplied by", "multiplied_by");
        content = content.replaceAll("divided by", "divided_by");

        // Split by space
        String[] tokens = content.split(" ");

        // If only one token and it's a number, return it
        if (tokens.length == 1) {
            try {
                return Integer.parseInt(tokens[0]);
            } catch (NumberFormatException e) {
                throw new IllegalArgumentException(ERROR_MSG);
            }
        }

        // If the first token is not a number, it's invalid (e.g. prefix notation)
        int idx = 0;
        Integer result = null;
        String pendingOp = null;

        while (idx < tokens.length) {
