import java.util.List;
import java.util.SortedMap;
import java.util.TreeMap;
import java.util.ArrayList;
import java.util.Collections;

class PalindromeCalculator {

    SortedMap<Long, List<List<Integer>>> getPalindromeProductsWithFactors(int minFactor, int maxFactor) {
        if (minFactor > maxFactor) {
            throw new IllegalArgumentException("invalid input: min must be <= max");
        }

        TreeMap<Long, List<List<Integer>>> palindromeProducts = new TreeMap<>();

        for (int i = minFactor; i <= maxFactor; i++) {
            for (int j = i; j <= maxFactor; j++) { // j starts at i to avoid duplicate pairs
                long product = (long) i * (long) j;
                if (isPalindrome(product)) {
                    palindromeProducts
                        .computeIfAbsent(product, k -> new ArrayList<>())
                        .add(List.of(i, j));
                }
            }
        }

        return palindromeProducts;
    }

    private boolean isPalindrome(long n) {
        String s = Long.toString(n);
        int left = 0, right = s.length() - 1;
        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}
