enum Suit {
    Clubs,
    Diamonds,
    Hearts,
    Spades,
}

#[derive(Debug, PartialEq, Eq, Clone)]
struct Card {
    rank: Rank,
    suit: Suit,
}

#[derive(Debug, PartialEq, Eq, PartialOrd, Ord)]
enum HandRank {
    HighCard(Vec<Rank>),
    OnePair(Rank, Vec<Rank>),
    TwoPair(Rank, Rank, Rank),
    ThreeOfAKind(Rank, Vec<Rank>),
    Straight(Rank),
    Flush(Vec<Rank>),
    FullHouse(Rank, Rank),
    FourOfAKind(Rank, Rank),
    StraightFlush(Rank),
}

fn parse_rank(s: &str) -> Option<Rank> {
    match s {
        "2" => Some(Rank::Two),
        "3" => Some(Rank::Three),
        "4" => Some(Rank::Four),
        "5" => Some(Rank::Five),
        "6" => Some(Rank::Six),
        "7" => Some(Rank::Seven),
        "8" => Some(Rank::Eight),
        "9" => Some(Rank::Nine),
        "10" => Some(Rank::Ten),
        "J" => Some(Rank::Jack),
        "Q" => Some(Rank::Queen),
        "K" => Some(Rank::King),
        "A" => Some(Rank::Ace),
        _ => None,
    }
}

fn parse_suit(s: char) -> Option<Suit> {
    match s {
        'C' => Some(Suit::Clubs),
        'D' => Some(Suit::Diamonds),
        'H' => Some(Suit::Hearts),
        'S' => Some(Suit::Spades),
        _ => None,
    }
}

fn parse_card(s: &str) -> Option<Card> {
    let (rank_str, suit_char) = if s.len() == 3 {
        (&s[..2], s.chars().nth(2)?)
    } else {
        (&s[..1], s.chars().nth(1)?)
    };
    Some(Card {
        rank: parse_rank(rank_str)?,
        suit: parse_suit(suit_char)?,
    })
}

fn parse_hand(s: &str) -> Option<Vec<Card>> {
    s.split_whitespace().map(parse_card).collect()
}

fn is_straight(mut ranks: Vec<Rank>) -> Option<Rank> {
    ranks.sort_by(|a, b| (*b as i32).cmp(&(*a as i32)));
    let mut last = ranks[0] as i32;
    for r in ranks.iter().skip(1) {
        let v = *r as i32;
        if v == last - 1 {
            last = v;
        } else if v == last {
            continue; // skip duplicate ranks (shouldn't happen in valid hands)
        } else {
            // Check for wheel straight (A-2-3-4-5)
            if ranks == vec![Rank::Ace, Rank::Five, Rank::Four, Rank::Three, Rank::Two] {
                return Some(Rank::Five);
            }
            return None;
        }
    }
    Some(ranks[0])
}

fn hand_rank(cards: &[Card]) -> HandRank {
    let mut ranks: Vec<Rank> = cards.iter().map(|c| c.rank).collect();
    ranks.sort_by(|a, b| (*b as i32).cmp(&(*a as i32)));

    let mut suits: Vec<Suit> = cards.iter().map(|c| c.suit).collect();
    suits.sort();

    let is_flush = suits.iter().all(|&s| s == suits[0]);
    let straight_high = is_straight(ranks.clone());

    let mut counts: HashMap<Rank, usize> = HashMap::new();
    for &r in &ranks {
        *counts.entry(r).or_insert(0) += 1;
    }
    let mut count_vec: Vec<(usize, Rank)> = counts.iter().map(|(&r, &c)| (c, r)).collect();
    count_vec.sort_by(|a, b| b.cmp(a)); // sort by count desc, then rank desc

    if is_flush && straight_high.is_some() {
        return HandRank::StraightFlush(straight_high.unwrap());
    }
    if count_vec[0].0 == 4 {
        // Four of a kind
        let four = count_vec[0].1;
        let kicker = count_vec[1].1;
        return HandRank::FourOfAKind(four, kicker);
    }
    if count_vec[0].0 == 3 && count_vec[1].0 == 2 {
        // Full house
        return HandRank::FullHouse(count_vec[0].1, count_vec[1].1);
    }
    if is_flush {
        return HandRank::Flush(ranks);
    }
    if let Some(high) = straight_high {
        return HandRank::Straight(high);
    }
    if count_vec[0].0 == 3 {
        // Three of a kind
        let three = count_vec[0].1;
        let mut kickers: Vec<Rank> = count_vec.iter().filter(|x| x.0 == 1).map(|x| x.1).collect();
        kickers.sort_by(|a, b| (*b as i32).cmp(&(*a as i32)));
        return HandRank::ThreeOfAKind(three, kickers);
    }
    if count_vec[0].0 == 2 && count_vec[1].0 == 2 {
        // Two pair
        let high_pair = count_vec[0].1.max(count_vec[1].1);
        let low_pair = count_vec[0].1.min(count_vec[1].1);
        let kicker = count_vec.iter().find(|x| x.0 == 1).unwrap().1;
        return HandRank::TwoPair(high_pair, low_pair, kicker);
    }
    if count_vec[0].0 == 2 {
        // One pair
        let pair = count_vec[0].1;
        let mut kickers: Vec<Rank> = count_vec.iter().filter(|x| x.0 == 1).map(|x| x.1).collect();
        kickers.sort_by(|a, b| (*b as i32).cmp(&(*a as i32)));
        return HandRank::OnePair(pair, kickers);
    }
    // High card
    HandRank::HighCard(ranks)
}

/// Given a list of poker hands, return a list of those hands which win.
///
/// Note the type signature: this function should return _the same_ reference to
/// the winning hand(s) as were passed in, not reconstructed strings which happen to be equal.
pub fn winning_hands<'a>(hands: &[&'a str]) -> Vec<&'a str> {
    let mut hand_ranks: Vec<(usize, HandRank)> = Vec::new();
    for (i, &hand) in hands.iter().enumerate() {
        if let Some(cards) = parse_hand(hand) {
            hand_ranks.push((i, hand_rank(&cards)));
        }
    }
    if hand_ranks.is_empty() {
        return vec![];
    }
    let max_rank = hand_ranks.iter().map(|(_, r)| r).max().unwrap();
    hand_ranks
        .iter()
        .filter(|(_, r)| r == max_rank)
        .map(|(i, _)| hands[*i])
        .collect()
}
