impl std::error::Error for Error {}

pub struct Scale {
    notes: Vec<String>,
}

fn is_flat_scale(tonic: &str) -> bool {
    // List of tonics that use flats
    let flats = [
        "F", "Bb", "Eb", "Ab", "Db", "Gb",
        "d", "g", "c", "f", "bb", "eb",
    ];
    flats.contains(&tonic)
}

fn normalize_tonic(tonic: &str) -> String {
    let mut chars = tonic.chars();
    let first = chars.next().unwrap().to_ascii_uppercase();
    let rest: String = chars.as_str().to_ascii_lowercase();
    format!("{}{}", first, rest)
}

fn get_chromatic_scale(tonic: &str) -> Vec<&'static str> {
    // Use flats or sharps depending on tonic
    let sharp_scale = [
        "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"
    ];
    let flat_scale = [
        "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab", "A", "Bb", "B"
    ];

    let use_flats = is_flat_scale(tonic);
    let scale = if use_flats { &flat_scale } else { &sharp_scale };

    // Find the index of the tonic in the scale
    let tonic_norm = normalize_tonic(tonic);
    let idx = scale.iter().position(|&n| n.eq_ignore_ascii_case(&tonic_norm))
        .unwrap();

    // Rotate the scale so it starts with the tonic
    scale.iter().cycle().skip(idx).take(12).cloned().collect()
}

fn interval_steps(interval: char) -> usize {
    match interval {
        'm' => 1, // half step
        'M' => 2, // whole step
        'A' => 3, // augmented second
        _ => 0,
    }
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let chromatic = get_chromatic_scale(tonic);
        let mut notes = Vec::new();
        let mut idx = 0;
        notes.push(chromatic[idx].to_string());
        for interval in intervals.chars() {
            idx = (idx + interval_steps(interval)) % chromatic.len();
            notes.push(chromatic[idx].to_string());
        }
        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        let chromatic = get_chromatic_scale(tonic);
        let mut notes: Vec<String> = chromatic.iter().map(|&n| n.to_string()).collect();
        // Add the octave (tonic again at the end)
        notes.push(notes[0].clone());
        Ok(Scale { notes })
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
}
