use std::collections::{HashMap, HashSet};

fn parse_input(input: &str) -> (Vec<Vec<char>>, Vec<char>) {
    // Parse the input into addends and result
    // Example: "SEND + MORE == MONEY"
    let input = input.replace("==", "=");
    let parts: Vec<&str> = input.split('=').collect();
    let left = parts[0].trim();
    let right = parts[1].trim();

    let addends: Vec<Vec<char>> = left
        .split('+')
        .map(|s| s.trim().chars().collect())
        .collect();

    let result: Vec<char> = right.chars().collect();

    (addends, result)
}

fn get_unique_letters(addends: &[Vec<char>], result: &[char]) -> Vec<char> {
    let mut set = HashSet::new();
    for word in addends.iter().chain(std::iter::once(&result.to_vec())) {
        for &c in word {
            set.insert(c);
        }
    }
    set.into_iter().collect()
}

fn get_leading_letters(addends: &[Vec<char>], result: &[char]) -> HashSet<char> {
    let mut set = HashSet::new();
    for word in addends.iter().chain(std::iter::once(&result.to_vec())) {
        if let Some(&c) = word.first() {
            set.insert(c);
        }
    }
    set
}

fn word_to_number(word: &[char], mapping: &HashMap<char, u8>) -> Option<u64> {
    let mut num = 0u64;
    for &c in word {
        let digit = *mapping.get(&c)? as u64;
        num = num * 10 + digit;
    }
    Some(num)
}

fn is_valid(
    addends: &[Vec<char>],
    result: &[char],
    mapping: &HashMap<char, u8>,
) -> bool {
    let sum: Option<u64> = addends
        .iter()
        .map(|word| word_to_number(word, mapping))
        .collect::<Option<Vec<u64>>>()
        .map(|v| v.iter().sum());

    let result_num = word_to_number(result, mapping);

    match (sum, result_num) {
        (Some(s), Some(r)) => s == r,
        _ => false,
    }
}

fn solve_recursive(
    letters: &[char],
    idx: usize,
    used: &mut [bool; 10],
    mapping: &mut HashMap<char, u8>,
    addends: &[Vec<char>],
    result: &[char],
    leading_letters: &HashSet<char>,
) -> Option<HashMap<char, u8>> {
    if idx == letters.len() {
        if is_valid(addends, result, mapping) {
            return Some(mapping.clone());
        }
        return None;
    }

    let c = letters[idx];
    for digit in 0..=9 {
        if used[digit as usize] {
            continue;
        }
        // Leading letter cannot be zero
        if digit == 0 && leading_letters.contains(&c) {
            continue;
        }
        used[digit as usize] = true;
        mapping.insert(c, digit);
        if let Some(sol) = solve_recursive(
            letters,
            idx + 1,
            used,
            mapping,
            addends,
            result,
            leading_letters,
        ) {
            return Some(sol);
        }
        used[digit as usize] = false;
        mapping.remove(&c);
    }
    None
}

pub fn solve(input: &str) -> Option<HashMap<char, u8>> {
    let (addends, result) = parse_input(input);
    let mut letters = get_unique_letters(&addends, &result);
    if letters.len() > 10 {
        return None; // Not enough digits for unique letters
    }
    // To improve performance, sort letters so leading letters are assigned first (to avoid zero)
    let leading_letters = get_leading_letters(&addends, &result);
    letters.sort_by_key(|c| !leading_letters.contains(c));

    let mut used = [false; 10];
    let mut mapping = HashMap::new();
    solve_recursive(
        &letters,
        0,
        &mut used,
        &mut mapping,
        &addends,
        &result,
        &leading_letters,
    )
}
