use std::marker::PhantomData;

/// A Matcher is a single rule of fizzbuzz: given a function on T, should
/// a word be substituted in? If yes, which word?
pub struct Matcher<T> {
    matcher: Box<dyn Fn(&T) -> bool + Send + Sync>,
    subs: String,
    _phantom: PhantomData<T>,
}

impl<T> Matcher<T> {
    /// matcher: function that returns true if the substitution should be applied
    /// subs: the word to substitute
    pub fn new<F, S>(matcher: F, subs: S) -> Matcher<T>
    where
        F: Fn(T) -> bool + Send + Sync + 'static,
        S: Into<String>,
        T: 'static + Copy,
    {
        // Wrap the matcher so it takes &T, to match the trait bound
        let wrapped = move |x: &T| matcher(*x);
        Matcher {
            matcher: Box::new(wrapped),
            subs: subs.into(),
            _phantom: PhantomData,
        }
    }

    /// Returns Some(subs) if the matcher matches, else None
    pub fn check(&self, value: &T) -> Option<&str> {
        if (self.matcher)(value) {
            Some(&self.subs)
        } else {
            None
        }
    }
}

/// A Fizzy is a set of matchers, which may be applied to an iterator.
pub struct Fizzy<T> {
    matchers: Vec<Matcher<T>>,
    _phantom: PhantomData<T>,
}

impl<T> Fizzy<T> {
    pub fn new() -> Self {
        Fizzy {
            matchers: Vec::new(),
            _phantom: PhantomData,
        }
    }

    #[must_use]
    pub fn add_matcher(mut self, matcher: Matcher<T>) -> Self {
        self.matchers.push(matcher);
        self
    }

    /// map this fizzy onto every element of an iterator, returning a new iterator
    pub fn apply<I>(self, iter: I) -> impl Iterator<Item = String>
    where
        I: IntoIterator<Item = T>,
        T: std::fmt::Display,
    {
        let matchers = self.matchers;
        iter.into_iter().map(move |item| {
            let mut out = String::new();
            for matcher in &matchers {
                if let Some(word) = matcher.check(&item) {
                    out.push_str(word);
                }
            }
            if out.is_empty() {
                format!("{}", item)
            } else {
                out
            }
        })
    }
}

/// convenience function: return a Fizzy which applies the standard fizz-buzz rules
pub fn fizz_buzz<T>() -> Fizzy<T>
where
    T: std::ops::Rem<Output = T> + PartialEq + From<u8> + Copy + std::fmt::Display + 'static,
{
    Fizzy::new()
        .add_matcher(Matcher::new(
            |x: T| x % T::from(3u8) == T::from(0u8),
            "fizz",
        ))
        .add_matcher(Matcher::new(
            |x: T| x % T::from(5u8) == T::from(0u8),
            "buzz",
        ))
}
