use rand::Rng;

fn is_valid_key(key: &str) -> bool {
    !key.is_empty() && key.chars().all(|c| c.is_ascii_lowercase())
}

fn is_valid_text(s: &str) -> bool {
    s.chars().all(|c| c.is_ascii_lowercase())
}

fn shift_char(c: char, shift: i8) -> char {
    let a = b'a';
    let c_u8 = c as u8 - a;
    let shifted = ((c_u8 as i8 + shift + 26) % 26) as u8;
    (a + shifted) as char
}

pub fn encode(key: &str, s: &str) -> Option<String> {
    if !is_valid_key(key) || !is_valid_text(s) {
        return None;
    }
    let encoded: String = s
        .chars()
        .enumerate()
        .map(|(i, plain)| {
            let k = key.chars().nth(i % key.len()).unwrap();
            let shift = (k as u8 - b'a') as i8;
            shift_char(plain, shift)
        })
        .collect();
    Some(encoded)
}

pub fn decode(key: &str, s: &str) -> Option<String> {
    if !is_valid_key(key) || !is_valid_text(s) {
        return None;
    }
    let decoded: String = s
        .chars()
        .enumerate()
        .map(|(i, cipher)| {
            let k = key.chars().nth(i % key.len()).unwrap();
            let shift = -((k as u8 - b'a') as i8);
            shift_char(cipher, shift)
        })
        .collect();
    Some(decoded)
}

pub fn encode_random(s: &str) -> (String, String) {
    let mut rng = rand::thread_rng();
    let key_len = std::cmp::max(100, s.len());
    let key: String = (0..key_len)
        .map(|_| (b'a' + rng.gen_range(0..26)) as char)
        .collect();
    let encoded = encode(&key, s).unwrap();
    (key, encoded)
}
