use anyhow::{Context, Error};
use std::collections::HashSet;
use std::fs::File;
use std::io::{BufRead, BufReader};

#[derive(Debug, Default)]
pub struct Flags {
    pub line_number: bool,      // -n
    pub file_names_only: bool,  // -l
    pub case_insensitive: bool, // -i
    pub invert: bool,           // -v
    pub match_entire_line: bool, // -x
}

impl Flags {
    pub fn new(flags: &[&str]) -> Self {
        let mut f = Flags::default();
        for &flag in flags {
            match flag {
                "-n" => f.line_number = true,
                "-l" => f.file_names_only = true,
                "-i" => f.case_insensitive = true,
                "-v" => f.invert = true,
                "-x" => f.match_entire_line = true,
                _ => {}
            }
        }
        f
    }
}

pub fn grep(pattern: &str, flags: &Flags, files: &[&str]) -> Result<Vec<String>, Error> {
    let mut results = Vec::new();
    let multiple_files = files.len() > 1;
    let mut matched_files = HashSet::new();

    for &filename in files {
        let file = File::open(filename)
            .with_context(|| format!("Failed to open file: {}", filename))?;
        let reader = BufReader::new(file);

        let mut file_has_match = false;

        for (idx, line_result) in reader.lines().enumerate() {
            let line = line_result?;

            // Prepare haystack and needle, ensuring lifetimes are correct
            let (haystack, needle);
            let (haystack_ref, needle_ref) = if flags.case_insensitive {
                haystack = line.to_lowercase();
                needle = pattern.to_lowercase();
                (haystack.as_str(), needle.as_str())
            } else {
                (line.as_str(), pattern)
            };

            let is_match = if flags.match_entire_line {
                haystack_ref == needle_ref
            } else {
                haystack_ref.contains(needle_ref)
            };

            let final_match = if flags.invert { !is_match } else { is_match };

            if final_match {
                file_has_match = true;
                if flags.file_names_only {
                    matched_files.insert(filename.to_string());
                    break; // Only need to know if at least one line matches
                } else {
                    let mut out = String::new();
                    if multiple_files {
                        out.push_str(filename);
                        out.push(':');
                    }
                    if flags.line_number {
                        out.push_str(&(idx + 1).to_string());
