#if !defined(BINARY_SEARCH_TREE_H)
#define BINARY_SEARCH_TREE_H

#include <memory>
#include <iterator>
#include <vector>
#include <stack>
#include <utility>
#include <cstddef>

namespace binary_search_tree {

template <typename T>
class binary_tree {
public:
    using value_type = T;
    using tree_ptr = std::unique_ptr<binary_tree<T>>;

    binary_tree(const T& value)
        : data_(value), left_(nullptr), right_(nullptr) {}

    void insert(const T& value) {
        if (value <= data_) {
            if (left_) {
                left_->insert(value);
            } else {
                left_ = std::make_unique<binary_tree<T>>(value);
            }
        } else {
            if (right_) {
                right_->insert(value);
            } else {
                right_ = std::make_unique<binary_tree<T>>(value);
            }
        }
    }

    const T& data() const {
        return data_;
    }

    const tree_ptr& left() const {
        return left_;
    }

    const tree_ptr& right() const {
        return right_;
    }

    class iterator {
    public:
        using iterator_category = std::forward_iterator_tag;
        using value_type = T;
        using difference_type = std::ptrdiff_t;
        using pointer = const T*;
        using reference = const T&;

        iterator() : current_(nullptr) {}

        explicit iterator(const binary_tree<T>* root) : current_(nullptr) {
            push_left(root);
            if (!nodes_.empty()) {
                current_ = nodes_.top();
            }
        }

        reference operator*() const {
            return current_->data_;
        }

        pointer operator->() const {
            return &(current_->data_);
        }

        iterator& operator++() {
            if (nodes_.empty()) {
                current_ = nullptr;
                return *this;
            }
            const binary_tree<T>* node = nodes_.top();
            nodes_.pop();
            if (node->right_) {
                push_left(node->right_.get());
            }
            if (!nodes_.empty()) {
                current_ = nodes_.top();
            } else {
                current_ = nullptr;
            }
            return *this;
        }

        iterator operator++(int) {
            iterator tmp = *this;
            ++(*this);
            return tmp;
        }

        bool operator==(const iterator& other) const {
            return current_ == other.current_;
        }

        bool operator!=(const iterator& other) const {
            return !(*this == other);
        }

    private:
        std::stack<const binary_tree<T>*> nodes_;
        const binary_tree<T>* current_;

        void push_left(const binary_tree<T>* node) {
            while (node) {
                nodes_.push(node);
                node = node->left_.get();
            }
        }
    };

    iterator begin() const {
        return iterator(this);
    }

    iterator end() const {
        return iterator();
    }

private:
    T data_;
    tree_ptr left_;
    tree_ptr right_;
};

template <typename T>
std::unique_ptr<binary_tree<T>> make_tree(const std::vector<T>& values) {
    if (values.empty()) return nullptr;
    auto root = std::make_unique<binary_tree<T>>(values[0]);
    for (size_t i = 1; i < values.size(); ++i) {
        root->insert(values[i]);
    }
    return root;
}

}  // namespace binary_search_tree

#endif // BINARY_SEARCH_TREE_H
