#include "binary_search_tree.h"

namespace binary_search_tree {

Node::Node(int value) : data(value), left(nullptr), right(nullptr) {}

void Node::insert(int value) {
    if (value <= data) {
        if (left) {
            left->insert(value);
        } else {
            left = std::make_unique<Node>(value);
        }
    } else {
        if (right) {
            right->insert(value);
        } else {
            right = std::make_unique<Node>(value);
        }
    }
}

bool Node::search(int value) const {
    if (value == data) {
        return true;
    } else if (value < data) {
        return left ? left->search(value) : false;
    } else {
        return right ? right->search(value) : false;
    }
}

BinarySearchTree::BinarySearchTree() : root(nullptr) {}

void BinarySearchTree::insert(int value) {
    if (root) {
        root->insert(value);
    } else {
        root = std::make_unique<Node>(value);
    }
}

bool BinarySearchTree::search(int value) const {
    return root ? root->search(value) : false;
}

}  // namespace binary_search_tree
