#include <vector>
#include <stdexcept>
#include <cstddef>

namespace circular_buffer {

template <typename T>
class CircularBuffer {
public:
    explicit CircularBuffer(size_t capacity);

    void write(const T& value);
    void overwrite(const T& value);
    T read();
    void clear();

    bool is_empty() const;
    bool is_full() const;

private:
    std::vector<T> buffer_;
    size_t capacity_;
    size_t head_;
    size_t tail_;
    size_t size_;
};

// Implementation must be in header for templates:
template <typename T>
CircularBuffer<T>::CircularBuffer(size_t capacity)
    : buffer_(capacity), capacity_(capacity), head_(0), tail_(0), size_(0) {}

template <typename T>
void CircularBuffer<T>::write(const T& value) {
    if (this->is_full()) {
        throw std::runtime_error("Buffer is full");
    }
    buffer_[tail_] = value;
    tail_ = (tail_ + 1) % capacity_;
    ++size_;
}

template <typename T>
void CircularBuffer<T>::overwrite(const T& value) {
    if (this->is_full()) {
        buffer_[tail_] = value;
        tail_ = (tail_ + 1) % capacity_;
        head_ = tail_;
    } else {
        write(value);
    }
}

template <typename T>
T CircularBuffer<T>::read() {
    if (this->is_empty()) {
        throw std::runtime_error("Buffer is empty");
    }
    T value = buffer_[head_];
    head_ = (head_ + 1) % capacity_;
    --size_;
    return value;
}

template <typename T>
void CircularBuffer<T>::clear() {
    head_ = 0;
    tail_ = 0;
    size_ = 0;
}

template <typename T>
bool CircularBuffer<T>::is_empty() const {
    return size_ == 0;
}

template <typename T>
bool CircularBuffer<T>::is_full() const {
    return size_ == capacity_;
}

}  // namespace circular_buffer

#endif // CIRCULAR_BUFFER_H
