#include "crypto_square.h"
#include <cctype>
#include <string>
#include <vector>
#include <cmath>

namespace crypto_square {

static std::string normalize(const std::string& text) {
    std::string result;
    for (char ch : text) {
        if (std::isalnum(static_cast<unsigned char>(ch))) {
            result += std::tolower(static_cast<unsigned char>(ch));
        }
    }
    return result;
}

std::string cipher(const std::string& text) {
    std::string norm = normalize(text);
    size_t len = norm.size();
    if (len == 0) return "";

    // Find r and c
    size_t c = static_cast<size_t>(std::ceil(std::sqrt(len)));
    size_t r = static_cast<size_t>(std::floor(std::sqrt(len)));
    if (r * c < len) ++r;
    if (c < r) std::swap(c, r);

    // Pad the normalized string to fit the rectangle
    size_t padded_len = r * c;
    std::string padded = norm + std::string(padded_len - len, ' ');

    // Read down the columns
    std::vector<std::string> chunks;
    for (size_t col = 0; col < c; ++col) {
        std::string chunk;
        for (size_t row = 0; row < r; ++row) {
            chunk += padded[row * c + col];
        }
        chunks.push_back(chunk);
    }

    // Join with spaces
    std::string result;
    for (size_t i = 0; i < chunks.size(); ++i) {
        result += chunks[i];
        if (i != chunks.size() - 1) result += " ";
    }
    return result;
}

}  // namespace crypto_square
