namespace queen_attack {

static bool is_on_board(const std::pair<int, int>& pos) {
    return pos.first >= 0 && pos.first < 8 && pos.second >= 0 && pos.second < 8;
}

chess_board::chess_board(std::pair<int, int> white, std::pair<int, int> black)
    : white_pos(white), black_pos(black)
{
    if (white == black) {
        throw std::domain_error("Queens cannot occupy the same position");
    }
    if (!is_on_board(white) || !is_on_board(black)) {
        throw std::domain_error("Queen position must be on the board");
    }
}

std::pair<int, int> chess_board::white() const {
    return white_pos;
}

std::pair<int, int> chess_board::black() const {
    return black_pos;
}

bool chess_board::can_attack() const {
    // Same row
    if (white_pos.first == black_pos.first) {
        return true;
    }
    // Same column
    if (white_pos.second == black_pos.second) {
        return true;
    }
    // Same diagonal
    if (std::abs(white_pos.first - black_pos.first) == std::abs(white_pos.second - black_pos.second)) {
        return true;
    }
    return false;
}

}  // namespace queen_attack
