#include "complex_numbers.h"
#include <cmath>

namespace complex_numbers {

Complex::Complex(double real, double imag) : re(real), im(imag) {}

double Complex::real() const {
    return re;
}

double Complex::imag() const {
    return im;
}

Complex Complex::operator+(const Complex& other) const {
    return Complex(re + other.re, im + other.im);
}

Complex Complex::operator-(const Complex& other) const {
    return Complex(re - other.re, im - other.im);
}

Complex Complex::operator*(const Complex& other) const {
    // (a + ib) * (c + id) = (ac - bd) + (bc + ad)i
    double real_part = re * other.re - im * other.im;
    double imag_part = im * other.re + re * other.im;
    return Complex(real_part, imag_part);
}

Complex Complex::operator/(const Complex& other) const {
    // (a + ib) / (c + id) = [(ac + bd) / (c^2 + d^2)] + [(bc - ad) / (c^2 + d^2)]i
    double denominator = other.re * other.re + other.im * other.im;
    double real_part = (re * other.re + im * other.im) / denominator;
    double imag_part = (im * other.re - re * other.im) / denominator;
    return Complex(real_part, imag_part);
}

// Member operators for Complex op double
Complex Complex::operator+(double value) const {
    return Complex(re + value, im);
}

Complex Complex::operator-(double value) const {
    return Complex(re - value, im);
}

Complex Complex::operator*(double value) const {
    return Complex(re * value, im * value);
}

Complex Complex::operator/(double value) const {
    return Complex(re / value, im / value);
}

Complex Complex::conj() const {
    return Complex(re, -im);
}

double Complex::abs() const {
    return std::sqrt(re * re + im * im);
}

Complex Complex::exp() const {
    // e^(a + ib) = e^a * (cos(b) + i sin(b))
    double exp_real = std::exp(re);
    double real_part = exp_real * std::cos(im);
    double imag_part = exp_real * std::sin(im);
    return Complex(real_part, imag_part);
}

// Non-member operators for double op Complex
Complex operator+(double lhs, const Complex& rhs) {
    return Complex(lhs + rhs.real(), rhs.imag());
}

Complex operator-(double lhs, const Complex& rhs) {
    return Complex(lhs - rhs.real(), -rhs.imag());
}

Complex operator*(double lhs, const Complex& rhs) {
    return Complex(lhs * rhs.real(), lhs * rhs.imag());
}

Complex operator/(double lhs, const Complex& rhs) {
    // lhs / (a + ib) = lhs * (a - ib) / (a^2 + b^2)
    double denominator = rhs.real() * rhs.real() + rhs.imag() * rhs.imag();
    double real_part = lhs * rhs.real() / denominator;
    double imag_part = -lhs * rhs.imag() / denominator;
    return Complex(real_part, imag_part);
}

