        return None

    def _find_path_any(self, current, target, path, parent=None):
        """Helper to find path from current node to target label, traversing up and down."""
        if current.label == target:
            return path + [current]
        # Traverse children
        for child in current.children:
            if parent and child.label == parent.label:
                continue
            res = self._find_path_any(child, target, path + [current], current)
            if res:
