def BuildTree(records):
    if not records:
        return None

    # Sort records by record_id
    records.sort(key=lambda x: x.record_id)
    n = len(records)

    # Validation: IDs must be continuous from 0 to n-1
    for idx, record in enumerate(records):
        if record.record_id != idx:
            raise ValueError("Record id is invalid or out of order.")

    # Validation: Root node
    if records[0].record_id != 0 or records[0].parent_id != 0:
        raise ValueError("Node parent_id should be smaller than it's record_id.")

    # Validation: No node can have parent_id >= record_id (except root)
    for record in records:
        if record.record_id == 0 and record.parent_id == 0:
            continue
        if record.parent_id == record.record_id:
            raise ValueError("Only root should have equal record and parent id.")
        if record.parent_id > record.record_id:
            raise ValueError("Node parent_id should be smaller than it's record_id.")
        if record.parent_id < 0:
            raise ValueError("Node parent_id should be smaller than it's record_id.")

    # Build nodes
    nodes = [Node(i) for i in range(n)]

    # Build tree structure
    for record in records:
        if record.record_id == 0:
            continue  # root node
        parent_id = record.parent_id
        nodes[parent_id].children.append(nodes[record.record_id])

    return nodes[0]
