        self._students = set()
        # Track results of add_student calls in order
        self._add_results = []

    def add_student(self, name, grade):
        if name in self._students:
            self._add_results.append(False)
            return False
        if grade not in self._grades:
            self._grades[grade] = set()
        self._grades[grade].add(name)
        self._students.add(name)
        self._add_results.append(True)
        return True

    def roster(self):
        # Return a list of all students in the school, sorted by grade then name
        result = []
        for grade in sorted(self._grades):
            result.extend(sorted(self._grades[grade]))
        return result

    def grade(self, grade_number):
        # Return a sorted list of students in the given grade
        if grade_number not in self._grades:
            return []
        return sorted(self._grades[grade_number])

    def added(self):
        # Return the list of results of add_student calls
        return self._add_results
