class Board:
    """Count territories of each player in a Go game

    Args:
        board (list[str]): A two-dimensional Go board
    """

    def __init__(self, board):
        self.board = board
        self.height = len(board)
        self.width = len(board[0]) if self.height > 0 else 0

    def _in_bounds(self, x, y):
        return 0 <= x < self.width and 0 <= y < self.height

    def _neighbors(self, x, y):
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if self._in_bounds(nx, ny):
                yield (nx, ny)

    def _flood_fill(self, x, y, visited):
        """Flood fill from (x, y) to find all connected empty points and bordering colors."""
        stack = [(x, y)]
        territory = set()
        bordering_colors = set()
        while stack:
            cx, cy = stack.pop()
            if (cx, cy) in visited:
                continue
            visited.add((cx, cy))
            if self.board[cy][cx] == ' ':
                territory.add((cx, cy))
                for nx, ny in self._neighbors(cx, cy):
                    if (nx, ny) not in visited:
                        stack.append((nx, ny))
            else:
                bordering_colors.add(self.board[cy][cx])
        return territory, bordering_colors

    def territory(self, x, y):
        """Find the owner and the territories given a coordinate on
           the board

        Args:
            x (int): Column on the board
            y (int): Row on the board

        Returns:
            (str, set): A tuple, the first element being the owner
                        of that area.  One of "W", "B", "".  The
                        second being a set of coordinates, representing
                        the owner's territories.
        """
        if not self._in_bounds(x, y):
            raise ValueError('Invalid coordinate')
        if self.board[y][x] != ' ':
            return (NONE, set())
        visited = set()
        territory, bordering_colors = self._flood_fill(x, y, visited)
        bordering_colors = set(c for c in bordering_colors if c in (WHITE, BLACK))
        if len(bordering_colors) == 1:
            owner = bordering_colors.pop()
        else:
            owner = NONE
        return (owner, territory)

    def territories(self):
        """Find the owners and the territories of the whole board

        Args:
            none

        Returns:
            dict(str, set): A dictionary whose key being the owner
                        , i.e. "W", "B", "".  The value being a set
                        of coordinates owned by the owner.
        """
        result = {BLACK: set(), WHITE: set(), NONE: set()}
        visited = set()
        for y in range(self.height):
            for x in range(self.width):
                if self.board[y][x] == ' ' and (x, y) not in visited:
                    terr_owner, terr_coords = self.territory(x, y)
                    visited.update(terr_coords)
                    result[terr_owner].update(terr_coords)
        return result
