def grep(pattern, flags, files):
    # Parse flags if passed as a single string
    if isinstance(flags, str):
        flags = flags.split()
    results = []
    match_case_insensitive = '-i' in flags
    invert_match = '-v' in flags
    match_entire_line = '-x' in flags
    show_line_numbers = '-n' in flags
    only_filenames = '-l' in flags

    matched_files = []

    for filename in files:
        with open(filename, 'r', encoding='utf-8') as f:
            lines = f.readlines()

        file_has_match = False
        for idx, line in enumerate(lines):
            line_content = line.rstrip('\n')

            # Prepare line and pattern for matching
            if match_case_insensitive:
                line_to_match = line_content.lower()
                pattern_to_match = pattern.lower()
            else:
                line_to_match = line_content
                pattern_to_match = pattern

            if match_entire_line:
                is_match = line_to_match == pattern_to_match
            else:
                is_match = pattern_to_match in line_to_match

            if invert_match:
                is_match = not is_match

            if is_match:
                file_has_match = True
                if only_filenames:
                    if filename not in matched_files:
                        matched_files.append(filename)
                    break  # Only need to know if at least one match exists
                else:
                    prefix = ''
                    if len(files) > 1:
                        prefix += f"{filename}:"
                    if show_line_numbers:
                        prefix += f"{idx+1}:"
                    results.append(f"{prefix}{line_content}")

    # Output formatting
    if only_filenames:
        # Output file names, one per line, in order of appearance
        return ''.join(f"{fname}\n" for fname in matched_files)
    else:
        if not results:
            return ""
        return ''.join(f"{line}\n" for line in results)
