import json

class RestAPI:
    def __init__(self, database=None):
        if database is None:
            self.users = []
        else:
            # Deep copy to avoid mutating input
            self.users = []
            for u in database.get("users", []):
                self.users.append({
                    "name": u["name"],
                    "owes": dict(u.get("owes", {})),
                    "owed_by": dict(u.get("owed_by", {})),
                    "balance": float(u.get("balance", 0.0))
                })

    def get(self, url, payload=None):
        if payload:
            data = json.loads(payload)
        else:
            data = {}

        if url == "/users":
            if "users" in data:
                # Return only the specified users, sorted by name
                selected_users = [self._get_user_obj(name) for name in data["users"]]
                selected_users = [u for u in selected_users if u is not None]
                selected_users.sort(key=lambda u: u["name"])
                return json.dumps({"users": selected_users})
            else:
                # Return all users, sorted by name
                all_users = [self._get_user_obj(u["name"]) for u in self.users]
                all_users.sort(key=lambda u: u["name"])
                return json.dumps({"users": all_users})
        else:
            return json.dumps({})

    def post(self, url, payload=None):
        data = json.loads(payload) if payload else {}

        if url == "/add":
            name = data["user"]
            if self._find_user(name) is not None:
                pass
            else:
                user = {
                    "name": name,
                    "owes": {},
                    "owed_by": {},
                    "balance": 0.0
                }
                self.users.append(user)
            return json.dumps(self._get_user_obj(name))

        elif url == "/iou":
            lender = data["lender"]
            borrower = data["borrower"]
            amount = float(data["amount"])

            lender_obj = self._find_user(lender)
            borrower_obj = self._find_user(borrower)

            # Net out any existing debts between lender and borrower
            # If lender owes borrower, reduce that first
            lender_owes_borrower = lender_obj["owes"].get(borrower, 0.0)
            borrower_owes_lender = borrower_obj["owes"].get(lender, 0.0)

            if lender_owes_borrower > 0:
                if lender_owes_borrower > amount:
                    # Lender still owes borrower after this transaction
                    lender_obj["owes"][borrower] = round(lender_owes_borrower - amount, 2)
                    borrower_obj["owed_by"][lender] = round(lender_owes_borrower - amount, 2)
                    amount = 0.0
                elif lender_owes_borrower == amount:
                    # Debts cancel out
                    lender_obj["owes"].pop(borrower)
                    borrower_obj["owed_by"].pop(lender)
                    amount = 0.0
                else:
                    # Lender's debt to borrower is less than the new IOU, so cancel that and borrower now owes lender
                    lender_obj["owes"].pop(borrower)
                    borrower_obj["owed_by"].pop(lender)
                    amount = round(amount - lender_owes_borrower, 2)
            # Now, if any amount remains, borrower owes lender
            if amount > 0:
                prev_borrower_owes_lender = borrower_obj["owes"].get(lender, 0.0)
                borrower_obj["owes"][lender] = round(prev_borrower_owes_lender + amount, 2)
                lender_obj["owed_by"][borrower] = round(lender_obj["owed_by"].get(borrower, 0.0) + amount, 2)

            # Clean up zero balances in owes/owed_by
            for user in (lender_obj, borrower_obj):
                for key in list(user["owes"].keys()):
                    if abs(user["owes"][key]) < 1e-9:
                        user["owes"].pop(key)
                for key in list(user["owed_by"].keys()):
                    if abs(user["owed_by"][key]) < 1e-9:
                        user["owed_by"].pop(key)

            # Recalculate balances
            self._recalculate_balance(lender_obj)
            self._recalculate_balance(borrower_obj)

            # Return updated user objects for lender and borrower, sorted by name
            users = [self._get_user_obj(lender), self._get_user_obj(borrower)]
            users.sort(key=lambda u: u["name"])
            return json.dumps({"users": users})

        else:
            return json.dumps({})

    def _find_user(self, name):
        for user in self.users:
            if user["name"] == name:
                return user
        return None

    def _get_user_obj(self, name):
        user = self._find_user(name)
        if user is not None:
            return {
                "name": user["name"],
                "owes": dict(user["owes"]),
                "owed_by": dict(user["owed_by"]),
                "balance": round(self._calc_balance(user), 2)
            }
        return None

    def _calc_balance(self, user):
        owed_by_total = sum(user["owed_by"].values())
        owes_total = sum(user["owes"].values())
        return round(owed_by_total - owes_total, 2)

    def _recalculate_balance(self, user):
        user["balance"] = self._calc_balance(user)
