                    lender_obj["owes"].pop(borrower, None)
                else:
                    # They are even
                    borrower_obj["owed_by"].pop(lender, None)
                    borrower_obj["owes"].pop(lender, None)
                    lender_obj["owed_by"].pop(borrower, None)
