class ConnectGame:
    def __init__(self, board):
        # Accepts either a string or a list of strings
        if isinstance(board, str):
            board = board.strip('\n').split('\n')
        self.board = []
        for line in board:
            row = line.strip().split()
            self.board.append(row)
        self.height = len(self.board)
        self.width = max(len(row) for row in self.board) if self.board else 0

    def get_winner(self):
        # Check for O (top to bottom)
        if self._has_path('O'):
            return 'O'
        # Check for X (left to right)
        if self._has_path('X'):
            return 'X'
        return ""

    def _has_path(self, player):
        visited = set()
        if player == 'O':
            # O: top to bottom
            for col in range(self.width):
                if self._cell(0, col) == 'O':
                    if self._dfs(0, col, player, visited):
                        return True
        elif player == 'X':
            # X: left to right
            for row in range(self.height):
                if self._cell(row, 0) == 'X':
                    if self._dfs(row, 0, player, visited):
                        return True
        return False

    def _dfs(self, row, col, player, visited):
        stack = [(row, col)]
        while stack:
            r, c = stack.pop()
            if (r, c) in visited:
                continue
            visited.add((r, c))

            if player == 'O' and r == self.height - 1:
                return True
            if player == 'X' and c == len(self.board[r]) - 1:
                return True

            for nr, nc in self._neighbors(r, c):
                if self._cell(nr, nc) == player and (nr, nc) not in visited:
                    stack.append((nr, nc))
        return False

    def _cell(self, row, col):
        if 0 <= row < self.height and 0 <= col < len(self.board[row]):
            return self.board[row][col]
        return None

    def _neighbors(self, row, col):
        # Hex grid neighbors: (r, c) + [(-1, 0), (-1, 1), (0, -1), (0, 1), (1, -1), (1, 0)]
        directions = [(-1, 0), (-1, 1), (0, -1), (0, 1), (1, -1), (1, 0)]
        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < self.height and 0 <= nc < len(self.board[nr]):
                yield (nr, nc)
