export class List {
  constructor(values = []) {
    this.values = values;
  }

  append(otherList) {
    // Returns a new List with this.values followed by otherList.values
    const result = [];
    for (let i = 0; i < this.values.length; i++) {
      result[result.length] = this.values[i];
    }
    for (let j = 0; j < otherList.values.length; j++) {
      result[result.length] = otherList.values[j];
    }
    return new List(result);
  }

  concat(lists) {
    // lists is an array of List instances
    let result = [];
    for (let i = 0; i < this.values.length; i++) {
      result[result.length] = this.values[i];
    }
    for (let i = 0; i < lists.values.length; i++) {
      const sublist = lists.values[i];
      for (let j = 0; j < sublist.values.length; j++) {
        result[result.length] = sublist.values[j];
      }
    }
    return new List(result);
  }

  filter(predicate) {
    const result = [];
    for (let i = 0; i < this.values.length; i++) {
      if (predicate(this.values[i])) {
        result[result.length] = this.values[i];
      }
    }
    return new List(result);
  }

  map(fn) {
    const result = [];
    for (let i = 0; i < this.values.length; i++) {
      result[result.length] = fn(this.values[i]);
    }
    return new List(result);
  }

  length() {
    let count = 0;
    for (let i = 0; i < this.values.length; i++) {
      count = count + 1;
    }
    return count;
  }

  foldl(fn, initial) {
    let acc = initial;
    for (let i = 0; i < this.values.length; i++) {
      acc = fn(acc, this.values[i]);
    }
    return acc;
  }

  foldr(fn, initial) {
    let acc = initial;
    for (let i = this.values.length - 1; i >= 0; i--) {
      acc = fn(acc, this.values[i]);
    }
    return acc;
  }

  reverse() {
    const result = [];
    for (let i = this.values.length - 1; i >= 0; i--) {
      result[result.length] = this.values[i];
    }
    return new List(result);
  }
}
