const HEADER = 'Team                           | MP |  W |  D |  L |  P';

function padTeamName(name) {
  // Pad or trim team name to 31 chars (to fit 31 + 1 for the |)
  return name.padEnd(31, ' ');
}

function formatRow(team, stats) {
  return (
    padTeamName(team) +
    `|  ${stats.MP} |  ${stats.W} |  ${stats.D} |  ${stats.L} |  ${stats.P}`
  );
}

function compareTeams([teamA, statsA], [teamB, statsB]) {
  if (statsA.P !== statsB.P) {
    return statsB.P - statsA.P; // Descending by points
  }
  // Alphabetical order if points are equal
  if (teamA < teamB) return -1;
  if (teamA > teamB) return 1;
  return 0;
}

export const tournamentTally = (input) => {
  // If input is empty, just return the header
  if (!input || input.trim() === '') {
    return HEADER;
  }

  // Stats per team
  const teams = {};

  // Process each line
  input.trim().split('\n').forEach(line => {
    if (!line.trim()) return; // skip empty lines
    const [team1, team2, result] = line.split(';');
    // Initialize stats if not present
    if (!teams[team1]) teams[team1] = { MP: 0, W: 0, D: 0, L: 0, P: 0 };
    if (!teams[team2]) teams[team2] = { MP: 0, W: 0, D: 0, L: 0, P: 0 };

    teams[team1].MP += 1;
    teams[team2].MP += 1;

    if (result === 'win') {
      teams[team1].W += 1;
      teams[team1].P += 3;
      teams[team2].L += 1;
    } else if (result === 'loss') {
      teams[team2].W += 1;
      teams[team2].P += 3;
      teams[team1].L += 1;
    } else if (result === 'draw') {
      teams[team1].D += 1;
      teams[team2].D += 1;
      teams[team1].P += 1;
      teams[team2].P += 1;
    }
  });

  // Sort teams by points descending, then alphabetically
  const sortedTeams = Object.entries(teams).sort(compareTeams);

  // Format output
  const lines = [HEADER];
  for (const [team, stats] of sortedTeams) {
    lines.push(formatRow(team, stats));
  }

  return lines.join('\n');
};
