//
// This is only a SKELETON file for the 'BookStore' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

const BOOK_PRICE = 800; // in cents

const DISCOUNTS = {
  1: 1.0,
  2: 0.95,
  3: 0.90,
  4: 0.80,
  5: 0.75,
};

// Helper function to count the number of each book
function countBooks(books) {
  const counts = [0, 0, 0, 0, 0];
  for (const book of books) {
    counts[book - 1]++;
  }
  return counts;
}

// Helper function to get all possible groupings recursively
function minCost(counts, memo = {}) {
  // Memoization key
  const key = counts.join(',');
  if (memo[key] !== undefined) {
    return memo[key];
  }

  // If all books are bought
  if (counts.every(c => c === 0)) {
    return 0;
  }

  let min = Infinity;

  // Try all possible group sizes (from 5 down to 1)
  // To avoid the "5+3" vs "4+4" problem, we only try group sizes 5, 4, 3, 2, 1
  // and always try all possible groupings recursively.
  for (let groupSize = 5; groupSize >= 1; groupSize--) {
    // Find all indices with at least one book left
    let idxs = [];
    for (let i = 0; i < counts.length; i++) {
      if (counts[i] > 0) {
        idxs.push(i);
      }
    }
    if (idxs.length < groupSize) continue;

    // Generate all combinations of groupSize indices
    const combinations = getCombinations(idxs, groupSize);
    for (const combo of combinations) {
      // Remove one copy of each book in the group
      const newCounts = counts.slice();
      for (const idx of combo) {
        newCounts[idx]--;
      }

      // Calculate cost for this group + recursively for the rest
      const groupCost = Math.round(groupSize * BOOK_PRICE * DISCOUNTS[groupSize]);
      const totalCost = groupCost + minCost(newCounts, memo);

      if (totalCost < min) {
        min = totalCost;
      }
    }
  }

  memo[key] = min;
  return min;
}

// Helper to get all combinations of a certain size from an array
function getCombinations(arr, k) {
  if (k === 0) return [[]];
  if (arr.length < k) return [];
  if (arr.length === k) return [arr.slice()];
  const [first, ...rest] = arr;
  const withFirst = getCombinations(rest, k - 1).map(comb => [first, ...comb]);
  const withoutFirst = getCombinations(rest, k);
  return withFirst.concat(withoutFirst);
}

export const cost = (books) => {
  if (!books || books.length === 0) return 0;
  const counts = countBooks(books);
  return minCost(counts);
};
