export class GradeSchool {
  constructor() {
    // Map grade (number) -> array of student names (strings)
    this._grades = {};
  }

  roster() {
    // Return a deep copy of the roster, sorted as required
    const result = {};
    Object.keys(this._grades)
      .map(Number)
      .sort((a, b) => a - b)
      .forEach(grade => {
        // Copy and sort the array of names
        result[grade] = [...this._grades[grade]].sort();
      });
    return result;
  }

  add(name, grade) {
    // Remove student from any previous grade
    for (const g in this._grades) {
      const idx = this._grades[g].indexOf(name);
      if (idx !== -1) {
        // If student is already in the same grade, do nothing
        if (parseInt(g, 10) === grade) {
          return;
        }
        // Remove from previous grade
        this._grades[g].splice(idx, 1);
      }
    }
    if (!this._grades[grade]) {
      this._grades[grade] = [];
    }
    this._grades[grade].push(name);
  }

  grade(grade) {
    // Return a sorted copy of the students in the given grade
    if (!this._grades[grade]) {
      return [];
    }
    return [...this._grades[grade]].sort();
  }
}
