function bottlePhrase(count, capitalize = false) {
  let phrase = '';
  if (count === 0) {
    phrase = 'no more bottles of beer';
    if (capitalize) {
      phrase = 'No more bottles of beer';
    }
  } else if (count === 1) {
    phrase = '1 bottle of beer';
  } else {
    phrase = `${count} bottles of beer`;
  }
  return phrase;
}

function wallPhrase(count, capitalize = false) {
  let phrase = '';
  if (count === 0) {
    phrase = 'no more bottles of beer on the wall';
    if (capitalize) {
      phrase = 'No more bottles of beer on the wall';
    }
  } else if (count === 1) {
    phrase = '1 bottle of beer on the wall';
  } else {
    phrase = `${count} bottles of beer on the wall`;
  }
  return phrase;
}

function actionPhrase(count) {
  if (count === 0) {
    return 'Go to the store and buy some more, 99 bottles of beer on the wall.';
  } else if (count === 1) {
    return 'Take it down and pass it around, no more bottles of beer on the wall.';
  } else if (count === 2) {
    return 'Take one down and pass it around, 1 bottle of beer on the wall.';
  } else {
    return `Take one down and pass it around, ${count - 1} bottles of beer on the wall.`;
  }
}

function verse(count) {
  if (count === 0) {
    return [
      'No more bottles of beer on the wall, no more bottles of beer.',
      'Go to the store and buy some more, 99 bottles of beer on the wall.'
    ];
  } else {
    return [
      `${bottlePhrase(count, true)} on the wall, ${bottlePhrase(count)}.`,
      actionPhrase(count)
    ];
  }
}

export const recite = (initialBottlesCount, takeDownCount) => {
  const verses = [];
  for (let i = 0; i < takeDownCount; i++) {
    const currentCount = initialBottlesCount - i;
    const lines = verse(currentCount);
    verses.push(...lines);
    if (i < takeDownCount - 1) {
      verses.push('');
    }
  }
  return verses;
};
