export class Binary {
  constructor(input) {
    this.input = input;
  }

  toDecimal() {
    // Check for invalid input: only '0' and '1' allowed
    if (!/^[01]+$/.test(this.input)) {
      return null;
    }

    let decimal = 0;
    // Process each digit from right to left
    for (let i = 0; i < this.input.length; i++) {
      const digit = this.input[this.input.length - 1 - i];
      // digit is either '0' or '1'
      decimal += Number(digit) * Math.pow(2, i);
    }
    return decimal;
  }
}
