    }
    words.push(tensWord);
  } else if (n > 0) {
    words.push(ONES[n]);
  }
  return words.join(' ');
}

function splitIntoThousands(n) {
  const chunks = [];
  do {
    chunks.unshift(n % 1000);
    n = Math.floor(n / 1000);
  } while (n > 0);
  return chunks;
}

