package dndcharacter

import (
	"math/rand"
	"sort"
	"time"
)

type Character struct {
	Strength     int
	Dexterity    int
	Constitution int
	Intelligence int
	Wisdom       int
	Charisma     int
	Hitpoints    int
}

// Modifier calculates the ability modifier for a given ability score
func Modifier(score int) int {
	return (score - 10) / 2 - b2i((score-10)%2 < 0)
}

// b2i converts a bool to int (true -> 1, false -> 0)
func b2i(b bool) int {
	if b {
		return 1
	}
	return 0
}

// Ability uses randomness to generate the score for an ability
func Ability() int {
	// Seed the random number generator (only once)
	rand.Seed(time.Now().UnixNano())

	rolls := make([]int, 4)
	for i := 0; i < 4; i++ {
		rolls[i] = rand.Intn(6) + 1 // random int in [1,6]
	}
	sort.Ints(rolls)
	// sum the largest three
	return rolls[1] + rolls[2] + rolls[3]
}

// GenerateCharacter creates a new Character with random scores for abilities
func GenerateCharacter() Character {
	str := Ability()
	dex := Ability()
	con := Ability()
	intel := Ability()
	wis := Ability()
	cha := Ability()
	hp := 10 + Modifier(con)
	return Character{
		Strength:     str,
		Dexterity:    dex,
		Constitution: con,
		Intelligence: intel,
		Wisdom:       wis,
		Charisma:     cha,
		Hitpoints:    hp,
	}
}
