package ledger

import (
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
	"time"
)

type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

// localeConfig holds locale-specific formatting details
type localeConfig struct {
	HeaderDate        string
	HeaderDescription string
	HeaderChange      string
	DateFormat        string // Go time format
	DateLayout        string // Input layout
	DescWidth         int
	CurrencyFmt       func(currency string, amount int) (string, error)
}

var localeConfigs = map[string]localeConfig{
	"en-US": {
		HeaderDate:        "Date",
		HeaderDescription: "Description",
		HeaderChange:      "Change",
		DateFormat:        "01/02/2006",
		DateLayout:        "2006-01-02",
		DescWidth:         25,
		CurrencyFmt:       formatCurrencyEN,
	},
	"nl-NL": {
		HeaderDate:        "Datum",
		HeaderDescription: "Omschrijving",
		HeaderChange:      "Verandering",
		DateFormat:        "02-01-2006",
		DateLayout:        "2006-01-02",
		DescWidth:         25,
		CurrencyFmt:       formatCurrencyNL,
	},
}

func isSupportedCurrency(currency string) bool {
	return currency == "USD" || currency == "EUR"
}

func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	cfg, ok := localeConfigs[locale]
	if !ok {
		return "", errors.New("unsupported locale")
	}

	// Check for supported currency
	if !isSupportedCurrency(currency) {
		return "", errors.New("unsupported currency")
	}

	// Defensive copy
	entriesCopy := make([]Entry, len(entries))
	copy(entriesCopy, entries)

	// Sort entries
	sort.SliceStable(entriesCopy, func(i, j int) bool {
		// Parse dates
		ti, erri := time.Parse(cfg.DateLayout, entriesCopy[i].Date)
		tj, errj := time.Parse(cfg.DateLayout, entriesCopy[j].Date)
		if erri != nil || errj != nil {
			// Fallback to string compare if date parse fails
			if entriesCopy[i].Date != entriesCopy[j].Date {
				return entriesCopy[i].Date < entriesCopy[j].Date
			}
		} else if !ti.Equal(tj) {
			return ti.Before(tj)
		}
		// Then by description
		if entriesCopy[i].Description != entriesCopy[j].Description {
			return entriesCopy[i].Description < entriesCopy[j].Description
		}
		// Then by change
		return entriesCopy[i].Change < entriesCopy[j].Change
	})

	// Header
	header := fmt.Sprintf("%-*s | %-*s | %s\n",
		10, cfg.HeaderDate,
		cfg.DescWidth, cfg.HeaderDescription,
		cfg.HeaderChange,
	)

	var sb strings.Builder
	sb.WriteString(header)

	for _, entry := range entriesCopy {
		// Validate date
		date, err := time.Parse(cfg.DateLayout, entry.Date)
		if err != nil {
			return "", errors.New("invalid date format")
		}
		dateStr := date.Format(cfg.DateFormat)

		// Description
		desc := entry.Description
		if len(desc) > cfg.DescWidth {
			desc = desc[:cfg.DescWidth-3] + "..."
		}
		desc = fmt.Sprintf("%-*s", cfg.DescWidth, desc)

		// Change
		changeStr, err := cfg.CurrencyFmt(currency, entry.Change)
		if err != nil {
			return "", err
		}

		// Compose line
		line := fmt.Sprintf("%-*s | %s | %13s\n", 10, dateStr, desc, changeStr)
		sb.WriteString(line)
	}

	return sb.String(), nil
}

// formatCurrencyEN formats currency for en-US locale
func formatCurrencyEN(currency string, amount int) (string, error) {
	var symbol string
	switch currency {
	case "USD":
		symbol = "$"
	case "EUR":
		symbol = "€"
	default:
		return "", errors.New("unsupported currency")
	}

	negative := amount < 0
	if negative {
		amount = -amount
	}

	dollars := amount / 100
	cents := amount % 100

	// Add thousands separator
	dollarStr := strconv.Itoa(dollars)
	var parts []string
	for len(dollarStr) > 3 {
		parts = append([]string{dollarStr[len(dollarStr)-3:]}, parts...)
		dollarStr = dollarStr[:len(dollarStr)-3]
	}
	if len(dollarStr) > 0 {
		parts = append([]string{dollarStr}, parts...)
	}
	intPart := strings.Join(parts, ",")

	amountStr := fmt.Sprintf("%s%s.%02d", symbol, intPart, cents)
	if negative {
		amountStr = "(" + amountStr + ")"
	} else {
		amountStr += " "
	}
	return amountStr, nil
}

// formatCurrencyNL formats currency for nl-NL locale
func formatCurrencyNL(currency string, amount int) (string, error) {
	var symbol string
	switch currency {
	case "USD":
		symbol = "$"
	case "EUR":
		symbol = "€"
	default:
		return "", errors.New("unsupported currency")
	}

	negative := amount < 0
	if negative {
		amount = -amount
	}

	euros := amount / 100
	cents := amount % 100

	// Add thousands separator (dot)
	euroStr := strconv.Itoa(euros)
	var parts []string
	for len(euroStr) > 3 {
		parts = append([]string{euroStr[len(euroStr)-3:]}, parts...)
		euroStr = euroStr[:len(euroStr)-3]
	}
	if len(euroStr) > 0 {
		parts = append([]string{euroStr}, parts...)
	}
	intPart := strings.Join(parts, ".")

	amountStr := fmt.Sprintf("%s %s,%02d", symbol, intPart, cents)
	if negative {
		amountStr += "-"
	} else {
		amountStr += " "
	}
	return amountStr, nil
}
