var (
	ones = []string{
		"zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
		"ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen",
	}
	tens = []string{
		"", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety",
	}
	scales = []string{
		"", "thousand", "million", "billion", "trillion",
	}
	maxNumber int64 = 999999999999
	minNumber int64 = 0
)

func Say(n int64) (string, bool) {
	if n < minNumber || n > maxNumber {
		return "", false
	}
	if n < 100 {
		return sayDoubleDigit(n), true
	}
	parts := splitThousands(n)
	words := []string{}
	for i := len(parts) - 1; i >= 0; i-- {
		part := parts[i]
		if part == 0 {
			continue
		}
		chunk := sayChunk(part)
		scale := scales[i]
		if scale != "" {
			words = append(words, chunk+" "+scale)
		} else {
			words = append(words, chunk)
		}
	}
	return strings.Join(words, " "), true
}

func sayDoubleDigit(n int64) string {
	if n < 20 {
		return ones[n]
	}
	t := n / 10
	u := n % 10
	if u == 0 {
		return tens[t]
	}
	return tens[t] + "-" + ones[u]
}

func sayChunk(n int64) string {
	if n == 0 {
		return ""
	}
	if n < 100 {
		return sayDoubleDigit(n)
	}
	h := n / 100
	r := n % 100
	if r == 0 {
		return ones[h] + " hundred"
	}
	return ones[h] + " hundred " + sayDoubleDigit(r)
}

func splitThousands(n int64) []int64 {
	parts := []int64{}
	for {
		parts = append(parts, n%1000)
		n /= 1000
		if n == 0 {
			break
		}
	}
	return parts
}
