	return "", nil
}

func parseBoard(lines []string) [][]player {
	board := make([][]player, len(lines))
	for i, line := range lines {
		trimmed := strings.TrimLeft(line, " ")
		row := make([]player, len(trimmed))
		for j, ch := range trimmed {
			row[j] = player(ch)
		}
		board[i] = row
	}
	return board
}

func hasPath(board [][]player, p player, rows, cols int) bool {
	visited := make([][]bool, rows)
	for i := range visited {
		visited[i] = make([]bool, cols)
	}

	var stack []pos

	if p == O {
		// O: top to bottom
		for c := 0; c < cols; c++ {
			if board[0][c] == O {
				stack = append(stack, pos{0, c})
				visited[0][c] = true
			}
		}
		for len(stack) > 0 {
			cur := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			if cur.r == rows-1 {
				return true
			}
			for _, n := range neighbors(cur, rows, cols) {
				if !visited[n.r][n.c] && board[n.r][n.c] == O {
					visited[n.r][n.c] = true
					stack = append(stack, n)
				}
			}
		}
	} else if p == X {
		// X: left to right
		for r := 0; r < rows; r++ {
			if board[r][0] == X {
				stack = append(stack, pos{r, 0})
				visited[r][0] = true
			}
		}
		for len(stack) > 0 {
			cur := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			if cur.c == cols-1 {
				return true
			}
			for _, n := range neighbors(cur, rows, cols) {
				if !visited[n.r][n.c] && board[n.r][n.c] == X {
					visited[n.r][n.c] = true
					stack = append(stack, n)
				}
			}
		}
	}
	return false
}

// Hex grid neighbors (6 directions)
var directions = []pos{
	{-1, 0},  // up
	{-1, 1},  // up-right
	{0, -1},  // left
	{0, 1},   // right
	{1, -1},  // down-left
	{1, 0},   // down
}

func neighbors(p pos, rows, cols int) []pos {
	var nbs []pos
	for _, d := range directions {
		nr, nc := p.r+d.r, p.c+d.c
		if nr >= 0 && nr < rows && nc >= 0 && nc < cols {
			nbs = append(nbs, pos{nr, nc})
		}
	}
	return nbs
}
