package palindrome

import (
	"errors"
	"sort"
	"strconv"
)

// Product represents a palindrome product and its factor pairs.
type Product struct {
	Product        int
	Factorizations [][2]int
}

// isPalindrome checks if a number is a palindrome.
func isPalindrome(n int) bool {
	s := strconv.Itoa(n)
	for i := 0; i < len(s)/2; i++ {
		if s[i] != s[len(s)-1-i] {
			return false
		}
	}
	return true
}

// Products finds the smallest and largest palindrome products and their factors in the given range.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, errors.New("fmin > fmax")
	}

	palindromes := make(map[int][][2]int)

	for i := fmin; i <= fmax; i++ {
		for j := i; j <= fmax; j++ {
			prod := i * j
			if isPalindrome(prod) {
				palindromes[prod] = append(palindromes[prod], [2]int{i, j})
			}
		}
	}

	if len(palindromes) == 0 {
		return Product{}, Product{}, errors.New("no palindromes found")
	}

	// Collect and sort all palindrome products
	keys := make([]int, 0, len(palindromes))
	for k := range palindromes {
		keys = append(keys, k)
	}
	sort.Ints(keys)

	smallest := keys[0]
	largest := keys[len(keys)-1]

	return Product{Product: smallest, Factorizations: palindromes[smallest]},
		Product{Product: largest, Factorizations: palindromes[largest]},
		nil
}
