import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;

class BaseConverter {

    private final int originalBase;
    private final int[] originalDigits;
    private final BigInteger value;

    BaseConverter(int originalBase, int[] originalDigits) {
        // Validate original base
        if (originalBase < 2) {
            throw new IllegalArgumentException("Bases must be at least 2.");
        }

        // Validate digits array reference (it may be empty but not null)
        if (originalDigits == null) {
            throw new IllegalArgumentException("Digits cannot be null.");
        }

        // Validate every digit that was supplied (if any)
        for (int digit : originalDigits) {
            if (digit < 0) {
                throw new IllegalArgumentException("Digits may not be negative.");
            }
            if (digit >= originalBase) {
                throw new IllegalArgumentException("All digits must be strictly less than the base.");
            }
        }

        this.originalBase = originalBase;
        this.originalDigits = originalDigits.clone();

        /*
         * Pre-compute the numeric value in a safe type (BigInteger).
         * If no digits were supplied, or if all digits are zero, the value is zero.
         */
        BigInteger total = BigInteger.ZERO;
        BigInteger baseBI = BigInteger.valueOf(originalBase);
        for (int digit : this.originalDigits) {
            total = total.multiply(baseBI).add(BigInteger.valueOf(digit));
        }
        this.value = total;
    }

    int[] convertToBase(int newBase) {
        if (newBase < 2) {
            throw new IllegalArgumentException("Bases must be at least 2.");
        }

        // Special case for zero (covers empty digit list and any representation equal to zero)
        if (value.equals(BigInteger.ZERO)) {
            return new int[] { 0 };
        }

        List<Integer> digitsReversed = new ArrayList<>();
        BigInteger baseBI = BigInteger.valueOf(newBase);
        BigInteger remaining = value;

        // Repeated division to obtain digits (least significant first)
        while (remaining.compareTo(BigInteger.ZERO) > 0) {
            BigInteger[] divMod = remaining.divideAndRemainder(baseBI);
            digitsReversed.add(divMod[1].intValue());
            remaining = divMod[0];
        }

        // Reverse the list to get the correct order
        int[] result = new int[digitsReversed.size()];
        for (int i = 0; i < digitsReversed.size(); i++) {
            result[i] = digitsReversed.get(digitsReversed.size() - 1 - i);
        }
        return result;
    }
}
