import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class ProteinTranslator {

    private static final Map<String, String> CODON_PROTEIN_MAP = createCodonProteinMap();

    private static Map<String, String> createCodonProteinMap() {
        Map<String, String> map = new HashMap<>();

        map.put("AUG", "Methionine");

        map.put("UUU", "Phenylalanine");
        map.put("UUC", "Phenylalanine");

        map.put("UUA", "Leucine");
        map.put("UUG", "Leucine");

        map.put("UCU", "Serine");
        map.put("UCC", "Serine");
        map.put("UCA", "Serine");
        map.put("UCG", "Serine");

        map.put("UAU", "Tyrosine");
        map.put("UAC", "Tyrosine");

        map.put("UGU", "Cysteine");
        map.put("UGC", "Cysteine");

        map.put("UGG", "Tryptophan");

        map.put("UAA", "STOP");
        map.put("UAG", "STOP");
        map.put("UGA", "STOP");

        return map;
    }

    List<String> translate(String rnaSequence) {
        if (rnaSequence == null || rnaSequence.isEmpty()) {
            return Collections.emptyList();
        }

        List<String> proteins = new ArrayList<>();
        int length = rnaSequence.length();
        boolean stopEncountered = false;
        int i = 0;

        for (; i + 3 <= length; i += 3) {
            String codon = rnaSequence.substring(i, i + 3);
            String protein = CODON_PROTEIN_MAP.get(codon);

            if (protein == null) {
                throw new IllegalArgumentException("Invalid codon");
            }

            if ("STOP".equals(protein)) {
                stopEncountered = true;
                break;
            }

            proteins.add(protein);
        }

        // If there are leftover nucleotides that are not part of a complete codon
        // and we did not stop because of a STOP codon, the sequence is invalid.
        if (!stopEncountered && i < length) {
            throw new IllegalArgumentException("Invalid codon");
        }

        return proteins;
    }
}
