    frequency_map global_freq;
    std::mutex    global_mutex;

    // Process each text element (potentially) in parallel.
    std::for_each(std::execution::par, texts.begin(), texts.end(),
                  [&](std::string_view text) {
                      frequency_map local_freq;

                      // Local frequency count for the current text.
                      for (char ch : text) {
                          unsigned char uch = static_cast<unsigned char>(ch);
                          if (std::isalpha(uch)) {
                              char lower = static_cast<char>(std::tolower(uch));
                              ++local_freq[lower];
                          }
                      }

                      // Merge the local result into the shared result.
                      if (!local_freq.empty()) {
                          std::scoped_lock lock(global_mutex);
                          for (const auto& [letter, count] : local_freq) {
                              global_freq[letter] += count;
                          }
                      }
                  });

    return global_freq;
}

} // namespace parallel_letter_frequency
