package linkedlist

import "errors"

// Element represents a single node in the singly linked list.
type Element struct {
	value int
	next  *Element
}

// List represents a singly linked list.
type List struct {
	head *Element
	size int
}

// New creates a new list from the supplied slice.
// The order of elements in the list matches the order of the slice,
// so the first slice element becomes the head of the list.
func New(elements []int) *List {
	l := &List{}
	for _, v := range elements {
		l.Push(v)
	}
	return l
}

// Size returns the number of elements currently in the list.
func (l *List) Size() int {
	if l == nil {
		return 0
	}
	return l.size
}

// Push appends a new element containing the given value to the tail
// of the list.
func (l *List) Push(element int) {
	if l == nil {
		return
	}

	e := &Element{value: element}

	// If the list is empty, new element becomes the head.
	if l.head == nil {
		l.head = e
		l.size = 1
		return
	}

	// Otherwise traverse to the last element and append.
	current := l.head
	for current.next != nil {
		current = current.next
	}
	current.next = e
	l.size++
}

// Pop removes the element at the tail of the list and returns its value.
// If the list is empty, an error is returned.
func (l *List) Pop() (int, error) {
	if l == nil || l.head == nil {
		return 0, errors.New("cannot pop from an empty list")
	}

	// If there's only one element.
	if l.head.next == nil {
		value := l.head.value
		l.head = nil
		l.size = 0
		return value, nil
	}

	// Traverse to the penultimate element.
	prev := l.head
	for prev.next.next != nil {
		prev = prev.next
	}

	value := prev.next.value
	prev.next = nil
	l.size--
	return value, nil
}

// Array converts the list into a slice with the same ordering
// as the elements appear in the list from head to tail.
func (l *List) Array() []int {
	if l == nil || l.head == nil {
		return []int{}
	}
	arr := make([]int, 0, l.size)
	for current := l.head; current != nil; current = current.next {
		arr = append(arr, current.value)
	}
	return arr
}

// Reverse creates a new list containing the elements of the current
// list in the opposite order. The original list is left unmodified.
func (l *List) Reverse() *List {
	reversed := &List{}
	for current := l.head; current != nil; current = current.next {
		// Insert at the head of the reversed list to invert the order.
		reversed.head = &Element{
			value: current.value,
			next:  reversed.head,
		}
		reversed.size++
	}
	return reversed
}
