package octal

import "errors"

// ParseOctal converts a string representing an octal (base-8) number to its
// decimal (base-10) equivalent.
//
// The function walks through the input string from left to right, ensuring each
// rune is a valid octal digit ('0'–'7'). For every digit it multiplies the
// running total by 8 (shifting one place to the left in base-8) and adds the
// digit’s value.
//
// If the input contains any character outside the range '0'–'7', the function
// returns 0 and a non-nil error, treating the entire input as the octal value 0
// as required by the exercise.
func ParseOctal(input string) (int64, error) {
	if input == "" {
		// Treat empty input as 0 with no error.
		return 0, nil
	}

	var total int64
	for _, r := range input {
		if r < '0' || r > '7' {
			return 0, errors.New("invalid digit in octal string")
		}
		total = total*8 + int64(r-'0')
	}

	return total, nil
}
