#include "sublist.h"

#include <algorithm>  // for std::search

namespace sublist {

// Helper to determine whether `sub` is a contiguous subsequence of `super`
static bool is_sublist(const std::vector<int>& sub,
                       const std::vector<int>& super) {
    if (sub.empty()) {
        return true;  // The empty list is a sublist of any list.
    }
    if (sub.size() > super.size()) {
        return false; // Can't be a sublist if it's longer.
    }

    auto it = std::search(super.begin(), super.end(), sub.begin(), sub.end());
    return it != super.end();
}

result_t check_lists(const std::vector<int>& list_a,
                     const std::vector<int>& list_b) {
    if (list_a == list_b) {
        return result_t::equal;
    }
    if (is_sublist(list_a, list_b)) {
        return result_t::sublist;
    }
    if (is_sublist(list_b, list_a)) {
        return result_t::superlist;
    }
    return result_t::unequal;
}

}  // namespace sublist
