package matrix

import (
	"errors"
	"strconv"
	"strings"
)

// Matrix represents a two-dimensional slice of integers.
type Matrix [][]int

// New constructs a Matrix from a string representation.
// The string should contain rows separated by newlines and
// columns separated by spaces. All rows must have the same
// number of columns, and every entry must be a valid integer.
//
// The function is intentionally strict:
//   • Leading or trailing new-lines are NOT ignored; they are treated as
//     empty rows and will trigger an error.
//   • Likewise, any empty line inside the string will trigger an error.
func New(s string) (Matrix, error) {
	// If the string is only white-space, reject it immediately.
	if strings.TrimSpace(s) == "" {
		return nil, errors.New("input string is empty")
	}

	lines := strings.Split(s, "\n")
	var mat Matrix
	expectedCols := -1

	for _, line := range lines {
		fields := strings.Fields(line)

		// Reject empty rows (e.g., leading/trailing or multiple consecutive new-lines).
		if len(fields) == 0 {
			return nil, errors.New("row is empty or contains no numbers")
		}

		// Establish expected column count based on first row.
		if expectedCols == -1 {
			expectedCols = len(fields)
		}

		// Ensure each row has the same number of columns.
		if len(fields) != expectedCols {
			return nil, errors.New("inconsistent row length")
		}

		row := make([]int, expectedCols)
		for i, f := range fields {
			n, err := strconv.Atoi(f)
			if err != nil {
				return nil, err
			}
			row[i] = n
		}
		mat = append(mat, row)
	}

	return mat, nil
}

// Cols returns a copy of the matrix's columns.
func (m Matrix) Cols() [][]int {
	if len(m) == 0 {
		return [][]int{}
	}

	numRows := len(m)
	numCols := len(m[0])
	cols := make([][]int, numCols)

	for c := 0; c < numCols; c++ {
		col := make([]int, numRows)
		for r := 0; r < numRows; r++ {
			col[r] = m[r][c]
		}
		cols[c] = col
	}

	return cols
}

// Rows returns a copy of the matrix's rows.
func (m Matrix) Rows() [][]int {
	rows := make([][]int, len(m))
	for i := range m {
		rowCopy := make([]int, len(m[i]))
		copy(rowCopy, m[i])
		rows[i] = rowCopy
	}
	return rows
}

// Set sets the value at the specified row and column.
// It returns true if the operation was successful and false
// if the provided indices were out of bounds.
func (m Matrix) Set(row, col, val int) bool {
	if row < 0 || row >= len(m) {
		return false
	}
	if col < 0 || (len(m[row]) > 0 && col >= len(m[row])) {
		return false
	}
	m[row][col] = val
	return true
}
